quests[27544] = { id = 27544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarische Hartnäckigkeit", description = "Ich glaube, diese Druiden geben nie auf. Ich habe die Pestländer schon vor Jahren aufgegeben, aber diese Optimisten vom Zirkel des Cenarius behaupten, es gäbe noch Hoffnung für dieses Land.\n\nDie letzte Besucherin war eine Nachtelfe, die auf dem Weg nach Norden, ins Fungustal, war. Sie sagte, diese Länder würden sich vollständig erholen, wenn wir uns nur Mühe geben. Ich weiß nicht, ob ich das glauben soll.\n\nGlaubt Ihr diesen Unsinn?! Vielleicht solltet Ihr einmal mit ihr reden. Sie müsste immer noch dort oben sein.", sourceObjective = "Sprecht mit Rayne nahe des Eingangs zum Fungustal.", completion = "Wenn Ihr mich finden konntet, sollte ich wohl an meiner Verstohlenheit arbeiten.\n\nWollt Ihr mir bei der Heilung der Pestländer helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27545] = { id = 27545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg ist geöffnet", description = "Mein Schamanenfreund und ich werden hier bleiben, um das Portal aufrechtzuerhalten.\n\nIhr solltet nach oben gehen und Kurdran benachrichtigen, dass unsere Arbeit hier erledigt ist. Es wird ihn freuen, zur Abwechslung mal gute Nachrichten zu hören.", sourceObjective = "Sprecht mit Kurdran Wildhammer in Hochstade im Schattenhochland.", completion = "Ha! Ich wusste, dass Ihr ein {class} seid, auf den ich mich verlassen kann, {name}. Ihr könnt das Portal jederzeit benutzen, um von Sturmwind zurück ins Schattenhochland zu gelangen.\n\nUnd jetzt zum Geschäft. Wir müssen die verschollenen Wildhammerklans, die überall im Schattenhochland verstreut sind, finden und vereinen. Am besten sprecht Ihr zunächst mit Thordun hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27547] = { id = 27547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgenlos", description = "Unsere Streitkräfte in Lohenscheit wurden vor Kurzem durch einen Schleichangriff überrascht. Die 7. Legion hat es geschafft, ihre Späher in die Stadt einzuschleusen und schließlich unsere Truppen zu dezimieren.\n\nDie Dunkle Fürstin hat uns mit einer Rettungsmission beauftragt. Wir sollen Überlebende finden und sie sicher aus Lohenscheit herausbringen. Wenn noch Soldaten am Leben sind, so sind sie wahrscheinlich nutzlos, aber wir werden das tun, was die Dunkle Fürstin befiehlt.\n\nLasst uns diesen Unsinn hinter uns bringen, {name}. Lohenscheit ist direkt im Südwesten der Frontlinie der Verlassenen.", sourceObjective = "Rettet 8 kauernde Soldaten.", completion = "Was heute hier geschehen ist, bleibt unter uns. Nur ein Wort zu irgendjemandem und Ihr findet Euch in einer Leichengrube neben diesen armen Narren wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[27548] = { id = 27548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrstunden in Angst", description = "Unsere Feinde werden immer schlauer und passen sich an unsere Strategien an. Erst vor Kurzem wurde Lohenscheit im Südwesten von hier angegriffen. Unsere Streitkräfte, die die Stadt besetzt halten, wurden natürlich dezimiert, aber was den Angriff besonders interessant macht, war die Völkerzusammensetzung der angreifenden Truppe. Es gab keine Menschen.\n\n<Walden lacht.>\n\nSie fürchten sich zu Recht davor, als Verlassene wiedererweckt zu werden.\n\nLasst uns den Nicht-Menschen eine Lektion in Angst erteilen. Zusammen werden wir ihnen zeigen, was mit Leichen geschieht, für die wir keine Verwendung haben.", sourceObjective = "Tötet 12 Späher der 7. Legion.", completion = "Ich nehme an, dass wir jetzt weniger Menschen an der Schlachtenfront sehen werden. Das Risiko für diese Feiglinge ist zu groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[27549] = { id = 27549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Sternenlicht", description = "Schaut Euch das an, {name}.\n\n<Harrison hält die Brille des toten Spähers hoch.>\n\nIch habe die Klammer in der Mitte angezogen und die Drähte an den Kanten etwas gezwirbelt. Sie mag nicht bequem sein, aber sie sollte halten.\n\nWenn ich Eure Schrifttafeln richtig übersetzt habe, ist hier etwas versteckt - ein letztes Teil für unser Puzzle.\n\nIch hoffe, Eure Brille birgt den Schlüssel.\n\nLasst mich wissen, was Ihr findet!", sourceObjective = "Sammelt 7 schwebende Sternenlichter.", progress = "Und?\n\nHabt Ihr etwas Interessantes gefunden?", completion = "Nun, mein Junge, es sieht so aus, als ob Ihr es wieder geschafft habt.\n\n<Harrison zeigt auf ein Bild auf den Schrifttafeln.>\n\nDieses Sternenlicht ist genau das, was gefehlt hat.\n\nJetzt können wir an die Arbeit gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27550] = { id = 27550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohenscheits Fall", description = "Die Angriffe gegen unsere Front sind ein Ablenkungsmanöver. Da unsere Aufmerksamkeit dem Ansturm der Worgen galt, hat die Allianz es geschafft, Lohenscheit von unseren Besatzungstruppen zurückzuerobern.\n\n<Godfrey übergibt Euch ein Bündel Fackeln.>\n\nEs muss ausgelöscht werden.\n\nMit diesen Fackeln werden wir Lohenscheit bis auf die Grundmauern niederbrennen und nur Asche für den Feind hinterlassen, hinter der er sich verstecken kann.\n\nLasst uns keine weitere Minute vergeuden. Lohenscheit liegt südwestlich der Frontlinie der Verlassenen. Führt uns dorthin, {name}.", sourceObjective = "Benutzt das Bündel Fackeln, um das Rathaus von Lohenscheit, das Gasthaus von Lohenscheit und die Kapelle von Lohenscheit niederzubrennen.", progress = "Ich spüre keine Reue.", completion = "Der Teil von mir, der aus Gilneas stammte, starb an der Witterfront. Es bleibt nur Rache, {name}. Und in der Hinsicht haben wir noch einiges zu tun. Erspart mir Eure sinnlosen Fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27551] = { id = 27551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schreiben der Baroness", description = "Die Notiz stammt von Baroness Anastari. Darin beschreibt sie ein Ritual, das sehr bald auf dem mittleren Schlachthaus im Pestwald abgehalten werden soll - etwas südlich von Tarenars Aufenthaltsort. Vielleicht halten sie dort Gidwin fest!\n\nTarenar muss davon erfahren... und zwar rasch, bevor es zu spät ist!", sourceObjective = "Bringt Tarenar das Schreiben der Baroness.", progress = "Was? Habt Ihr etwas gefunden?", completion = "Das ist es! Wenn das, was in dem Schreiben steht, stimmt, dann ist er auf der anderen Seite des Hügels!\n\nWorauf warten wir noch, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27555] = { id = 27555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fionas Glücksbringer", sourceObjective = "Fiona hat ein paar ihrer Glücksbringer im Karawanenwagen gelassen.\n\nAls Händlerin kann sie ziemlich gut mit Geld umgehen. Vielleicht könnt Ihr Eure Finanzen verbessern, wenn Ihr einen ihrer Glücksbringer tragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27556] = { id = 27556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwins Waffenöl", sourceObjective = "Gidwin hat einige Flaschen Waffenöl im Karawanenwagen zurückgelassen.\n\nEr scheint im Nahkampf ein recht wilder Gegner zu sein. Vielleicht wird Euch sein Waffenöl ebenfalls gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27557] = { id = 27557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenars Talisman", sourceObjective = "Tarenar hat einige heilige Talismane im Karawanenwagen ausgelegt. Sie wirken unbenutzt.\n\nSie scheinen magischer Natur zu sein. Wenn Tarenar sie nicht benutzt, könnte es doch nicht schaden, sich einen für eine Weile auszuleihen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27558] = { id = 27558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamelas Puppe", sourceObjective = "Ihr findet eine kleine Puppe in der hinteren Ecke des Karawanenwagens.\n\nTarenar sagt, sie gehöre Gidwin und Gidwin sagt, es wäre wahrscheinlich Tarenars.", sourceObjectiveStatus = "unverified-source-field" }
quests[27559] = { id = 27559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vex'tuls Armbinden", sourceObjective = "Vex'tul hat einige Armbinden im Karawanenwagen zurückgelassen. Er war sogar so freundlich, sie zu falten und separat von den Habseligkeiten aller anderen aufzubewahren.\n\nVex'tul schätzt Stärke mehr als alles andere. Als Ihr Euch vorbeugt, spürt Ihr Überreste seiner Kraft, die aus den Armbinden strömt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27560] = { id = 27560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argus' Tagebuch", sourceObjective = "Ihr entdeckt ein verwittertes Tagebuch im Karawanenwagen. Das Emblem des Argentumkreuzzugs auf dem Buchrücken weist darauf hin, dass es Argus gehört.\n\nIn dem Tagebuch hat Argus einige seiner Erfahrungen während seiner Zeit beim Kreuzzug niedergeschrieben. Es sollte Euch interessanten Lesestoff auf der Reise bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27561] = { id = 27561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rimblats Stein" }
quests[27562] = { id = 27562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beezils Zahnrad", sourceObjective = "Beezil fühlt sich anscheinend schon wie zuhause. Er hat mehrere seltsame Apparate in den Karawanenwagen gestopft.\n\nDie meisten erscheinen Euch zu unpraktisch oder gefährlich, um sie mitzunehmen. Ein kleines Zahnrad sieht jedoch recht gut verarbeitet aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[27564] = { id = 27564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt das Refugium", description = "Calen hat uns benachrichtigt. Der Schattenhammer ist in das Refugium eingedrungen!\n\nWenn Ihr nach einer Gelegenheit sucht, um seine Gunst zu erlangen, dann ist dies der rechte Zeitpunkt!", sourceObjective = "Sprecht mit Calen im Zinnoberrefugium.", completion = "Ich hoffe, dass Ihr so hart im Nehmen seid, wie Eure Ausrüstung es verspricht. Der Schattenhammer hat irgendwie einen Weg in das Refugium gefunden. Ich brauche jemanden, der sie zur Strecke bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27565] = { id = 27565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Gefängnis", description = "Es ist uns gelungen, jemand in das Gefängnis der Dunkeleisenzwerge einzuschleusen.\n\nAlso... es ist uns möglicherweise gelungen.\n\nKevin Dawson hatte die... Ehre... nachzusehen, was dort drüben vor sich geht. Doch seitdem haben wir nichts mehr von ihm gehört. Ihr seht so aus, als ob Ihr nicht gerne sterbt. Ihr solltet nachschauen gehen, ob er in Ordnung ist!\n\nEr sollte eigentlich in der Halle am südlichen Ende der Höhle vor uns sein... Doch etwas sagt mir, dass er es vielleicht nicht bis dahin geschafft hat.", sourceObjective = "Findet Kevin Dawson.", completion = "Ich habe keine Ahnung, wieso ich noch am Leben bin. Die Patrouillen laufen an mir vorbei, als ob ich gar nicht hier wäre.\n\n...Bin ich tot, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27567] = { id = 27567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammer?! Nein!", description = "Es ist zwar schwer zu glauben, aber es gibt Mitglieder des Schattenhammers hier in den Schwarzfelstiefen! Ich weiß nicht, wie viele von ihnen durch diesen Ort kriechen, aber ich habe gehört, dass Ihre Verhörmeisterin Gerstahn in dieser Halle ist.\n\nIch weiß nicht, warum sie hier foltern, aber vielleicht könnt Ihr es herausfiniden, indem Ihr Gerstahn entgegentretet?", sourceObjective = "\"Verhört\" Verhörmeisterin Gerstahn.", completion = "Hmm... wie ich sehe, war sie nicht hilfsbereit. Hoffentlich können wir sie noch aufhalten, bevor etwas Furchtbares geschieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27568] = { id = 27568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschmiede unterwandern", description = "Könnt Ihr ein Geheimnis für Euch behalten? Ich hab' ein Geheimnis, das ich mit Euch teilen will.\n\nHier sind alle VERRÜCKT!!!\n\nDa drüben sind Goblins, dort sind Dunkeleisenzwerge und ein riesiges lebendes Feuer hinter dem Tor da! Und das ist nur das, was ich in dieser kleinen Höhle sehe!\n\nUnd Euch! Was macht Ihr hier?\n\nAh, ich verstehe. Winky hat Euch geschickt, nicht wahr? Hat Euch geschickt, um mit Ausgrabungsleiter Seymour zu sprechen, der hinter diesem Tor gleich rechts ist, nicht wahr? Dann geht! Oralius kümmert das nicht!\n\n...DAS WERDE ICH DIR HEIMZAHLEN WINKY!!!\n\n<Oralius fängt an zu schluchzen.>", sourceObjective = "Sprecht mit Ausgrabungsleiter Seymour.", completion = "Ich würde mich von Oralius fern halten. Sehr, sehr weit fern halten. Er ist nicht ganz richtig im Kopf.\n\nAber zurück zum Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27569] = { id = 27569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategen der Dunkeleisenzwerge", description = "General Zornesschmied und Golemlord Argelmach führen die Armeen der Dunkeleisenzwerge und ihre Golems gegen uns. Wenn wir sie überwinden wollen, müssen die beiden getötet werden.\n\nGeht durch diese Tür und schließt das Schloss der Schattenschmiede auf, die die Ost- und Westgarnisonen trennt. Dann folgt der Treppe und haltet Euch oben links, bis Ihr die Westgarnison erreicht. Dort findet Ihr den General und den Golemlord.\n\nBleibt immer wachsam, da beide äußerst erfahrene Kämpfer sind. Wenn Ihr erfolgreich seid, sucht Mayara Wolkenglanz.", sourceObjective = "Tötet General Zornesschmied und Golemlord Argelmach.", completion = "Ich bin sicher, dass Ihr der Aufgabe gewachsen seid, die ich für Euch habe, wenn Ihr es unversehrt bis hierher geschafft habt.\n\n<Mayara Wolkenglanz flüstert ganz leise.>\n\nUnter uns gesagt - Ihr solltet Euch während Eures Aufenthaltes hier ein wenig im \"Grimmigen Säufer\" vergnügen. Es könnte Euer letztes Getränk sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27571] = { id = 27571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Grimmige Säufer", description = "Es gibt Stimmen, die behaupten, dass der \"Grimmige Säufer\" das Geheimnis der Kriegsanstrengungen der Dunkeleisenzwerge ist. Ihre Krieger erholen sich dort und kommen durstig nach einer weiteren unschuldigen Seele wieder heraus. Ich glaube, wir können sie erheblich behindern, indem wir dort ein wenig Chaos anrichten.\n\nIhr müsst einen Streit mit drei der berüchtigten Stammkunden anfangen. Beschädigt die Fässer und Hurley Pestatem wird herbeieilen. Stehlt die Gegenstände vom Tisch in der Nähe von Stöpsel Zapfring und er wird kämpfen. Was Ribbly Schraubstutz angeht - mit dem Hitzkopf müsst Ihr nur reden. Meldet Euch bei Orfus, wenn Ihr fertig seid.", sourceObjective = "Kämpft gegen Hurley Pestatem, Stöpsel Zapfring und Ribbly Schraubstutz.", progress = "Beeilt Euch bitte. Zeit ist ein Luxus, den wir nicht haben.", completion = "Die Dunkeleisenzwerge haben unser Donnerbräu gestohlen. Nach dieser Tat kann ich sie nicht am Leben lassen. Wenn ich könnte, würde ich sie alle höchstpersönlich töten!\n\nWenn Ihr allerdings nach vorne schaut, werdet Ihr sehen, dass wir uns im Moment um dringendere Dinge zu kümmern haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27573] = { id = 27573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pakt mit den Dunkeleisenzwergen", description = "Vor uns befindet sich die Kreatur, die nur als Botschafter Flammenschlag bekannt ist. Er ist der Botschafter von Ragnaros dem Feuerlord und vertritt ihn beim Volk der Dunkeleisenzwerge. Jenseits dieser Kammer befindet sich die Gruft der Beschwörer. Dort sind die Geister der sieben Patriarchen der Dunkeleisenzwerge zu Hause, die Ragnaros in unsere Welt gerufen haben.\n\nMöglicherweise habt Ihr noch nichts von dem großen Feuer gehört, aber er bedeutet das Ende für Azeroth, wenn er nicht aufgehalten wird. Diese Individuen stehen in direkter Verbindung zu der Macht, die er über die Dunkeleisenzwerge hat. Tötet sie, damit dieses Volk eines Tages vielleicht rehabilitiert werden kann.", sourceObjective = "Tötet Botschafter Flammenschlag und Un'rel.", completion = "Ich kann alleine nicht weitermachen, egal, wie viel Kampferfahrung ich habe. Das Lyzeum hat sich als zu schwer für mich erwiesen. Doch da Ihr hier seid... Ihr könntet der Schlüssel zu all dem hier sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27574] = { id = 27574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich vergesse nie ein Gesicht", description = "Ihr habt einen teilweise verdauten Kopf gefunden. Lord Godfrey wird aufmerksam, als er ihn sieht. Vielleicht solltet Ihr ihm den Kopf geben.", sourceObjective = "Übergebt den teilweise verdauten Kopf an Lord Godfrey im Silberwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[27575] = { id = 27575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Bauch der Bestie", description = "Ich glaube, dass wir ihn wiederherstellen können. Wenn es uns gelingt, ihn wieder zusammenzusetzen, kann er uns vielleicht Informationen über Crowley geben.\n\nWir müssen jeden Krokilisken im Sumpf töten, bis wir den Rest von Sean Dempseys Leiche gefunden haben. Aus dem Bauch des Ungeheuers wird dieser Mensch wiedergeboren!", sourceObjective = "Findet Dempseys Torso, Dempseys Gliedmaßen und Dempseys Eingeweide.", sourceObjectiveStatus = "unverified-source-field" }
quests[27576] = { id = 27576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickwerkbefehle", description = "Die kürzlichen Ereignisse machen mehr als deutlich, dass sich hier zu verkriechen und ab und zu einmal Grim Batol anzugreifen weder ausreicht, um Unsereins zu beschützen, noch um Grim Batol zurückzuerobern. Wir müssen aggressiver vorgehen und sie direkt ins Herz treffen.\n\nIch habe mich bereit erklärt, ein paar Drachen zur Unterstützung Eurer Kommandanten zu schicken. Sie waren bereits dabei, einen Angriffsplan für Grim Batol zu schmieden, also solltet Ihr Euch zunächst darauf konzentrieren.\n\nSucht nach Flick am Drachenmalpass, südlich in der Schlucht unter uns.", sourceObjective = "Sprecht mit Flick im Drachenmalpass.", completion = "Ihr habt die Drachen mit ins Spiel gebracht! Gut gemacht.\n\nUnsere Pläne waren bereits geschmiedet, als wir von den Drachen gehört haben. Sie helfen uns, indem sie die Rückzugrouten des Feindes abschneiden.\n\nEs ist noch nicht zu spät für Euch, an dem Spaß teilzuhaben. Wir haben ein Bisschen für Euch aufgehoben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27577] = { id = 27577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtpläne der 7. Legion", description = "Lohenscheit zu vernichten verschafft uns auf dem Schlachtfeld sicher einen Vorteil gegenüber der Allianz, doch unser wahres Ziel hier ist es, sie geschlagen zurückzulassen.\n\nSüdwestlich von hier, in der Nähe des Graumähnenwalls, liegt das Basislager der 7. Legion. Wir müssen dieses Basislager nach Schlachtplänen durchsuchen. Mit den Schlachtplänen der 7. Legion können wir die Truppenbewegung der Allianz im Silberwald genau nachverfolgen.", sourceObjective = "Besorgt Euch den Schlachtplan der 7. Legion.", progress = "Durchsucht jeden ranzigen Zwergenleichnam.", completion = "<Walden überfliegt den Schlachtplan.>\n\nSieht aus, als setzte die Verstärkung von den Schiffen in Gilneas sich bald in Bewegung. Crowley und Blutfang haben im Südosten ein Lager der Gilnearischen Befreiungsfront eingerichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27578] = { id = 27578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgans Verwirklichung", description = "Imperator Dagran Thaurissan übt von seinem Thron vor uns die absolute Kontrolle über die Stadt aus.. Wenn wir seine Armeen aufhalten wollen, müssen wir die Herrschaft des Imperators beenden.\n\nIhr müsst an seiner Leibwache - einschließlich des riesigen Magmus - vorbei, um an ihn heranzukommen. Bewegt Euch so schnell wie möglich. Wenn sich die Nachricht verbreitet, bevor Ihr fertig seid, wird die ganze Stadt zu seinem Thron eilen.\n\nDenkt daran, die Türen im Lyzeum öffnen sich nur, wenn Ihr die Kohlenpfannen mit Fackeln der Flammenbewahrer angezündet habt. Viel Glück.", sourceObjective = "Tötet Imperator Dagran Thaurissan.", completion = "Ihr habt es geschafft! Ihr habt es wirklich geschafft! All die Jahre, die Morgan Pläne geschmiedet und gewartet hat, haben endlich Früchte getragen.\n\nSie hat zwar ihr Land und ihre Familie verloren, als Ragnaros das Land entzwei riss, aber jetzt, da die Dunkeleisenzwerge angeschlagen sind, werden wir gefahrlos ein neues Königreich in der Brennenden Steppe aufbauen können. Nicht einmal der Feuerlord selbst wird in der Lage sein, die Mauern der Hauptstadt zu durchbrechen!\n\nIhr müsst unbedingt eines Tages, wenn wir fertig sind, zurückkommen. Ihr werdet unser höchster Ehrengast sein. Ich danke Euch von ganzem Herzen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27579] = { id = 27579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Gefängnis", description = "Der Schattenhammer wird 'nen Grund für seine Anwesenheit hier haben. Wir ha'm keine Ahnung, wieso, aber Thal'trak verrät Euch eins unserer kleinen Geheimnisse: Der Schurke Lexlort wartet vor der Halle von Verhörmeisterin Gerstahn, um sie abzumurksen, wenn er 'ne Chance dazu bekommt.\n\nSie is' aber zu clever dafür, als müsst Ihr da reingehen un' das erledigen, ya? Geht und sprecht mit Lexlort und sagt ihm Bescheid. Ich bin sicher, er wird damit einverstanden sein.", sourceObjective = "Findet Lexlort.", completion = "Kommt hier rüber. Wenn Ihr meine Tarnung auffliegen lasst, dann schwöre ich beim Kriegshäuptling, dass ich Euch auf der Stelle töten werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27580] = { id = 27580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfrieden säen", description = "Die Verstärkung der Allianz hat eine Stellung in der südwestlichen Region des Silberwalds etabliert - das Basislager der 7. Legion. Für uns hat es oberste Priorität, in diesem Basislager Unfrieden unter den Truppen zu säen. Die Mission ist ein blitzschnelles Attentat auf ihren Feldkommandanten, General Marstein. Sein Tod wird den Vormarsch der Allianz nicht aufhalten, aber er wird ihre Ränge aufweichen.", sourceObjective = "Ermordet General Marstein.", completion = "Der Rest der Allianzflotte wird bald eintreffen und ihr Basislager dezimiert vorfinden. Und jetzt kommen wir zum zweiten und wichtigsten Teil unseres Schlachtplans.", sourceObjectiveStatus = "unverified-source-field" }
quests[27581] = { id = 27581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammer?! Nein!", description = "Gerstahn ist viel zu schwer bewacht. Außerdem ist sie viel zu schlau, um ihren Posten zu verlassen. Also werde ich sie nicht töten.\n\nIhr werdet es tun.\n\nIch werfe auch noch etwas, das ich einer Wache abgenommen habe, mit in die Waagschale, damit es die Mühe für Euch wert ist.", sourceObjective = "Tötet Verhörmeisterin Gerstahn.", completion = "Die Anwesenheit des Schattenhammers macht unsere Aufgabe hier nur noch komplizierter. Doch Ihr habt Euren Teil für den Moment getan. Ihr habt eine Belohnung für Eure Bemühungen verdient... und ein wenig Ruhe. Lasst uns hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27582] = { id = 27582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschmiede unterwandern", description = "Ich fürchte, wir kämpfen momentan auf verlorenem Posten. Es wäre schon schwierig genug, die Dunkeleisenzwerge allein zu besiegen, aber ihre Elementarverbündeten haben ihnen nagelneue Krieger verschafft, mit denen wir nicht mithalten können.\n\nIhr müsst uns helfen, ihren Bereich zu infiltrieren und so viele ihrer wichtigen Anführer wie möglich zu töten. Das wird hoffentlich ihren Streitkräften einen Schock versetzen und das Blatt zu unseren Gunsten wenden. Meldet Euch bei Razal'hieb für weitere Anweisungen. Er ist jenseits dieses Tors auf der rechten Seite stationiert.", sourceObjective = "Sprecht mit Razal'hieb.", completion = "Hinter dieser Tür liegt der Kommandant der Armee der Dunkeleisenzwerge, umgeben von ausgebildeten Soldaten. Fühlt Ihr Euch gerüstet für ein kleines Gemetzel?", sourceObjectiveStatus = "unverified-source-field" }
quests[27583] = { id = 27583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nördliche Flanke", description = "Ich habe befohlen, dass ein Verteidigungsring an unserer nördlichen Küste bei der Wuchernden Bucht eingerichtet wird. Unsere Späher berichten, dass die Naga versucht haben, dort an Land zu gehen.\n\nGralok hat das Kommando über diese Operation. Meldet Euch bei ihm und sichert den Strand!", sourceObjective = "Meldet Euch bei Gralok in der Wuchernden Bucht im Schattenhochland.", completion = "Kriegsfürstin Zaela hat Euch geschickt? Gut.\n\nWenn Ihr von der Horde so stark seid, wie Eurer Kriegshäuptling behauptet, erwarte ich Unmengen vergossenen Blutes auf diesen Ufern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27584] = { id = 27584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutrote Brandung", description = "Dieser Nagaabschaum hat vor, den Fluss nach oben zu ziehen, um die Bastion des Zwielichts zu verstärken. Wir werden ihnen die Fischköpfe ABREISSEN und ihnen die GRÄTEN ZIEHEN.\n\n<Gralok rammt sein Breitschwert in den Boden.>\n\nVernichtet die Schwarzschuppen!", sourceObjective = "Tötet eine beliebige Kombination aus 15 Plünderern der Schwarzschuppen oder Herrinnen der Schwarzschuppen.", completion = "<Garlok mustert Euch.>\n\nIhr seid eine echte Kämpfernatur, {name}. Ich habe es genossen, Euch bei der Arbeit zu beobachten. Vielleicht gehört das Drachenmal ja doch zu Eurer Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27585] = { id = 27585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die 109te Division", description = "General Zornesschmied und Golemlord Argelmach sind direkt verantwortlich für das grässliche Abschlachten der 109ten Division des Kargath Expeditionskorps. In dieser Division waren eine Menge guter Trolle und Orcs - viele davon waren enge Freunde von mir.\n\nNun <junger/junge:r> {race}, es ist an der Zeit, unsere gefallenen Brüder endlich zu rächen.\n\nSchließt das Schloss der Schattenschmiede auf, dann folgt der Treppe und haltet Euch oben links, bis Ihr die Westgarnison erreicht. Tötet Zornesschmied und Argelmach und wagt es ja nicht, einem von ihnen Gnade zu erweisen.", sourceObjective = "Tötet General Zornesschmied und Golemlord Argelmach.", completion = "Genau vor uns liegt der \"Grimimge Säufer\". Eine schäbige Bar gefüllt mit unseren Feinden, die volltrunken und daher unfähig sind, zu kämpfen.\n\n<Hierophantin Theodora Mulvadania grinst.>\n\nReif zum Schlachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27586] = { id = 27586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombiger Badestrand", description = "Ich konnte diese Mörser aus unserem Luftschiff retten, als es über dem Hafen des Drachenmals explodierte. Doch Munition ist knapp.\n\nWährend Ihr am Strand entlang lauft, tut mir den Gefallen und sammelt alle Mörserblindgänger ein, die Ihr finden könnt.\n\nBlindgänger mag ich am allerliebsten. Man weiß nie, WANN sie losgehen. Die perfekte Überraschung für einen Feind.", sourceObjective = "Sammelt 8 Mörserblindgänger am Strand bei der Wuchernden Bucht.", progress = "Habt Ihr die Blindgänger? Gebt sie mir!\n\n… Vorsichtig!", completion = "Oh ja. JA! Damit können wir ganz sicher jemanden erledigen.\n\nWahrscheinlich ein paar Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[27587] = { id = 27587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverschämt lecker", description = "Wisst Ihr, ich habe hier ein Problem, bei dem Ihr mir vielleicht helfen könntet.\n\nNun, zusätzlich zu meinen Waffengeschäften, die ich hier verfolge, versuche ich, hier in Kraulsumpf ein wenig Unterhaltung aufleben zu lassen. Anscheinend gibt es ein paar dieser Makruradinger in den nördlichen Gewässern, denen unsere wilden Strandpartys nicht in den Kram passen.\n\nJetzt sind sie die Angeschmierten. Ich lasse mich doch nicht von riesigen Hummern herumschubsen - sie werden meine nächste Einkommensquelle sein! Bringt mir einige ihrer Schwänze und wir schlagen aus dem Problem unseren Profit.", sourceObjective = "Besorgt 6 intakte Makruraschwänze von Sumpfstrandmakruras.", progress = "Habt Ihr die Schwänze? Versucht nicht, mir kaputte anzudrehen!", completion = "Ich sehe es schon vor mir: unsere eigenen, berühmten Kraulsumpfer Hummercracker! Frisch aus dem Meer! Oh, es ist, als ob sich das von ganz alleine schreibt...\n\nIch weiß Eure Hilfe sehr zu schätzen, mein Freund. Ich werde sehen, ob ich für Eure Leute besonders günstige Konditionen machen kann, ok?", sourceObjectiveStatus = "unverified-source-field" }
quests[27588] = { id = 27588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr unseren Truppen signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27589] = { id = 27589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Grimmige Säufer", description = "Jeder im \"Grimmigen Säufer\" ist vollkommen betrunken und deshalb leicht zu verärgern. Ich glaube, wir können die Dunkeleisenzwerge ernsthaft behindern, indem wir hier ein wenig Chaos stiften.\n\nIhr müsst einen Streit mit drei der berüchtigten Stammkunden vom Zaun brechen. Beschädigt die Fässer und Hurley Pestatem wird herbeieilen. Stehlt die Gegenstände vom Tisch in der Nähe von Stöpsel Zapfring und er wird kämpfen. Was Ribbly Schraubstutz angeht - mit dem Hitzkopf müsst Ihr nur reden. Meldet Euch bei Donnerherz, wenn Ihr fertig seid.", sourceObjective = "Findet Hurley Pestatem, Stöpsel Zapfring und Ribbly Schraubstutz.", completion = "Ich höre ziemlichen Tumult im \"Grimimgen Säufer\". Wie ich sehe, habt Ihr schwer gearbeitet.\n\nWenn Ihr jetzt Eure Aufmerksamkeit auf die mir gegenüberliegende Seite richtet, werdet Ihr bemerken, dass wir uns um wichtigere Dinge sorgen müssen, als mit Betrunkenen Spielchen zu spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27590] = { id = 27590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlt den Angriff", description = "Jetzt, da Ihr Schädelbrecher den Berg vom Schattentor weggelockt habt, müsst Ihr unseren Truppen signalisieren, dass sie angreifen können!", sourceObjective = "Benutzt das Angriffssignal auf einem der Türme beim Schattentor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27591] = { id = 27591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pakt mit den Dunkeleisenzwergen", description = "In dieser Kammer liegt Botschafter Flammenschlag. Er ist der Botschafter von Ragnaros dem Feuerlord und vertritt ihn beim Volk der Dunkeleisenzwerge. Jenseits dieser Kammer befindet sich die Gruft der Beschwörer, Heimat der Geister der sieben Patriarchen der Dunkeleisenzwerge, die Ragnaros in unsere Welt gerufen haben.\n\nMöglicherweise habt Ihr noch nichts von dem großen Feuer gehört, aber er bedeutet das Ende für Azeroth, wenn er nicht aufgehalten wird. Diese Individuen stehen in direkter Verbindung zu der Macht, die er über die Dunkeleisenzwerge hat. Tötet sie alle und möge die unheilige Vereinigung enden.", sourceObjective = "Tötet Botschafter Flammenschlag und Un'rel.", completion = "Ich kann alleine nicht weitermachen, egal, wie viel Kampferfahrung ich habe. Das Lyzeum hat sich als zu schwer für mich erwiesen. Doch da Ihr hier seid... Ihr könntet der Schlüssel zu all dem hier sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27592] = { id = 27592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getränke \"on the rocks\"", description = "Was geht, \"Bruder\"? Wir waren grad mitten in einer krass-spontanen Strandparty, als etwas Furchtbares passierte, \"Alter\"!\n\nIch hatte eine ganze Kiste Silberschnappirinha, das bevorzugte Getränk des Barons, bis die Schlickkriecher ihn gestohlen haben! Ich habe noch nie gesehen, dass Kriecher trinken, aber sie haben alles mit ins Wasser am Strand genommen! Wir brauchen irgendeinen großartigen Helden, der uns helfen kann, unser mit Schutzmarke versehenes Lieblingsgetränk wiederzubeschaffen.\n\n<Brono starrt Euch einen Moment lang an.>\n\nDamit meine ich Euch, \"Kumpel\"!", sourceObjective = "Sammelt 10 Flaschen gestohlenen Silberschnappirinha von Schlickkriechern ein.", progress = "Habt Ihr die Ware, \"Bruder\"?", completion = "Unser eiskalter, erfrischender Silberschnappirinha! Ich kann Euch für diese vollkommen spontane Heldentat gar nicht genug danken, \"Kumpel\"! \n\nHier habt Ihr Eure eigene Flasche als total aufrichtiges Zeichen unserer Dankbarkeit! Jetzt müsst Ihr nur noch ALL EUREN FREUNDEN sagen, wie gut er schmeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27593] = { id = 27593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiedergeburt des KEK", description = "Imperator Dagran Thaurissan hat die volle Kontrolle über die Stadt von seinem Thron aus, der vor uns liegt. Wenn wir seine Armeen aufhalten wollen, müssen wir die Herrschaft ihres Gebieters beenden.\n\nUm zu ihm vorzudringen, werdet Ihr seine persönliche Leibgarde überwinden müssen, einschließlich des Riesen Magmus. Bewegt Euch so schnell wie möglich - sollte jemand Alarm schlagen, bevor Ihr fertig seid, wird die gesamte Stadt zu seinem Thron strömen.\n\nDenkt auch daran, dass die Tore am anderen Ende des Lyzeums sich nur öffnen werden, wenn Ihr die Kohlenpfannen mit Fackeln von den Flammenbewahrern entzündet habt. Viel Glück.", sourceObjective = "Tötet Imperator Dagran Thaurissan.", completion = "Ihr seid ein {class}, wie er im Buche steht! Ihr habt das Unmögliche vollbracht! Ich wusste, dass wir uns auf Euch verlassen können.\n\n\n\nUnd damit möchte ich Euch als Erstem bekanntgeben, dass das Expeditionskorps von Kargath offiziell wieder im Geschäft ist!\n\nIch entbiete Euch meine persönliche Dankbarkeit für Eure Bemühungen hier. Denkt immer an unser Motto: \"Die ersten drin, die letzten draußen und immer siegreich. Vergesst niemals Kargath.\"\n\nIhr dürft wegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27594] = { id = 27594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Geheimdienst Ihrer Majestät", description = "Lorna Crowley, Tochter von Lord Darius Crowley, befindet sich momentan im vorderen Basislager der Gilnearischen Befreiungsfront, in der Nähe des Graumähnenwalls im Südosten.\n\nUnsere oberste Priorität ist es, jemanden in das Lager einzuschleusen und sie lebend zu fangen. Die Dunkle Fürstin glaubt, dass sie Lorna als Druckmittel gegen Crowley einsetzen kann. Ich sage, wir töten sie einfach und bringen sie als eine Verlassene zurück, doch wir müssen uns den Befehlen der Dunklen Fürstin beugen.\n\nWir müssen uns beeilen, bevor der Rest der Allianzstreitkräfte eintrifft.", sourceObjective = "Nehmt Kommandantin Lorna Crowley gefangen und bringt sie zu Fürstin Sylvanas Windläufer an der Frontlinie der Verlassenen im Silberwald.", completion = "Ihr habt es geschafft! Endlich fügt sich alles zusammen. Wenn Crowley unsere Bedingungen nicht akzeptiert, wird seine Tochter umgewandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27595] = { id = 27595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Prophet Hadassi", description = "Prophet Hadassi ist das weiseste und älteste Mitglied des Orsisstammes.\n\nWir wissen nicht, wo er sich aufhält, und sein Wohlergehen ist von immenser Bedeutung.\n\nGeht nach Orsis und findet ihn. Sollte er verletzt worden sein, wird ein großer Tag der Abrechnung über die Lakaien von Al'Akir kommen.", sourceObjective = "Findet den Propheten Hadassi in Orsis.", completion = "Wer... wer seid Ihr? Hierher geschickt... um mein Volk zu retten und unsere Feinde zu bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27596] = { id = 27596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Berges", description = "Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!\n\nAlso muss ich Gewalt anwenden.\n\nKämpft Euch zum Schwarzen Gewölbe in der Nähe der Halle des Handwerks durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!\n\nViel Glück.", sourceObjective = "Besorgt Euch das Herz des Berges.", progress = "Habt Ihr das 'Herz des Berges'? Für mich ist der Edelstein unendlich wertvoll.", completion = "Ihr habt das Herz! Erstaunlich! Es ist sogar noch schöner, als ich es mir vorgestellt hatte!\n\nBitte, {name}, nehmt dies als Bezahlung an!", sourceObjectiveStatus = "unverified-source-field" }
quests[27597] = { id = 27597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verrückte Larry", description = "Ihr habt es begriffen, {name}. Eine Hand wäscht die andere. Um genau zu sein, wasche ich die Hände Eurer ganzen Armee, und zwar ein bisschen besser als die Hand der anderen Seite! War das zu kompliziert?\n\nIch meine damit, dass das eine Menge Hände sind. Deshalb muss ich Euch bitten, meine Hand noch ein paar Mal zu waschen. Der Dieb dieser Landminen hat wahrscheinlich gerade unsere Jungs am Ostufer erwischt.\n\nMacht Euch zu unserem Lager im Südosten auf und sprecht mit dem verrückten Larry. Er wird Euch alles erklären.", sourceObjective = "Findet den verrückten Larry südöstlich von Kraulsumpf.", completion = "Silberschnapp schickt Euch?! Ich bin ERLEDIGT!\n\nOh... er hat Euch geschickt, um mir zu helfen! Das ist was anderes, haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[27598] = { id = 27598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Gil", description = "Gilblins!\n\n<Larry starrt Euch eine Weile schweigend an.>\n\nIhr habt noch nie einen Gilblin gesehen? Sie sind verrückt! Noch verrückter als ich! Ich jage Dinge für meinen Lebensunterhalt in die Luft, aber diese Dinger sind DURCHGEKNALLT!\n\nIch habe keine Ahnung, wo sie hergekommen sind, aber sie sind wie schreckliche Fischgoblins! Mit Kiemen und allem Drum und Dran! Sie haben all meine Leute unten am Strand getötet und dann haben sie unseren Schiffsfrachter ausgeschaltet.\n\nIhr müsst helfen! Sie sind genau im Osten. Geht und schafft mir diese Gilblins vom Hals!", sourceObjective = "Tötet 7 Pirscher der Gilblins.", completion = "Das wird diesen fischgesichtigen Missgeburten eine Lehre sein! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27599] = { id = 27599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Hemd hat keine Taschen", description = "Alle Besatzungsmitglieder, die Ihr nicht in diesem Lager seht, sind TOT! Das waren wirklich gute Goblins, aber das Schlimmste ist, dass sie immer noch dort draußen sind! Das ist eine TRAGÖDIE!\n\nIch meine, es ist eine Tragödie, dass sie immer noch ihren ganzen Besitz haben! Schrecklich, wenn man an all die guten Materialien und Münzen denkt, die dort draußen im Wasser liegen.\n\nHey! Ihr könntet mir einen Gefallen erweisen! Wenn Ihr dort draußen Gilblins tötet, könntet Ihr die Kulturbeutel meiner ehemaligen Besatzungsmitglieder mitbringen!\n\nKommt schon, die brauchen sie doch nicht mehr! Mal ehrlich!", sourceObjective = "Beschafft 6 Kulturbeutel von toten Freibeutern von Kraulsumpf.", progress = "Habt Ihr die Kulturbeutel? Hoffentlich habt Ihr die Goblins da gelassen!", completion = "Wow!\n\nIch weiß nicht, warum ich das gesagt habe. Ich bin leicht zu begeistern! Aber seht nur, wie viel Zeug diese Jungs bei sich hatten!\n\nHier, wollt Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[27600] = { id = 27600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knall auf Fall", description = "Unsere Handelsfregatte ist immer noch ziemlich weit draußen auf dem Wasser umschwärmt von Gilblins! AHH!\n\nTut mir leid. Aber mal im Ernst! Wir müssen einen Weg finden, wie wir Euch dorthin befördern und unsere Sachen wiederbekommen. Auf dem Schiff befinden sich Qualitätswaren! QUALITÄT! SO WIE MEIN ZWEITER VORNAME!\n\nZu Eurem Glück habe ich eine Idee! Geht aus dem Camp hinaus und an der Nordwand entlang... Mein Sohn Jerry wird Euch mit unserer Kanone dorthinbefördern. Vorausgesetzt, er hat geübt!", sourceObjective = "Sprecht mit dem verrückte Jerrylein, um das Schiff zu entern. Besorgt danach die drei wertvollen Waren des verrückten Larry.", progress = "Habt Ihr sie? Habt Ihr sie bekommen? Habt Ihr die Kanone ausprobiert? Ihr seid nicht explodiert!", completion = "Meine hochwertige Lunte! Mein importiertes Sprengpulver!\n\nUnd mein... ja, hallo erstmal! Ich brauche nur das!\n\nDas alles ist mehr wert, als alles Gold, das Ihr bei Euch tragt! Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[27601] = { id = 27601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Städte im Staub", description = "Unsere Armeen treffen überall auf dem Schlachtfeld aufeinander. Crowley und seine Streitkräfte verlieren an Boden und wissen bisher noch nichts über das Schicksal von Lorna Crowley. Wir treffen uns mit Crowley und seinen Landsleuten in der Mitte des Feldes und ich werde ihnen die Bedingungen für ihre Kapitulation unterbreiten. Entweder, sie akzeptieren diese, oder wir werden sie alle töten und ihre Städte im Staub hinterlassen.\n\nDa Ihr mein vertrautester Soldat seid, möchte ich, dass Ihr während des Austauschs an meiner Seite steht. Sagt mir, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Begleitet Fürstin Sylvanas Windläufer auf das Schlachtfeld und besiegt die Allianz!", completion = "<Fürstin Sylvanas Windläufer verzerrt schmerzerfüllt das Gesicht.>\n\nEs... ist noch nicht vorbei. Godfrey und seine verräterischen Verbündeten werden dafür bezahlen, was sie hier getan haben, genau wie die verbleibenden Streitkräfte der Allianz, die Lordaeron besetzt halten.\n\nUnsere Arbeit hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27602] = { id = 27602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Worte eines sterbenden Propheten", description = "Wir... sind... durch einen Eid... verpflichtet, das Zepter von Orsis zu beschützen.\n\nHört zu, {class}, ich habe nicht mehr... viel Zeit.\n\nFindet das heilige Gefäß... am südlichen Ende der Stadt.\n\nLasst es... nicht in... ihre Hände fallen.", sourceObjective = "Findet das heilige Gefäß.", completion = "Die Kiste selbst ist verschlossen, aber darüber befindet sich eine Plakette mit interessanten Hieroglyphen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27603] = { id = 27603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das versiegelte Tor", description = "Am einen Ende der Dunkeleisenstraße findet Ihr ein massives Tor, ähnlich dem, das auf der gegenüberliegenden Seite die Schattenschmiede schützt. Wir haben jedoch keine Ahnung, was sich dahinter befindet!\n\nWir wissen nur, dass es von Patrouillen der Zorneshämmer und dem geschmolzenen Riesen Bael'gar schwer bewacht wird. Ihr müsst sie einfach nur beseitigen und schauen, ob Ihr das Tor öffnen könnt.\n\nStellt Euch nur vor, was dahinter liegen mag... Es könnte eine komplette zweite Hälfte der Stadt geben, von der wir bis jetzt noch keine Ahnung hatten! Oder nichts! Wer weiß das schon?\n\nAber da ist sicher etwas...", sourceObjective = "Tötet Bael'gar.", completion = "Verdammt! Ich MUSS einfach wissen, was hinter diesem Tor liegt! Das könnte die Entdeckung sein, die meine Karriere ins Rollen bringt. Versteht Ihr?\n\nHmm… Vielleicht können ein paar strategisch platzierte Explosionen das Problem ja lösen…", sourceObjectiveStatus = "unverified-source-field" }
quests[27604] = { id = 27604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an der Prophet", description = "Jammal'an der Prophet, Anführer der Atal'ai- und Hakkaritrolle, hat eine kleine Menge Blut von Hakkar dem Seelenschinder an sich gebracht. Jetzt verabreichen sie es grünen Drachen, damit deren Körper riesige Mengen des Bluts produzieren, das notwendig ist, um Hakkar in unsere Welt zu rufen.\n\nDas können wir nicht zulassen Tötet Jammal'an und seine Priester, bevor sie noch weitere Fortschritte machen.", sourceObjective = "Erbeutet den Kopf von Jammal'an dem Propheten.", progress = "Habt Ihr Jammal'an getötet? Ich brauche einen Beweis, dass die Tat vollbracht ist.", completion = "Ausgezeichnet! Ich nehme an, dass die Trolle sich ohne Jammal'ans Führung gegenseitig bekämpfen werden. Hakkar wird diese Welt nie erblicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27605] = { id = 27605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus", description = "Das Hakkarblut, das die Atal'ai den grünen Drachen verabreicht haben, hatte verheerende Auswirkungen auf die Drachen. Offenbar hat seine Anwesenheit in ihren Körpern die Drachen, die früher Gefangenenwärter der Atal'ai waren, verdorben und in Alptraumkreaturen verwandelt.\n\nEranikus, Yseras erstem Berater und Oberaufseher über den Tempel, wurden die größten Mengen des Blutes verabreicht. Das hat ihn jenseits aller Vorstellungskraft verändert. Wenn Jammal'an tot ist, sucht Eranikus und bereitet ihm ein Ende.", sourceObjective = "Tötet Eranikus.", completion = "Ihr habt nur Eranikus' Schemen besiegt? Das ist äußerst beunruhigend...\n\nHoffen wir, dass seine wahre Gestalt nicht noch außerhalb des Tempels existiert. Nur Ysera persönlich ist stärker als er.", sourceObjectiveStatus = "unverified-source-field" }
quests[27606] = { id = 27606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt ihn in die Luft!", description = "Lasst uns ein paar Fische fangen, {name}! Jetzt, da die Mörser bereit sind, können wir den Anführer dieser Invasion vernichten.\n\nTiefenlord Heth'Jatar ist der Kopf der Kriegerkaste der Schwarzschuppen. Geht zu den Bannern der Heth'Jatari nordöstlich von hier und blast in dieses Muschelhorn. Es funktioniert wie eine Hundepfeife, nur für Fische.\n\nWenn Heth'Jatar sich zeigt, werde ich den Mörserschützen befehlen, das Feuer zu eröffnen. Ihr werdet sehen, wo die Granaten einschlagen werden.\n\nLockt Heth'Jatar in unser Mörserfeuer und prügelt solange auf ihn ein, bis er aufgibt.", sourceObjective = "Blast in der Nähe eines Banners der Heth'Jatari in das Muschelhorn. Tötet Tiefenlord Heth'Jatar. Es wird einfacher, wenn Ihr ihn in das Mörserfeuer lockt.", completion = "Kabumm!\n\nWas? Ihr habt den Tiefenlord schon erschlagen?\n\nNun, dann brauchen wir wohl nicht weiter auf seine Leiche schießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27607] = { id = 27607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die südliche Flanke", description = "Unsere neue Vereinbarung mit der Horde stürzt mein Volk in einen direkten Konflikt mit der Allianz.\n\nDann sollen sie mal kommen!\n\nIn diesem Augenblick rückt die Allianz auf der Halbinsel vor, um den Hafen des Drachenmals zu bedrängen.\n\nSucht im Süden nach Rok'tar und stellt sicher, dass das Zwielichtufer in unserer Hand bleibt. Ich glaube, Rok'tar hat einen Gefechtsstand auf einem der Schiffswracks errichtet.", sourceObjective = "Sprecht mit Rok'tar am Zwielichtufer im Schattenhochland.", completion = "Ihr kommt genau rechtzeitig, {class}. Wir sind gerade dabei, einen Gegenangriff zu starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27608] = { id = 27608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Wir werden gleich den Angriff auf die Tore der Zitadelle starten, doch es gibt noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nWürdet Ihr nochmals losziehen und sie töten?", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", sourceObjectiveStatus = "unverified-source-field" }
quests[27609] = { id = 27609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Köpfe sind besser als keiner", description = "Wir werden gleich den Angriff auf die Tore der Zitadelle starten, doch es gibt noch eine Sache, um die Ihr Euch kümmern müsst: Za'brox und Beeble'phod, die Jünger Cho'galls.\n\nLaut den Geheiminformationen halten sie sich im Schlupfwinkel der Jünger auf, einer kleinen Ogerhöhle am südwestlichen Ende des Schattentors.\n\nGeht bitte zurück und tötet sie.", sourceObjective = "Sammelt die vier Köpfe von Za'brox und Beeble'phod.", sourceObjectiveStatus = "unverified-source-field" }
quests[27610] = { id = 27610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späht den Strand aus", description = "Wenn die Allianz die Kontrolle über diese Halbinsel erlangt, gerät der Hafen des Drachenmals in Gefahr. Das lasse ich nicht zu.\n\nSüdlich von hier findet Ihr einen kleinen Hügel, von dem aus man einen beeindruckenden Ausblick auf die Küstenlinie hat. Wer diesen Hügel kontrolliert, hat auch die Oberhand über die gesamte Küste.\n\nEilt schnell dorthin und späht den Brückenkopfkontrollpunkt aus. Er ist mit einer riesigen Flagge markiert. Kehrt dann zu mir zurück.\n\nIhr müsst ihn nicht einnehmen, es sei denn, Ihr seid auf einem Kampf mit der Allianz aus.", sourceObjective = "Späht den Brückenkopfkontrollpunkt am Zwielichtufer aus. Ihr müsst ihn nicht einnehmen, doch wenn Ihr dies tut, erhält Eure Fraktion einen Vorteil im Kampf und Ihr werdet für den PvP-Kampf markiert.", completion = "Gute Arbeit, {class}. Jetzt kennt Ihr die Lage des Landes.\n\nWenn Ihr je Probleme im Kampf hier am Zwielichtufer habt, dann vergesst nicht, dass alle Streitkräfte der Horde einen Kampfvorteil erhalten, wenn der Brückenkopf unter unserer Kontrolle steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27611] = { id = 27611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgetränkter Sand", description = "Unser Ziel im Schattenhochland ist, die Bastion des Zwielichts zu stürmen, aber die Allianz hat sich entschlossen, einen Krieg anzuzetteln.\n\nAlso sollen sie ihren Krieg haben!\n\nTötet ihre Marinesoldaten, bis sie ihre Lektion gelernt haben.", sourceObjective = "Tötet 12 Marinesoldaten am Zwielichtufer im Schattenhochland.", completion = "Gut, gut. Wer Wind sät, soll Sturm ernten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27612] = { id = 27612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg im Inneren", description = "Ein paar unserer Männer haben es nicht durch die Portale geschafft, die sich in dieser Abtei hätten öffnen sollen. Ihr habt bereits bewiesen, dass Ihr ebenso gut ausweichen wie kämpfen könnt... das müsst Ihr noch einmal zeigen.\n\nDie Abtei hat zwei Flügel: eine Bibliothek und eine Halle der Waffen. In beiden Flügeln sollte es ein Portal geben.\n\nSetzt den Schlüsselstein bei diesen Portalen ein. Der Stein sollte ihre Öffnung erzwingen. Dann können unsere restlichen Stoßtruppsoldaten die Abtei einnehmen.", sourceObjective = "Öffnet die Argentumportale im Bibliotheksflügel und der Halle der Waffen in der Abtei in Tyrs Hand.", completion = "Die Abtei wird in Kürze fallen. Wir können bald tiefer in Tyrs Hand eindringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27613] = { id = 27613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Assassine", description = "Das Schicksal des Scharlachroten Kreuzzugs ist tragisch, aber nicht ohne Ironie. Einst waren sie die Speerspitze der Menschheit im Kampf gegen die Untoten. Jetzt sehen sie aus wie die Leichen, die sie früher jagten. Es ist unklar, was sie in den Untod getrieben hat, aber das macht sie nicht weniger gefährlich.\n\nEiner ihrer tödlichsten Kämpfer war ein Assassine, der sich Rohan nannte. Laut unseren Informationen hält er sich genau in dieser Abtei ganz oben im Glockenturm auf. Findet und tötet ihn, {name}. Und versucht, dabei nicht zu sterben.", sourceObjective = "Tötet Rohan den Assassinen im Glockenturm der Abtei in Tyrs Hand.", completion = "Rohans Tod erleichtert mich ein wenig.\n\nWisst Ihr, dass ich früher mit ihm gekämpft habe? Vor vielen Jahren war er ein Abgesandter des Scharlachroten Kreuzzugs, einer der wenigen, die uns in der Schlacht gegen Kel'Thuzad zur Seite standen. Wie schnell sich alles ändert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27614] = { id = 27614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Bergung", description = "Diese Schlacht war schon gewonnen, bevor sie begann. Jetzt verbessern wir nur noch unsere B-Note.\n\nDie wimmernden Scharlachroten Kreuzfahrer klammern sich in ihren Kasernen an ihre unbezahlbaren Artefakte, obwohl manche so heilig sind, dass ihre jetzt untoten Hände sie nicht mehr berühren können. Also werden sie in Truhen aufbewahrt und vor der Welt versteckt.\n\nFindet diese Artefakte und bringt sie mir zurück. Ihr Platz ist beim Argentumkreuzzug. Sie gehören in die Hände der Rechtschaffenen.", sourceObjective = "Erbeutet den Purpureber, Lihannas Strang, das Tuch des Uther und Gavinrads Siegel.", progress = "Ich hoffe, es war ein guter Kampf.", completion = "Hervorragend, {name}. Ich werde sie nach unserer Rückkehr Tyrosus übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27615] = { id = 27615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zornwirker", description = "Im Kerker der Kaserne lauert ein äußerst übler Zeitgenosse des Scharlachroten Kreuzzugs, Mataus der Zornwirker. Der Untod passt zu seinem düsteren Gehabe.\n\nWäre ich noch jünger und an der Front, würde ich ihn selbst aufspießen. Doch leider muss ich unsere Streitkräfte von hinten anführen. Deshalb überlasse ich Euch dieses Vergnügen.", sourceObjective = "Tötet Mataus den Zornwirker.", completion = "Ihr seid auf dem besten Weg, ein wahrer Champion des Lichts zu werden, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27616] = { id = 27616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger", description = "Die Kugeln und Pfeile, die uns oben aus dieser Festung entgegenschießen, haben schon ein halbes Dutzend Männer das Leben gekostet. Ich kenne das Gesicht des Feindes, der auf uns schießt nicht, doch das ist auch nicht nötig. Ich kenne den Namen des Mannes, der dort oben hockt.\n\nLeopold.\n\nEs ist wirklich nur ein einziger Mann, der von dort oben meine Männer nacheinander umbringt. Und so wie ich das sehe, gibt es auch nur <einen/eine> von Euch.\n\nKlingt nach einem fairen Kampf.", sourceObjective = "Tötet Jäger Leopold.", completion = "Eine Sorge weniger. Gute Arbeit da oben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27617] = { id = 27617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entdorben", description = "Spürt Ihr es? Die Verderbnis löst sich bereits von diesem Gebäude.\n\nEin heiliges Gebäude will heilig sein. Übeltäter wie Rohan und seine Scharlachroten Kumpane hindern es jedoch daran.\n\nDie Abtei ist gesichert. Die Eroberung von Tyrs Hand ist einen Schritt näher gerückt. Meldet Angela das Ergebnis unseres Schlags. Sie führt den Angriff auf die Kathedrale irgendwo aus der Stadtmitte an.", sourceObjective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", completion = "Gut, die Abtei ist unser. Ich habe keinen Moment lang an Eligors Fähigkeiten gezweifelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27618] = { id = 27618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argentumaufstand", description = "Wir haben dieser Kaserne so viel Schaden zugefügt, dass man von einem Sieg sprechen kann. Eine Kommandantin, ein Jäger und ein Hexenmeister getötet... Und die ganzen Relikte, die wir geborgen haben. Oder sollte ich sagen... Die IHR geborgen habt.\n\nDie Kathedrale wird als nächstes fallen. Sprecht mit Erzmagierin Angela Dosantos im Hauptinnenhof. Das Schicksal der Kathedrale von Tyrs Hand liegt in ihren fähigen Händen.", sourceObjective = "Meldet Euch bei Erzmagierin Angela Dosantos in Tyrs Hand in den Östlichen Pestländern.", completion = "Korfax hat wohl in der Kaserne richtig aufgeräumt. So eine Angeberei passt zu ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27619] = { id = 27619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kommandantin", description = "Die Scharlachrote Kommandantin Marjhan ist listig, gewieft und bereit, alles für einen Sieg zu tun. Doch das Wichtigste ist ihre unerschütterliche Loyalität.\n\nIhr werdet sie zweifellos in der Hauptkammer der Kaserne finden. Dort wird sie unter einem scharlachroten Banner kämpfen, bis sie entweder siegt oder stirbt.\n\nSorgt dafür, dass Letzteres eintritt.", sourceObjective = "Tötet die Scharlachrote Kommandantin Marjhan.", completion = "Gut, gut. Die Kaserne ist so gut wie erobert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27620] = { id = 27620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Ratten", description = "Es freut mich, dass Eligor und Korfax mir ein wenig Spaß übrig gelassen haben. Es war nicht leicht, sie davon abzuhalten, Hals über Kopf in diese Kathedrale zu stürmen.\n\nAber das ist schließlich EURE Aufgabe.\n\nDie Kathedrale liegt vor uns. Sie ist die letzte Bastion der Scharlachroten Macht. Kreuzfahrerlord Valdelmar hockt darin auf dem klapprigen Lügengerüst von Tyrs Hand.\n\nEs darf keine Flucht geben und keine Gnade. Der erbärmliche Rest des Scharlachroten Kreuzzugs wird hier sein Ende finden. Tötet ihn.", sourceObjective = "Tötet Kreuzfahrerlord Valdelmar.", completion = "Obwohl ich mit ihren Methoden nicht einverstanden bin, sprechen ihre Resultate für sich. Der Scharlachrote Kreuzzug meinte es eigentlich gut, aber ihr Eifer wurde zu groß und ihr Hass raubte ihnen den Verstand.\n\nIch hoffe inständig, dass dies unserer Bruderschaft des Lichts nie zustoßen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27621] = { id = 27621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbarts Patrouille", description = "Ich war auf dem Weg, um mich Feuerbarts Patrouille anzuschließen, als mein Vogel abgeschossen wurde.\n\nDer Schattenhammer hat überall im Hochland Überraschungsangriffe durchgeführt. Manchmal erschienen ihre Gebäude einfach so aus dem Nichts aus dem Boden, mitten in unseren Dörfern. Es war ein echter Alptraum!\n\nIn dem Chaos war Feuerbart einer der wenigen, die einen kühlen Kopf bewahrten. Er versucht, einen vollständigen Greifenreiterflügel aus den Überlebenden zusammenzustellen.\n\nWenn Ihr wollt, dass die Wildhämmer sich der Allianz anschließen, solltet Ihr zunächst Feuerbart im Westen helfen.", sourceObjective = "Sucht nach Keegan Feuerbart bei Feuerbarts Patrouille im Schattenhochland.", completion = "Seid Ihr hier, um Euch der Patrouille anzuschließen, Bursche? Ich nehme Euch mit Freuden auf.\n\nIch brauche ein paar fähige Recken, um unsere Verteidigung hier unter Kontrolle zu kriegen. Helft mir und ich werde zusehen, dass ich eine etwas glanzvollere Arbeit für Euch finde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27622] = { id = 27622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netter Schredder", description = "{name}, ich habe Pläne für einen verbesserten Schredder, aber meine Ingenieure können nicht einfach so alleine in ein Kampfgebiet spazieren.\n\nGeht und findet einen bergungsfähigen Schredder am Zwielichtufer und benutzt ihn, um einen meiner Bergungsexperten herbeizurufen. Verteidigt den Schredder, bis wir ein paar \"Aktualisierungen\" daran vorgenommen haben.\n\nDie Allianz wird gar nicht wissen, wie ihr geschieht! Zumindest nicht, bis meine Marketingkampagne angelaufen ist!", sourceObjective = "Findet einen bergungsfähigen Schredder am Zwielichtufer und benutzt ihn, um einen Bergungsexperten aus Bilgewasser herbeizurufen. Verteidigt den Schredder, bis er wieder funktionstüchtig ist.", completion = "So mag ich das! Genau so! Kalter Stahl und heißer Tod!\n\nWelchen Namen sollten wir unserer neuen Schöpfung geben? Der Gnugatron? Nein, viel besser: der {name}-o-Matik! Das hat einen guten Klang.", sourceObjectiveStatus = "unverified-source-field" }
quests[27623] = { id = 27623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kolossale Wächter", description = "Die Kiste, die das Zepter enthält, scheint magisch versiegelt zu sein und ist nicht zum Nachgeben zu bewegen.\n\nDie Plakette darüber zeigt zwei riesige Statuen, in deren Mitte sich Vertiefungen befinden, in die jeweils ein mond- und ein sternförmiger Stein passen.\n\nDie Abbildung der Statuen zeigt, wie sie Pyramiden bewachen, die so wie diejenigen aussehen, die sich draußen befinden.\n\nVielleicht würde es sich lohnen, diese zu untersuchen.", sourceObjective = "Beschafft Euch den Stein des Mondes und den Stein der Sonne von den kolossalen Wächtern.", progress = "Ihr wischt den Sand von den Hieroglyphen, aber sie werden sofort von einer neuen Schicht überzogen. Ihr solltet Euch lieber beeilen.", completion = "Ihr platziert die beiden Edelsteine in die Vertiefungen an der Wand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27624] = { id = 27624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Fall", description = "Och, das war nichts weiter.\n\nDiese Statuen waren ohnehin wackelig - sie brauchten nur einen kleinen Schubs.\n\nWie wäre es, wenn Ihr geht und die Trümmer durchsucht?\n\nIch habe das Gefühl, als ob wir kurz davor stehen, das Rätsel zu lösen.", sourceObjective = "Sammelt die Kugel des Morgensterns, die Kugel des Abendsterns, die Kugel des Nordsterns und die Kugel der Sternschnuppe ein.", progress = "Habt Ihr etwas Interessantes gefunden, {name}?", completion = "Gute Arbeit, {name}.\n\n\n\nSieht so aus, als ob unsere Arbeit hier fast erledigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27625] = { id = 27625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verteidigung von Quel'Danil", description = "Die Untoten sind hier! Die Verlassenen! Sie kamen immer näher und näher, aber aufs Ganze gehen und uns angreifen... Diese entsetzlichen Monstrositäten!\n\nDie jungen Draenei, die man mir anvertraut hat, haben mit den Hochtalelfen im Kampf trainiert. Sie sind nicht schutzlos, aber sie brauchen Hilfe!\n\nBitte, {name}, helft ihnen! Drängt die Verlassenen zurück!", sourceObjective = "Tötet 16 Eindringlinge der Todespirscher an der Jagdhütte Quel'Danil.", completion = "Derartige Verirrung im Angesicht des Lichts... Ihr seid mutig, Euch ihnen entgegenzustellen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27626] = { id = 27626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hochtalaufzeichnungen", description = "Die Hochtalelfen haben seit Jahren hier detaillierte Aufzeichnungen aufbewahrt. Todesfälle, Geburten, Jahreszeiten... aber auch wichtige Informationen von Spähern und Methoden, wie man mit dem Rest der Allianz Verbindung aufnehmen kann.\n\nDiese Aufzeichnungen werden in dem Chaos verstreut werden. Wenn sie in die Hände der Verlassenen fallen, könnten noch mehr Leben auf dem Spiel stehen! Bitte, Ihr müsst die Aufzeichnungen finden, bevor sie der Horde in die Hände fallen.", sourceObjective = "Findet den Hochtalbericht, die Hochtalaufzeichnungen und die Hochtalnotizen.", progress = "Sind sie in Sicherheit?", completion = "Dem Licht sei Dank! Wir werden den Verlassenen nichts überlassen, das gegen uns verwendet werden kann, egal, wie wenig es sein mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[27627] = { id = 27627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine aufgetakelte Kakerlake", description = "Offensichtlich beherbergten die uralten Statuen verschiedene Arten von Skarabäen.\n\nIhr seid entschlossen, diesen Ort in dem bestmöglichen Zustand zu verlassen und beschließt, die Kammer von dieser Plage zu befreien.", sourceObjective = "Tötet 5 Amethystskarabäen, 5 Saphirskarabäen, 5 Türkisskarabäen und 5 Smaragdskarabäen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27628] = { id = 27628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benachrichtigt Phaoris", description = "Beeilt Euch, {name}. Wir müssen mit meinem Bruder, dem König, sprechen.\n\nEr will unbedingt einen Krieg mit Al'Akir und Neferset verhindern. Er hat die törichte Hoffnung, dass es für dieses Problem eine diplomatische Lösung gibt.\n\nVielleicht kommt er zur Vernunft, wenn er hört, was hier geschehen ist.", sourceObjective = "Sprecht mit König Phaoris in Ramkahen in Uldum.", completion = "Das ist erst der Anfang, {name}. Wenn die Gehilfen von Todesschwinge ganze Städte begraben können, haben wir kaum eine Chance, sie mit normalen Mitteln zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27629] = { id = 27629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Votum des Wesirs", description = "Wesir Tanotep dazu zu bewegen, sich gegen die Wünsche meines Bruders zu stellen, wird äußerst schwierig sein. Seine Stellung beruht darauf, den Willen von Phaoris durchzusetzen.\n\nIch hatte kein Glück damit, für einen offenen Krieg gegen Neferset zu plädieren.\n\nDennoch müsst Ihr mit ihm sprechen. Vielleicht hört er auf die Ansichten eines Außenstehenden.\n\nIhr findet den Wesir auf den Feldern von Akhenet in offizieller Mission.", sourceObjective = "Sprecht mit Wesir Tanotep auf den Feldern von Akhenet in Uldum.", completion = "Was für eine Kreatur seid Ihr? Ihr werdet das Land des Königs verlassen, bevor...\n\nWartet! Ihr seid dieser {name}, über den ich so viel gehört habe.\n\nIhr müsst meine mangelnde Gastfreundschaft entschuldigen. Wir haben hier zu viele feindliche Eindringlinge zu Gesicht bekommen, seit die Barriere um Uldum gefallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27630] = { id = 27630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Votum des Hohepriesters", description = "Das Votum von Hohepriester Amet ist das einzige, das sich unserer Kontrolle entzieht.\n\nEr wird so abstimmen, wie seine Weissagungen es ihm vorschreiben und wir können ihn nicht davon abbringen.\n\nIch denke, dadurch sind die Chancen in beide Richtungen ausgeglichen.\n\nDas einzige Problem ist, dass seine Hellseherei ihn, seitdem die Barrieren um Uldum gefallen sind, im Stich lässt.\n\nEr wird nicht abstimmen, solange er nicht wieder die Kontrolle über seine Weissagungen hat.\n\nSteigt eine der Treppen an den Seiten des Vir'naaldamms hinab, sprecht mit ihm und seht, was Ihr tun könnt, um ihm zu helfen.", sourceObjective = "Sprecht mit Hohepriester Amet im Vir'naaldamm in Uldum.", completion = "Krieg, sagt Ihr.\n\nWeissagungen für einen Krieg sind immer schwierig. Einige Kriege dürfen nie ausgetragen werden, auch, wenn der Sieg sicher wäre. Einige Kriege müssen geführt werden, auch wenn die Niederlage sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27631] = { id = 27631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Votum des Hochkommandanten", description = "Wenn wir eine Resolution für Krieg verabschieden sollen, muss der Hohe Rat einstimmig dafür sein.\n\nIch bin sicher, dass Hochkommandant Kamses uns seine Stimme geben wird, wenn er hört, was in Orsis geschehen ist.\n\nBitte sprecht mit ihm in Ramkahen und stellt sicher, dass er Bescheid weiß. Ich muss Vorbereitungen treffen, falls unser Plan erfolglos ist.", sourceObjective = "Sprecht mit Hochkommandant Kamses am Außenposten der Legion von Ramkahen in Uldum.", completion = "Es ist nicht nötig, mich in die Geschehnisse in Orsis einzuweihen, {name}.\n\nIch habe bereits davon gehört. Und von Euch. Jeder Feind von Al'Akir ist mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[27632] = { id = 27632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanoteps Sohn", description = "Ich habe mein Leben in die Dienste des Königs gestellt. Nichts ist so wichtig, wie ihm zu dienen - mit einer Ausnahme: mein Sohn.\n\nTahet wurde von Wachposten von Neferset gefangen genommen.\n\nSie behaupten, dass mein Sohn unbefugt ihr Gebiet betreten hat. Phaoris versucht, seine Freilassung zu verhandeln... doch ich befürchte das Schlimmste.\n\nWenn Ihr Tahet findet, würde ich Euch meine Stimme geben.\n\nIch weiß nicht, wohin sie ihre Gefangenen bringen, aber ich habe gesehen, wie die Wachen auf Karten geschaut haben, die sie durch die dichte Vegetation führen sollten.", sourceObjective = "Besorgt die Karte des Vir'Naaldeltas von einer Wache von Neferset.", progress = "Dies könnte die Karte sein, die Ihr sucht.", completion = "Ihr habt eine Karte des Vir'naaldeltas bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27633] = { id = 27633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutgott Hakkar", description = "Hakkar... die Bloße Erwähnung des Namens des Seelenschinders schlägt viele in die Flucht. Im Sanktum des Gefallenen Gottes haben die Atal'ai einen großen Teil seines Skeletts geborgen und möchten ihn wieder ins Leben rufen. Seine Kinder haben schon begonnen, im Umkreis aufzutauchen.\n\nLegt dieses Ei im Sanktum ab. Es wird seine Beschwörung früher als geplant erzwingen. {name}, Ihr dürft nicht zögern. Schlagt zu, sobald sein Avatar erscheint!", sourceObjective = "Tötet den Avatar von Hakkar.", completion = "Hier habt Ihr Hakkar erfolgreich aufgehalten, aber ich befürchte, wir sind noch lange nicht fertig. Die Atal'ai haben den Großteil des von ihnen produzierten Blutes nach Zul'Gurub abtransportiert, wo die Hakkari daran arbeiten, den Blutgott dort zu beschwören.\n\nIch glaube nicht, das dies hier jemals der Ort für Hakkars Ankunft sein sollte - es war lediglich ein Test, um zu sehen, ob das Blut stark genug ist! Hakkar kann nur in Zul'Gurub beschworen werden... und ich befürchte, wir kommen zu spät, um die Hakkari aufzuhalten, nun da sie das Blut besitzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27635] = { id = 27635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekontamination", description = "Ihr seid schon sehr lange hier unten in Gnomeregan, {name}, und es ist bemerkenswert, dass Ihr überlebt habt und noch bei Verstand seid! Wir müssen Euch rausholen.\n\nBevor wir Euch zu den anderen Gnomen an die Oberfläche schicken können, müsst Ihr dekontaminiert werden. Begebt Euch in den nächsten Raum und besteigt den Sanitron 500. Er wird den Rest erledigen! Es wird nicht weh tun... nicht sehr.\n\nMeldet Euch bei Techniker Braggel, wenn Ihr fertig seid. Er wird Euch geeignete Ausrüstung besorgen.", sourceObjective = "Besteigt den Sanitron 500 und lasst Euch dekontaminieren.", completion = "So, jetzt könnt Ihr Euch an die Oberfläche begeben und ein neues Leben beginnen. Der Hochtüftler wird begeistert sein, wenn er von Eurer Ankunft erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27636] = { id = 27636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Mathias", description = "Alle Agenten des SI:7 sind tot. Ihr müsst Meister Mathias Shaw finden.\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo er sich aufhält.", sourceObjective = "Findet Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", completion = "Wo ist der Rest meiner Leute?", sourceObjectiveStatus = "unverified-source-field" }
quests[27637] = { id = 27637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Mathias", description = "Das ist ein schwerer Schlag für unsere Bemühungen. Verdammt sei Cho'gall!\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo Meister Mathias Shaw sich aufhält.", sourceObjective = "Findet Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[27638] = { id = 27638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Garona", description = "Alle Kor'kron sind tot. Ihr müsst Garona die Halborcin finden.\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo sie sich aufhält.", sourceObjective = "Findet Garona die Halborcin bei der Schattenzitadelle im Schattenhochland.", completion = "Wo sind die Kor'kron?", sourceObjectiveStatus = "unverified-source-field" }
quests[27639] = { id = 27639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Ihr und Garona", description = "Das ist ein schwerer Schlag für unsere Bemühungen. Verdammt sei Cho'gall!\n\nZum Glück hat der Truppenkommandant Euch erzählt, wo Garona sich aufhält.", sourceObjective = "Findet Garona die Halborcin bei der Schattenzitadelle im Schattenhochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[27640] = { id = 27640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen Dunwalds ist kein Kraut gewachsen", description = "Man hat Euch also beauftragt, die Wildhammerklans für den Krieg zu vereinen. Ein edles Unterfangen, keine Frage, aber ich glaube nicht, dass Ihr wisst, worauf Ihr Euch da eingelassen habt.\n\nDennoch, wenn Ihr Euch auf eine Schlacht vorbereitet, darf eine Familie unter keinen Umständen an Eurer Seite fehlen. Geht nach Südwesten, gegenüber des Schmelztiegels des Gemetzels. Dort findet Ihr die Ruinen des Dunwaldklans. Sie sind zwar ganz schön ramponiert, aber das hält jemanden wie die Dunwalds nicht auf. Der schwierigste Teil dabei wird, sie zu finden.", sourceObjective = "Haltet nach Überlebenden der Familie Dunwald in den Ruinen von Dunwald Ausschau.", completion = "Wenn Ihr nach den Dunwalds sucht, dann habt Ihr sie gefunden. Zumindest einen Teil davon. Meine anderen Brüder kann ich leider nicht finden, so sehr ich es auch versucht habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27641] = { id = 27641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beim Familientreffen", description = "He da, <Bursche/meine Dame>! Sicher hat Keely Euch in Sorge um unsere Brüder gestürzt, aber sie können ganz gut auf sich selbst aufpassen. Sie werden schon irgendwie hierher zurückfinden.\n\nVielleicht könnt Ihr mir einen Gefallen tun, wenn Ihr ohnehin schon zum Familientreffen da draußen seid... Das Gebiet der Dunwalds ist immer noch voll von den Kultisten des Schattenhammers und ihren Dienern. Ich würde es sehr zu schätzen wissen, wenn Ihr sie daran erinnert, dass sie hier nicht willkommen sind.", sourceObjective = "Tötet 20 Mitglieder des Schattenhammers im Gebiet der Dunwalds.", completion = "Ja, genau so habe ich mir das vorgestellt, Bursche. Ein {race} ganz nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[27642] = { id = 27642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsuchung der Trümmer", description = "Als der Schattenhammer unser Dorf gebrandschatzt hat, waren sie ganz schön gründlich. Meine Brüder und ich waren vielleicht die Einzigen, die sie zurückgehalten haben. Ich muss jedoch Gewissheit haben.\n\nWährend Ihr die Ruinen durchsucht, haltet Ausschau nach Leichen meiner Gefolgsleute. Ich muss wissen, ob es Überlebende gibt... oder Anzeichen dafür, dass jemand entkommen konnte.", sourceObjective = "Durchsucht die Leichen von 12 Opfern der Dunwalds.", completion = "So viele Tote also? Dann ist es nicht sehr wahrscheinlich, dass jemand außer meinen Brüdern den Kampf überlebt hat. Das habe ich befürchtet.\n\nVielen Dank, dass Ihr Euch die Zeit genommen habt, für mich zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27643] = { id = 27643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnelly Dunwald", description = "Ihr sucht nach uns, und ich suche nach meinen Brüdern. Offensichtlich haben wir also schonmal eine Sache gemeinsam.\n\nDonnelly ist unser ältester Bruder. Bei seiner Körpergröße wird das deutlich, bei seinem Verstand jedoch eher weniger. Normalerweise hält er sich in den Ruinen im Norden auf, in der Hütte. Könntet Ihr vielleicht für mich nach ihm suchen? Es würde mich beruhigen, wenn ich wüsste, dass es ihm gut geht.", sourceObjective = "Findet Donnelly Dunwald.", completion = "Hallo, Freund! Ich glaube nicht, dass ich Euch kenne… Ich bin Donnelly Dunwald.\n\nUnd wie heißt Ihr? Ich glaube nicht, dass ich Euch kenne… Kenne ich Euch?", sourceObjectiveStatus = "unverified-source-field" }
quests[27644] = { id = 27644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eoin Dunwald", description = "Eoin ist einer der Zwillinge. Er trinkt gerne mal einen über den Durst. Wahrscheinlich findet Ihr ihn beim alten Brunnen. Dort haben wir nämlich in einem Gebäude unser Bier gelagert.\n\nKönntet Ihr ihn vielleicht überreden, seiner besorgten Schwester einen Besuch abzustatten? Wenn Ihr zuerst an das Bier gelangt, sollte er sich bestimmt nicht lange bitten lassen.", sourceObjective = "Findet Eoin Dunwald.", completion = "Warum musste von allen Gebäuden dieser Stadt ausgerechnet dieses hier einstürzen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[27645] = { id = 27645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cayden Dunwald", description = "Cayden ist der andere Zwilling. Auch ihn dürstet es, aber nicht nach Bier. Er amüsiert sich sicher köstlich, seit der Schattenhammer an unsere Tür geklopft hat. Vielleicht kann er so ein paar Aggressionen loswerden.\n\nIch schätze, Ihr sucht am besten in der Marktgasse bei der alten Schmiede nach ihm. Er hat sich schon früher immer gerne dort aufgehalten, aber da sich an diesem Ort die meisten Anhänger des Schattenhammers tummeln, hat er wahrscheinlich jetzt noch mehr Grund, ihn sein Zuhause zu nennen.\n\nBringt ihn zu mir zurück. Unversehrt, falls möglich.", sourceObjective = "Findet Cayden Dunwald.", completion = "Schaut Euch nur an mit all der Ausrüstung und dem Schnickschnack. Keely hat Euch also geschickt, damit Ihr auf den alten Cayden aufpasst, ja? Nicht nötig! Ich habe diese Flegel im Griff.\n\nHaha! Sie haben heute dem falschen Zwerg aufgelauert! Ahahahahaha!", sourceObjectiveStatus = "unverified-source-field" }
quests[27646] = { id = 27646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Schnäbelchen", description = "Ich hab' meinen Greifen verloren. Schnäbelchen! Wo bist du, Schnäbelchen?!\n\nHelft Ihr mir, ihn zu finden? Ich weiß, dass er irgendwo in den Hütten ist. Muss er einfach sein!\n\nSchnäbelchen?! Wo tust du denn stecken?\n\nIch hoffe, ihm fehlt nichts.", sourceObjective = "Helft Donnelly dabei, Schnäbelchen in den Hütten von Dunwald zu finden.", progress = "Habt Ihr ihn gefund'n?! Bitte?", completion = "Ihr habt ihn gefund'n! Ihr habt Schnäbelchen gefund'n! Ich mag Euch, mein neuer Freund!\n\nIch werde ihn gleich Keely zeigen. Keely tut Schnäbelchen auch mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27647] = { id = 27647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles außer Wasser", description = "Schaut, Kumpel. Entweder helft Ihr mir, etwas zu trinken zu finden, oder Ihr geht mir aus dem Weg.\n\nWarum schaut Ihr nicht unten im alten Lagerhaus nach? Ich hatte den alten Buchhalter da nämlich schon immer im Verdacht, dass er sich heimlich das ein oder andere Gläschen zwischen den Zeilen gönnt. Ich wette, er hat ein Fass im Keller versteckt.\n\nWenn Ihr etwas findet, dann kommt sofort zu mir zurück. Nicht trödeln! Das hier ist brandeilig.", sourceObjective = "Durchsucht den Keller, von dem Eoin Dunwald gesprochen hat, nach einem Fass.", progress = "Ihr stinkt nach Nüchternheit! Sucht mir etwas zu trinken!", completion = "Bei Donnellys Dickbauch! Das sieht schon besser aus. Wie schön, dass ich jetzt nicht mehr verdursten muss.\n\nHier, nehmt einen Schluck. Der gute alte Eoin ist nie so unhöflich, nicht zu teilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27648] = { id = 27648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch diese hohle Gasse muss er kommen", description = "In Ordnung, in Ordnung. Ihr wollt also auch etwas von dem Spaß haben? Fein, Ihr könnt mitmachen.\n\nLasst mich wissen, wenn Ihr bereit seid.", sourceObjective = "Begleitet Cayden Dunwald durch den etwas offensichtlichen Hinterhalt.", progress = "Sie kommen immer wieder, und ich hau weiter drauf.", completion = "Wundervoll, oder? Und sie können nicht genug davon bekommen. Ich liebe es!\n\nIch werde zu Keely gehen und sie ein wenig beruhigen. Nur noch ein Durchgang!", sourceObjectiveStatus = "unverified-source-field" }
quests[27649] = { id = 27649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stete Versorgung", description = "He, Kumpel. Da Ihr ja so freundlich und toll und so seid, könntet Ihr einem Zwerg vielleicht einen Gefallen tun?\n\nDies sind die Ruinen der Dunwalds… Es MUSS einfach mehr Vorräte in einem dieser Gebäude geben. Wenn Ihr noch etwas Bier findet, würdet Ihr es mir dann bringen? Ja? Ein guter Zwerg kann nie genug bekommen!\n\nIch werde mich auf den Weg zu Keely machen, also werdet Ihr mich vielleicht suchen müssen. Aber keine Sorge, es wird Eure Mühe wert sein.", sourceObjective = "Sammelt 6 Fässer Wildhammerbier.", progress = "Wo ist mein gutes Gesöff?", completion = "Whoohooo! Genau das verlangt mein Magen!\n\nIhr bringt mir wirklich lauter nette Sachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27650] = { id = 27650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder zuhause", description = "Ihr solltet Keely aufsuchen. Sie ist bestimmt auf Eure Neuigkeiten gespannt.", sourceObjective = "Sprecht mit Keely Dunwald in der Bastion der Dunwalds.", completion = "Vielen Dank, dass Ihr meine Brüder wieder zusammengetrommelt habt. Ich weiß, sie sind harte Brocken, aber Seite an Seite sind sie noch härter, und da draußen sind ganz schön viele Kultisten des Schattenhammers.\n\nIhr habt einem armen Mädchen eine schwere Last von der Seele genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27651] = { id = 27651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Dunwälder Art", description = "Sie sind schon auf dem Weg, um den Ettin zu jagen, der den Angriff auf den Besitz der Dunwalds angeführt hat. Ich habe sie gebeten, Euch wenigstens eine Chance zu lassen, sie einzuholen, aber ich bin mir nicht sicher, ob das Warten ihnen liegt.\n\nSie sind in Richtung Ratsplatz gegangen, in die Mitte der Ruinen. Ihr solltet zu ihnen aufschließen, wenn Ihr auch mit von der Partie sein wollt.", sourceObjective = "Sprecht mit Flynn Dunwald und helft den Dunwaldbrüdern dabei, Darunga zu töten.", completion = "Vielen Dank für Eure Hilfe. Ihr habt das Herz eines Kriegers. Fast hätt' ich Euch für einen Wildhammer gehalten, wenn Ihr nicht… nun ja… Ihr wisst schon.\n\nIch weiß, dass Feuerbart Euch geschickt hat, um uns zu vereinen. Meine Sympathie für diesen Zwerg ist alles andere als groß, aber Ihr wisst ja jetzt, dass wir genügend Gründe haben, um den Schattenhammer als Feind zu betrachten. Sagt ihm, dass er auf die Familie Dunwald zählen kann, wenn die Schlacht beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27652] = { id = 27652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Auftragsmörder", description = "Sogar ich werde gejagt. Das hat man eben davon, wenn man sich unter Schafen versteckt.\n\n<Mathias mustert Euch einen Augenblick lang.>\n\nDer Schattenhammer hat einen Zahn zugelegt und seine dunklen Auftragsmörder nach mir geschickt. Nette Kerle, doch leider alle tot. Sie bestehen aus den Seelen der fähigsten Attentäter.\n\nMöchtet Ihr mir einen Gefallen tun? Dann bringt sie zur Strecke und beschafft mir ihre Seelenanhänger.", sourceObjective = "Sammelt 5 Anhänger eines dunklen Auftragsmörders.", progress = "Wie viele Anhänger habt Ihr?", completion = "Ich bin mir nicht sicher, was ich mit all diesen Dingern tun soll. Wahrscheinlich werde ich sie verhökern und den Ertrag dem Waisenhaus in Sturmwind stiften.\n\nJetzt muss ich nur noch jemanden finden, der geisteskrank genug ist, so etwas zu kaufen. Wahrscheinlich ein Goblin. Oder ein gnomischer Hexenmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[27653] = { id = 27653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Auftragsmörder", description = "Sogar ich werde gejagt. Das hat man eben davon, wenn man sich unter Schafen versteckt.\n\n<Garona mustert Euch einen Augenblick lang.>\n\nDer Schattenhammer hat einen Zahn zugelegt und seine dunklen Auftragsmörder nach mir geschickt. Nicht schlecht für einen haufen toter Kerle. Sie bestehen aus den Seelen der fähigsten Attentäter.\n\nMöchtet Ihr mir einen Gefallen tun? Dann bringt sie zur Strecke.\n\nSie tragen ihre Seelen in Anhängern um den Hals. Bringt sie mir. Die Seelen sind optional.", sourceObjective = "Sammelt 5 Anhänger eines dunklen Auftragsmörders.", progress = "Wie viele Anhänger habt Ihr?", completion = "Was soll ich nur mit all diesen Dingern tun? Vielleicht lasse ich sie einschmelzen und mache mir aus dem Metall einen neuen Dolch, den ich Cho'gall ins Herz stoßen kann.\n\nMeint Ihr, dafür haben wir genug Zeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[27654] = { id = 27654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Hammer", description = "Ein Vorstoß auf das Schlachtfeld wäre nicht vollständig, wenn es keine altmodische \"Macht den bösen Jungs den Garaus\"-Mission gäbe.\n\nIch bin mir sicher, dass Ihr bei all den Veteranen der Zitadelle, den korrumpierten Elementaristen und den Zwielichtverteidigern genügend Ziele findet.\n\nWie Ihr sie zur Strecke bringt, bleibt ganz Euch überlassen.", sourceObjective = "Tötet 10 Veteranen der Zitadelle, korrumpierte Elementaristen und/oder Zwielichtverteidiger.", completion = "Keiner von uns ist zu schade, um sich die Hände dreckig zu machen. Oder in diesem Fall blutig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27655] = { id = 27655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Hammer", description = "Es gibt nicht Schlimmeres als diese von Selbsthass zerfressenen Kultisten des Schattenhammers. Nichts! Diese Idioten wollen tatsächlich das Ende der Welt herbeiführen.\n\nDas bringt sie ganz oben auf meine Abschussliste.\n\nBei all den Veteranen der Zitadelle, den korrumpierten Elementaristen und den Zwielichtverteidigern gehen Euch die Ziele sicher nicht aus.\n\nWie Ihr sie zur Strecke bringt, ist mir herzlich egal.", sourceObjective = "Tötet 10 Veteranen der Zitadelle, korrumpierte Elementaristen und/oder Zwielichtverteidiger.", completion = "Fühlt sich gut an, so ein bisschen Blut an den Händen, was? Besonders, wenn es das Blut solcher verblendeten Narren ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27656] = { id = 27656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokischwemme", description = "Im Stagalsumpf östlich der Stadt wimmelt es von Krokilisken. Wimmelt, hört Ihr? Ich habe jeden vorstellbaren Teil der Krokilisken verkauft.\n\nKrokiliskenhäute, ihre Zähne, Schwänze, Zungen, Augen und so weiter. Was ich damit sagen will: Das verkauft sich nicht mehr. Es gibt zu viele Krokis! Wir haben ein Überangebot und eine Unternachfrage.\n\nDa sie mir also nichts mehr nützen und gelegentlich meine Gäste fressen, möchte ich, dass Ihr die Drecksviecher umbringt. Tut mir den Gefallen, ja? Ich verhandle währenddessen über irgendwas mit Euren Leuten.", sourceObjective = "Tötet 8 Sägezahnkrokilisken.", completion = "Alles erledigt? Freut mich. Eine Sorge weniger.\n\nJetzt kann ich mich auf ordentliche Geschäfte mit den freundlichen Bewohnern von Sumpftidenwacht und Steinard konzentrieren, die vom Krieg gezeichnet sind... und all der Blödsinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27657] = { id = 27657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Erdenruferin", description = "Meine Untersuchungen zu Cho'galls Artefakt sind in einer Sackgasse angelangt. Der Schattenhammer hat eine Gruppe von Schmieden der Wildhämmer versklavt und im See ertränkt, als sie ihre Aufgabe erledigt hatten.\n\n<Mathias spuckt aus.>\n\nWir brauchen Hilfe. Es gibt da eine Erdenruferin des Irdenen Rings mit Namen Yevaa.\n\nSie und ihr goblinischer Initiand halten sich an der Elementiummine im Südwesten auf und brauchen Hilfe dabei, die Elementarportale in der Gegend zu schließen. Im Gegenzug können sie uns sicher bei unserem Problem helfen.", sourceObjective = "Sprecht mit Erdenruferin Yevaa vor den Elementiumtiefen im Schattenhochland.", completion = "{name}! Ich bin froh, dass Ihr hier seid.\n\nNatürlich helfe ich Euch gerne, wo ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27658] = { id = 27658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Erdenruferin", description = "Meine Untersuchungen zu Cho'galls Artefakt sind in einer Sackgasse angelangt. Der Schattenhammer hat eine Gruppe von Schmieden der Wildhämmer versklavt und im See ertränkt, als sie ihre Aufgabe erledigt hatten.\n\n<Garona spuckt aus.>\n\nIch sage es nicht gerne, aber wir brauchen Hilfe. Es gibt da eine Dame des Irdenen Rings, eine Draenei namens Erdenruferin Yevaa. Sie und ihr Goblinschoßhund halten sich in der Elementiummine im Südwesten auf.\n\nSie brauchen Hilfe dabei, die Elementarportale in der Gegend auszuschalten. Im Gegenzug können sie uns bei unserem Problem helfen.", sourceObjective = "Sprecht mit Erdenruferin Yevaa vor den Elementiumtiefen im Schattenhochland.", completion = "{name}! Ich bin froh, dass Ihr hier seid.\n\nNatürlich helfe ich Euch gerne, wo ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27659] = { id = 27659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlastung der Portale", description = "Ich war früher die Hüterin der Portale des Irdenen Rings, doch als Ihr in Tiefenheim wart, um zu helfen, ist der Schattenhammer hier eingefallen und hat das Gebiet verderbt.\n\nSie lassen unsere Portale von mächtigen Aszendenten bewachen. Und genau darin liegt ihr Fehler.\n\nIch möchte, dass Ihr zu den Portalen geht und die Steuerungen verwendet, um sie zu überlasten. Dadurch werden die gesamten Energien des Portals freigesetzt und die Aszendenten geschwächt. Tötet sie.", sourceObjective = "Tötet den entkräfteten Apexar, den entkräfteten Aetharon und den entkräfteten Edemantus.", completion = "Das letzte Portal liegt tief in der Mine hier, aber darum kümmern wir uns gleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27660] = { id = 27660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist des Lochs", description = "Ich weiß nichts von einem Artefakt, das Cho'gall herstellt, aber ich glaube, ich kenne jemanden, der Euch helfen kann.\n\nGräfin Verrall ist ein alter Geist, der sich im Loch Verrall im Norden aufhält. Sie hegt keine Sympathie für den Schattenhammer, der ihre Wasser verschmutzt hat.\n\nBittet sie um die Weisheit, die Ihr sucht.", sourceObjective = "Sprecht mit Gräfin Verrall im Loch Verrall im Schattenhochland.", completion = "Ich weiß, warum Ihr hier seid, {name}. Eure Gründe singen im Rauschen Eures Blutes.\n\nIch weiß von dem toten Zwergenschmied, der meine Wasser verschmutzt. Wenn Ihr herausfinden wollt, an was sein Leichnam sich erinnert, dann müsst Ihr es Euch verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27661] = { id = 27661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artilleriefeuer", description = "Mein Erzfeind, Lord Artillerius, war so dumm, sich dem Schattenhammer anzuschließen.\n\nIn der Vergangenheit hatten wir einen brüchigen Waffenstillstand geschlossen, aber nach dieser Entscheidung habe ich keine andere Wahl, als ihm ein Ende zu setzen. Oder lasst es mich so ausdrücken: Wenn Ihr Informationen von einem toten Zwerg wollt, müsst Ihr Lord Artillerius für mich töten.\n\nSucht ihn bei Artillerius' Inferno im Südosten auf.", sourceObjective = "Tötet Lord Artillerius.", completion = "Ich bin sehr zufrieden. Lord Artillerius war mir immer ein unwürdiger Gegner.\n\nNun gut, {race}. Ich werde Euch dabei helfen, an die Informationen zu gelangen, die Ihr sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27662] = { id = 27662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichtentbindung", description = "Wenn ich mich mit einer Sache auskenne, dann sind es Elementare. Ich habe wirklich gelernt zu verstehen, wie sie empfinden. Und lasst mich Euch sagen: Es gefällt ihnen gar nicht, versklavt zu werden!\n\nIch will damit sagen, dass die Elementare Euch sicher nicht nur dankbar sind, wenn Ihr sie aus der Sklaverei befreit, sondern sich wahrscheinlich auch gegen ihre Meister wenden.\n\nIch finde, das klingt für beide Seiten nach einem Gewinn.", sourceObjective = "Befreit 10 versklavte Elementare in der Schattenzitadelle, indem Ihr sie tötet.", completion = "Was habe ich Euch gesagt? Elementare sind gar nicht so übel, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[27663] = { id = 27663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmeckt wie Schreiter", description = "Ihr da! Ja, Ihr! Ihr wollt ein gutes Wort beim Handelsbaron eingelegt bekommen? Dann geht mir mal zur Hand!\n\nIch habe gehört, dass Ihr derjenige seid, der die ganzen Makruraschwänze besorgt hat. Die sind zwar toll, aber nicht ausreichend für ein anständiges Sumpfessen. Ich brauche Keulen für mein Gumbo!\n\nEs gibt eine Menge Sumpfschreiter außerhalb der Stadt, im Sorgendunkel. Ich will die größten Keulen, die Ihr finden könnt!", sourceObjective = "Sammelt 9 riesige Sumpfschreiterschenkel von Sumpfschreitern.", progress = "Habt ihr die Keulen?", completion = "Ah, gut, gut! Das war genau, was ich brauchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27664] = { id = 27664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulkankartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Vulkankartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Vulkankartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Vulkankartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Vulkankartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27665] = { id = 27665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hurrikankartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Hurrikankartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Hurrikankartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Hurrikankartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Hurrikankartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27666] = { id = 27666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tsunamikartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Tsunamikartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Tsunamikartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Tsunamikartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Tsunamikartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27667] = { id = 27667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbebenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Erdbebenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Erdbebenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Erdbebenkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Erdbebenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27668] = { id = 27668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passt auf!", description = "Hört zu, {race}. Nicht, dass ich die Rettung nicht zu schätzen wüsste, aber wir sind in einer schlimmen Lage.\n\nIhr müsst da draußen besser achtgeben!\n\nIch habe Euch beobachtet. Ihr seid direkt über einer zerbrochenen Kiste der Allianz vorbeigeschwommen.\n\nDa ist sicher etwas drin, das mir und meinen Jungs helfen könnte.\n\nWarum geht Ihr nicht dorthin und schaut einfach mal hinein, hm?", sourceObjective = "Nazgrim möchte, dass Ihr nachschaut, was in der zerbrochenen Kiste der Allianz nördlich der \"Ewiger Kreislauf\" liegt.", completion = "Ja…\n\nDas sieht aus wie etwas, an dem Nazgrim sehr interessiert sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27669] = { id = 27669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr habt die Ehre", description = "Anscheinend müssen jetzt nur noch die Kugeln auf die Sockel in jeder Ecke dieses Mechanismus gelegt werden.\n\nWir sind offenbar über den wichtigsten Fund der modernen Geschichte gestolpert.\n\n<Harrison schaut Euch eine Weile an und gibt Euch dann die Kugeln.>\n\nNur zu, {name}.\n\nOhne Euch hätten wir diese Entdeckung nie gemacht.", sourceObjective = "Benutzt die Kugeln der Sterne in der Nähe des Mechanismus in der Kammer der Sterne.", completion = "Jetzt schaut Euch das an!\n\nSo erstaunlich dies auch sein mag, ich bin sicher, dass hinter unserer Entdeckung noch mehr steckt.\n\nWesentlich mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[27670] = { id = 27670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingekesselt", description = "Mein Name ist Nevin Drallzang und ich bin der Kommandant von S.I.C.H.E.R.\n\nIch weiß nicht, wie Ihr die Strahlung hier unten überlebt habt, {name}, aber die meisten anderen hatten nicht so viel Glück. Mein Team sammelt zwar die Überlebenden, aber es gibt so viele strahlungsverwirrte Lepragnome, dass wir sie nicht mehr lange zurückdrängen können. Sie haben den Verstand verloren!\n\nSolltet Ihr noch stark genug sein, um eine Waffe zu heben oder einen Zauber zu wirken, könntet Ihr uns helfen, ein paar dieser Lepragnome auszuschalten.", sourceObjective = "Tötet 6 wahnsinnige Lepragnome.", completion = "Gut gemacht, {name}. Meine Männer werden jetzt übernehmen. Konzentrieren wir uns darauf, die anderen Überlebenden herauszubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27671] = { id = 27671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kümmert Euch um die Überlebenden", description = "Wenn wir nicht bald handeln, werden weder Nevin noch die Überlebenden hier heil herauskommen. Ich werde Euch das Notfallteleportersignal meiner Einheit geben. Wir haben noch genügend Kraft und Munition, um uns nach oben zu kämpfen, aber diese Überlebenden können nicht mithalten.\n\nSetzt das Signal bei den Überlebenden ein, damit sie in die sichere Zone, die meine Männer errichtet haben, teleportiert werden können. Erstattet mir Bericht, sobald das erledigt ist und wir werden dafür sorgen, dass Ihr hier wegkommt.", sourceObjective = "Benutzt das Teleportersignal, um 6 Überlebende in Sicherheit zu teleportieren.", completion = "Es wird Nevin freuen, dass Ihr so vielen Überlebenden helfen konntet. Ich kann immer noch nicht fassen, dass Ihr trotz der Strahlung hier unten noch so stark seid. Ihr habt ja den Zustand der anderen Überlebenden gesehen.\n\nAb mit Euch zum Laderaum zur Dekontamination.", sourceObjectiveStatus = "unverified-source-field" }
quests[27672] = { id = 27672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer von Khaz'mul", description = "In der Kartenkammer gibt es eine Tür, die zur legendären Kammer von Khaz'mul führt. Wer kann schon sagen, welche Geheimnisse darin verborgen sein mögen!\n\nWas wir wissen, ist, dass sie von Ironaya, einer Titanenwächterin von immenser Größe und Macht bewacht wird. Ihr müsst sie besiegen, wenn Ihr die Geheimnisse von Uldaman entdecken wollt.", sourceObjective = "Besiegt Ironaya.", sourceObjectiveStatus = "unverified-source-field" }
quests[27673] = { id = 27673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kommt auf die inneren Werte an", description = "Die Schöpfer haben zwei Uralte Steinbewahrer gebaut, um Uldaman vor möglichen Eindringlingen zu schützen und die Tagesgeschäfte zu überwachen, währen Ironaya und Archaedas schlummern. Einer ist immer noch voll funktionsfähig und befindet sich in der Halle des Tempels, aber der andere in der Echomok-Höhle wurde von etwas beschädigt.\n\nIch fürchte, dass einer der Alten Götter dafür verantwortlich ist. Ihr müsst mir helfen herauszufinden, ob das der Fall ist. Legt beide Wächter hin und bringt mir ihre Kraftkerne. Sie werden uns enthüllen, was wir wissen müssen.", sourceObjective = "Beschafft Euch den Obsidiankraftkern und den Titankraftkern.", progress = "Wo sind die Kerne, mein Junge? Bei Muradins Bart, wo sind die verflixten Kerne?\n\n<Kand atmet tief durch.>\n\nTut mir leid. Konntet Ihr die Kerne an Euch bringen?", completion = "Das ist unglaublich, {name}. Die Kraft, die durch jeden dieser Kerne fließt... Die gegensätzlichen Kräfte so nah beieinander.\n\nIch bringe das sofort zu den richtigen Zwergen. Diese Kerne sind immens wichtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[27674] = { id = 27674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Oberfläche", description = "Nevin hat gerade gemeldet, dass er und seine Leute auf dem Weg zur Oberfläche sind. Er erwartet Euch in dem Gebäude, das S.I.C.H.E.R. zum Hauptquartier erkoren hat.\n\nSeht Ihr Torben Zischknall da hinten? Sprecht mit ihm, wenn Ihr zur Oberfläche aufbrechen wollt und er wird für den Transport sorgen. Es war mir ein Vergnügen, Euch kennenzulernen, {name}. Ich fühle mich geehrt, eine kleine Rolle bei Eurer Flucht aus Gnomeregan und dem Beginn Eures neues Lebens an der Oberfläche gespielt zu haben.", sourceObjective = "Sprecht mit Torben Zischknall, lasst Euch an die Oberfläche teleportieren und meldet Euch bei Nevin Drallzang.", completion = "Schön, Euch wiederzusehen, {name}. Ohne Eure Hilfe wäre es uns dieses Mal nicht gelungen, so viele Überlebende aus Gnomeregan zu retten. Alle wollen Euch treffen und Eure Geschichte hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27675] = { id = 27675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefälschte Dokumente", description = "Findet einen Bewohner in Sturmwind, der Eure gefälschten Dokumente annimmt.", progress = "Habt Ihr etwas für mich?", completion = "<Ihr überreicht die gefälschten Dokumente und wechselt dabei nur wenige Worte. Euer meisterhaftes Können spricht für sich selbst.>" }
quests[27676] = { id = 27676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter verschlossenen Türen", description = "Galgann Feuerhammer und seine Gruppe Dunkeleisenzwerge halten sich in Grabstelle Drei auf und bewachen dort eine Tür, von der wir nichts wissen! Es reicht! Ständig stören seine Leute unsere Arbeit. Die Forscherliga besitzt als einzige Gruppe die Erlaubnis, die Artefakte in Uldaman zu begutachten!\n\nGeht zur Grabstelle und werdet ihn los, damit wir unsere Arbeit ungestört fortsetzen können. Ich will wissen, was hinter dieser Tür ist!", sourceObjective = "Tötet Galgann Feuerhammer.", completion = "Großartig! Hervorragende Arbeit! Wir werden schon bald wissen, was sich in Grabstelle Drei verbirgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27677] = { id = 27677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, der alte Steinbehüter", description = "Das wahre Ziel in Uldaman ist es, die Scheiben von Norgannon zu erlangen. Die Geheimnisse auf diesen Scheiben könnte die Art, wie wir unsere Welt sehen, völlig verändern. Zahllose Geheimnisse der Schöpfer sind darauf aufgeschrieben... ihr Wert liegt über allem Materiellen, das Ihr Euch nur vorstellen könnt.\n\nDas Problem ist, das Archaedas, eine uralte und mächtige Konstruktion der Schöpfer, die Scheiben mit einer beachtlichen Armee zu seiner Verfügung beschützt. Ihr müsst ihn besiegen und die Scheiben für die Forscherliga sichern!", sourceObjective = "Besiegt Archaedas.", completion = "Gut gemacht, Mädel! Geht jetzt zu den Scheiben und erfahrt von ihnen so viel es geht!", sourceObjectiveStatus = "unverified-source-field" }
quests[27679] = { id = 27679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer von Khaz'mul", description = "In der Kartenkammer befindet sich eine verschlossene Tür, die zur legendären Kammer von Khaz'mul führen muss. Wir wissen noch nicht, was für Artefakte sich darin befinden.\n\nWas wir wissen, ist, dass sie von Ironaya, einer Titanenwächterin von immenser Größe und Macht bewacht wird. Ihr müsst sie bezwingen, wenn Ihr vorhabt, weiter in diesen Ort vorzudringen.", sourceObjective = "Besiegt Ironaya.", completion = "Agenten der Akademie sind unterwegs, um die Kammer zu untersuchen. Ihr habt Wichtigeres zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27680] = { id = 27680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, der alte Steinbehüter", description = "Das wahre Ziel in Uldaman ist es, die Scheiben von Norgannon zu erlangen. Diese Platinscheiben könnten uns unfassbare Macht verleihen. Zahllose Geheimnisse der Schöpfer sind darauf aufgeschrieben... ihr Wert liegt über allem Materiellen, das Ihr Euch nur vorstellen könnt.\n\nDas Problem ist, das Archaedas, eine uralte und mächtige Konstruktion der Schöpfer, die Scheiben mit einer beachtlichen Armee zu seiner Verfügung beschützt. Ihr müsst ihn besiegen und die Scheiben für die Archäologische Akademie sichern!", sourceObjective = "Besiegt Archaedas.", completion = "Ihr seid ein überaus verlässlicher Agent, {name}. Nähert Euch den Scheiben und findet heraus, soviel Ihr könnt. Erstattet mir sofort danach wieder Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27681] = { id = 27681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter verschlossenen Türen", description = "Galgann Feuerhammer und seine Gruppe Dunkeleisenzwerge halten sich in Grabstelle Drei auf und bewachen dort eine Tür, von der wir nichts wissen! Es reicht! Ständig stören seine Leute unsere Arbeit. Die Archäologische Akademie besitzt als einzige Gruppe die Erlaubnis, die Artefakte in Uldaman zu begutachten!\n\nGeht zur Grabstelle und werdet ihn los, damit wir unsere Arbeit ungestört fortsetzen können. Ich will wissen, was hinter dieser Tür ist!", sourceObjective = "Tötet Galgann Feuerhammer.", completion = "Gut gemacht! Grabstelle Drei und die Geheimnisse hinter dieser Tür werden bald uns und nur uns gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27682] = { id = 27682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen mehr Mineralien", description = "Die Titanen haben zwei uralte Steinbewahrer erbaut, um Uldaman vor möglichen Eindringlingen zu schützen und den täglichen Betrieb zu überwachen, während Ironaya und Archaedas schlafen. Einer davon ist noch voll funktionstüchtig und steht in der Tempelhalle. Der andere in der Echomokhöhle wurde jedoch von etwas verderbt.\n\nIch vermute, dass einer der alten Götter dahinter steckt, und Ihr werdet mir dabei helfen, dieser Vermutung nachzugehen. Überwältig beide Wächter und bringt mir ihre Kraftkerne. Sie werden uns alles sagen, was wir wissen müssen.", sourceObjective = "Besorgt den Obsidiankraftkern und den Titankraftkern.", progress = "Habt Ihr die Kerne bei Euch, oder wollt Ihr nur plaudern? Vielleicht sollten wir mit dem ganzen Quatsch hier aufhören und uns lieber ein paar Leckereien und ein feines Gläschen Wein gönnen?", completion = "Diese Kerne sind viel mächtiger als die meisten herkömmlichen Kerne, die wir benutzen, um unsere Beschützer mit Energie zu versorgen. Und diese Geräte sind uralt!\n\nVielen Dank. Sie werden sich sicher als besonders wertvoll für unsere Gesellschaft herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27683] = { id = 27683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wälder", description = "Letztens konnte ich ein seltsames Treiben in der Stadt beobachten. Es handelte sich um einen Pferdewagen voller Kisten und Truhen, mit einer Worgenfrau auf dem Kutschbock, einem Blutelfen an ihrer Seite und einem Zwergenpaladin, der hinter dem Wagen her lief und die kreativsten Obszönitäten rief, die ich seit langem gehört habe.\n\nSie schienen auf dem Weg in die Östlichen Pestländer zu sein, allerdings dürften sie bis jetzt kaum weiter als bis zum Fluss Thondroril gekommen sein. Ich frage mich, was sie vorhaben.", sourceObjective = "Sucht nach einer Worgenfrau am Fluss Thondroril in den Östlichen Pestländern.", completion = "Ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[27684] = { id = 27684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besucher", description = "Meine Quellen an der Stätte der Heiler haben mir verraten, dass wir bald einige Besucher erwarten dürfen. Eine Gruppe Paladine - die bizarrerweise von einer Worgenhändlerin angeführt wird - müsste bald hier eintreffen. Ich freue mich, sie kennenzulernen. Vor allem einen.\n\nWärt Ihr so nett, kurz nach ihnen zu sehen? Ich bin mir zwar nicht sicher, aber wenn Ihr dort eintrefft, sollten sie gerade den Fluss Thondroril weit im Westen überqueren.", sourceObjective = "Sucht nach einer Worgenfrau am Fluss Thondroril in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27685] = { id = 27685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gute Tat bleibt unvollständig", description = "'N Tag, <Kumpel/Mädel>.\n\nIch bin Rendel.\n\nSieht aus, als wär'n die gute alte Moanah und ich gerade rechtzeitig hier eingetroffen, was?\n\nErunak hat nicht gescherzt, als er sagte, es ginge um Leben oder Tod!\n\nDa wir uns so beeilt ha'm, hierher zu kommen, ha'm wir ein Stück im Osten ein paar unerledigte Aufgaben zurückgelassen.\n\nDa war eine kleine Lady, die nur knapp dem Tode entronnen is'. Wir hatten keine andere Wahl, als sie bei einem kleinen Luftstrom zurückzulassen, nachdem wir sie gerettet ha'm.\n\nWarum geht Ihr nicht dorthin und helft ihr, solange die Zeit es zulässt?", sourceObjective = "Sprecht mit Adarrah im Tang'tharwald.", completion = "Oh, endlich!\n\nIch weiß nicht, wie lange ich noch durchhalte!", sourceObjectiveStatus = "unverified-source-field" }
quests[27686] = { id = 27686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefälschte Dokumente", description = "Findet einen Bewohner in Orgrimmar, der Eure gefälschten Dokumente annimmt.", progress = "Habt Ihr etwas für mich?", completion = "<Ihr überreicht die gefälschten Dokumente und wechselt dabei nur wenige Worte. Euer meisterhaftes Können spricht für sich selbst.>" }
quests[27687] = { id = 27687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz ohne Zähneknirschen", description = "Was für eine Leistung, einen solch mächtigen Meerriesen zu erlegen!\n\nDie neuen Bewohner des Schmugglerschmisses werden sich bestimmt sehr viel sicherer fühlen, wenn dieses Monster nicht mehr vor ihrer Zuflucht herumlungert.", sourceObjective = "Bringt Nagers Kopf zu Samir im Schmugglerschmiss.", progress = "Ihr habt diesen Meeresriesen erlegt, {class}?", completion = "Es ist nicht viel, aber es ist alles, was ich hier unten habe.\n\nIch gebe es Euch von Herzen gerne, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27688] = { id = 27688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lenkt sie für mich ab", description = "Es gibt drei Anwärter auf die Aszendenz, die wir beseitigen müssen: Freifrau Alys Finnsson, Meister Klem und Mia die Rose.\n\nIch möchte, dass Ihr als Ablenkung dient. Wenn der rechte Moment gekommen ist, werde ich hinzukommen und sie von hinten erledigen.\n\nEgal was Ihr tut, Ihr dürft sie auf keinen Fall unterschätzen, {name}. Jeder von ihnen hat sich seine Position durch Skrupellosigkeit erkämpft, und sie sind gut in dem, was sie tun.", sourceObjective = "Tötet Freifrau Alys Finnsson, Meister Klem und Mia die Rose.", completion = "Damit hätten wir einen Großteil ihrer Anführer außerhalb der Bastion erledigt.\n\nWir sind ein gutes Team, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27689] = { id = 27689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lenkt sie für mich ab", description = "Es gibt drei Anwärter auf die Aszendenz, die wir beseitigen müssen: Freifrau Alys Finnsson, Meister Klem und Mia die Rose.\n\nIch möchte, dass Ihr als Ablenkung dient. Wenn der rechte Moment gekommen ist, werde ich hinzukommen und sie von hinten erledigen.\n\nEgal was Ihr tut, Ihr dürft sie auf keinen Fall unterschätzen, {name}. Jeder dieser Wahnsinnigen hat sich seine Position durch Skrupellosigkeit erkämpft, und sie sind gut in dem, was sie tun.", sourceObjective = "Tötet Freifrau Alys Finnsson, Meister Klem und Mia die Rose.", completion = "Damit hätten wir einen Großteil ihrer Anführer außerhalb der Bastion des Zwielichts erledigt. Keine schlechte Arbeit, {name}. Ganz und gar nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27690] = { id = 27690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, der Drachenzähmer", description = "{name}, die Feste in der Blutschlucht bildet das Herz des Drachenmalreiches im Schattenhochland. Sie befindet sich direkt den Fluss entlang. Narkrall Harkenklaue nutzt seine beträchtliche Macht, um dort einen Drachenreitergeschwader zu versammeln.\n\nDamit das Drachenmal Erfolg hat, muss die Blutschlucht Erfolg haben. Geht zu Narkrall und stellt sicher, dass dies der Fall ist.", sourceObjective = "Meldet Euch bei Narkrall Harkenklaue in der Blutschlucht im Schattenhochland.", completion = "<Narkrall mustert Euch.>\n\nNoch so ein weinerlicher Welpe der Horde? Zaela raubt uns unsere Stärke, indem sie unsere Truppen mit dem Blut der Schwachen verwässert. Nun gut, {class}. Beweist Euch und zeigt mir, aus welchem Holz Eure Horde geschnitzt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27691] = { id = 27691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschflossenwahnsinn", description = "Ich fürchte, der Rest des Dampfdruckkartells ist tot. Alle jungen in dem Lager im Osten waren verloren, als die Murlocs kamen.\n\nJa, an diesen Ufern sind immer Murlocs... aber nicht so viele. Sie kamen in Scharen nachts aus dem Meer, heulten und schäumten und schwärmten an Land, um anzugreifen!\n\nWir können nicht zulassen, dass sie weiter hier herumrennen, nicht wahr? Würdet Ihr einem alten Goblin seinen Seelenfrieden zurückgeben und einige von ihnen wieder ins Wasser zurücktreiben?", sourceObjective = "Tötet 12 Murlocs der Marschflossen.", progress = "Ich habe immer noch ein paar Asse im Ärmel, aber ich werde nicht mit den Murlocs kämpfen, wenn es nicht sein muss.", completion = "Man muss sich doch fragen, was da draußen ist. Dies ist die Küste des Verbotenen Meers. Dahinter befindet sich nichts... doch dieses ganze Fischgesindel kam direkt dort heraus.\n\nSchlimmer noch, ich sah, wo sie hingingen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27692] = { id = 27692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzessin Theradras", description = "Fürchtet Euch nicht, <junger/junge> {race}. Ich bin Zaetar, Sohn des Cenarius, und ich komme, um Euch um Hilfe zu bitten.\n\nVor langer Zeit machte ich den Fehler, mich mit Prinzessin Theradras einzulassen, einer mächtigen Erdelementarin, die den Alten Göttern unterstand. Unsere Kinder, die Khans der Zentauren, wandten sich schon bei ihrer Geburt gegen mich und töteten mich ohne Gnade. Nun ist Theradras Verderbnis weit fortgeschritten und bedroht weit mehr als nur Maraudon.\n\nKommt und tötet sie, und befreit meinen Geist, sodass wir Desolace in einen Ort des blühenden Lebens und der Verheißung verwandeln können, wie Cenarius es gewollt hätte.", sourceObjective = "Tötet Prinzessin Theradras und kehrt zu Zaetars Geist zurück.", completion = "Danke, {name}. Wie Ihr sehen könnt, hat meine bloße Anwesenheit hier üppiges Leben entspringen lassen, trotz der Anwesenheit meines Gefährten. Ungeachtet des Namens werdet Ihr vielleicht eines Tages wieder nach Desolace reisen und eine blühende Oase frei von jeder Sput der Alten Götter vorfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27693] = { id = 27693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel des Wächters", description = "Ihr seht, wie sich die Statue erst in zwei, dann in vier, dann in acht identische Statuen in quadratischer Anordnung teilt.\n\nIhr hört eine Stimme, jedoch nicht mit Euren Ohren, sondern direkt in Eurem Kopf:\n\n\"Ein wahrer Wächter sieht nicht nach AUSSEN, um nach Anzeichen der Gefahr zu suchen.\n\n Ein wahrer Wächter richtet seinen Blick nach INNEN, immer darauf konzentriert, seine Beute zu schützen.\"\n\nVielleicht ist dies eine Art Rätsel?", sourceObjective = "Beendet das Spiel des Wächters, indem Ihr die Bauern des Wächters in eine nach innen gerichtete Position teleportiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27694] = { id = 27694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränenteich", description = "Die Trolle, die in diesem Tempel lauern, haben meiner Art Schreckliches angetan, {name}. Wir wurden hierher geschickt, um diesen Ort zu schützen, und stattdessen wurden wir benutzt, um die fürchterlichen Mächte darin zu entfesseln.\n\nIch flehe Euch an, um die Hilfe, die nur ein Sterblicher leisten kann. Ihr könnt meine Hand im Tempel sein; würde ich allein eintreten, könnte auch ich gegen meine Brüder gewendet werden.\n\nWir werden einen Pakt schließen. Wenn Ihr mir helfen wollt, sammelt Artefakte der Atal'ai aus den Wassern um den Tempel herum, und bringt sie zu mir.", sourceObjective = "Sammelt 5 Artefakte der Atal'ai aus dem Tränenteich um den Tempel von Atal'Hakkar herum.", progress = "Diese Artefakte zu sammeln wird Eure Vertrauenswürdigkeit unter Beweis stellen. Sobald das geschehen ist, werde ich das Ritual durchführen.", completion = "Die Essenz des grünen Drachenschwarms entströmt diesen Artefakten; die Überbleibsel meiner verderbten Verwandten. Indem ich sie reinige, schließe ich einen Bund zwischen uns.\n\nTretet hervor, {name}, und empfangt den Schwurstein von Yseras Drachenschwarm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27695] = { id = 27695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elementiumaxt", description = "Diese Feiglinge des Schattenhammers haben so viele rote Drachen gefangen und getötet, aber einer ist immer noch am Leben. Erinnert Ihr Euch an Lirastrasza? Sie ist in der Nähe angekettet, und wir werden sie befreien.\n\nAber zuerst brauchen wir etwas, das scharf genug ist, um ihre Ketten zu zerschlagen.\n\nAm Altar des Aufstiegs im Süden wacht ein alter Ettin namens Blindauge der Wächter.\n\nIn seinem Besitz befindet sich eine fein gearbeitete Axt aus Elementium. Ich frage mich, ob das wohl Cho'galls \"ultimative\" Waffe ist.", sourceObjective = "Beschafft Euch die Elementiumaxt.", progress = "Habt Ihr die Axt? Sie werden Lirastrasza bald töten.", completion = "Das Ding sieht verdammt scharf aus. Zumindest scharf genug, um seinen Zweck zu erfüllen.\n\nIch für meinen Teil schätze, dass dies nicht die Bewaffnung ist, hinter der Cho'gall her ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27696] = { id = 27696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elementiumaxt", description = "Diese Feiglinge des Schattenhammers haben so viele rote Drachen gefangen und getötet, aber einer ist immer noch am Leben. Erinnert Ihr Euch an Lirastrasza? Sie ist in der Nähe angekettet, und wir werden sie befreien.\n\nAber zuerst brauchen wir etwas, das scharf genug ist, um ihre Ketten zu zerschlagen.\n\nAm Altar des Aufstiegs im Süden wacht ein alter Ettin namens Blindauge der Wächter.\n\nIn seinem Besitz befindet sich eine fein gearbeitete Axt aus Elementium. Ich frage mich, ob das wohl Cho'galls \"ultimative\" Waffe ist.", sourceObjective = "Beschafft Euch die Elementiumaxt.", progress = "Habt Ihr die Axt?", completion = "Das ist eine verdammt scharfe Axt. Sie wird ihren Zweck erfüllen, aber ich für meinen Teil schätze, dass dies nicht die Bewaffnung ist, hinter der Cho'gall her ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27697] = { id = 27697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis in Maraudon", description = "{name}, ich benötige sofort Eure Unterstützung! Ich bin Zaetar, Sohn des Cenarius, und ich sitze hier aufgrund einer Reihe unglücklicher Ereignisse fest! Bevor man überhaupt daran denken kann, mich zu retten, müsst Ihr mir helfen, die Verderbnis, die von Maraudon Besitz ergriffen hat, auszumerzen.\n\nLord Schlangenzunge ist der Satyr, der über die purpurnen Kristallhöhlen herrscht. Er ist ein heimtückisches Mitglied der brennenden Legion und wird durch seine Anwesenheit Chaos und Tod bringen. Er darf nicht länger leben!", sourceObjective = "Tötet Lord Schlangenzunge und kehrt zu Zaetars Geist zurück.", completion = "Hervorragende Arbeit, {name}! Schlangenzunges Tod ist ein wichtiger Schritt auf dem Weg zu meiner Rettung und letzten Endes auch zur Rettung dieses Landes vor der Verderbnis. Nehmt dies als Zeichen meiner Dankbarkeit und als Anregung, Eure Arbeit hier fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27698] = { id = 27698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von Theradras", description = "Prinzessin Theradras, meine ehemalige Gefährtin, hat ihre enormen Mächte benutzt, um die Natur von Maraudon selbst zu verderben. In diesem Moment wüten iher Geschopfe dort, und ich fürchte, dass sie bald in die Welt entkommen werden, um dort die Saat von Tod und Verwüstung zu streuen.\n\n{name}, geht und tötet Noxxion und Schlingwurzler. Sie sind ihre zwei mächtigsten Diener, und ihre Tode würden der kaltherzigen Prinzessin verdientermaßen selbst Leid und Trauer bringen. Vielleicht könnt ihr mir dann helfen, meinen Geist aus ihrer Umklammerung zu befreien.", sourceObjective = "Tötet Noxxion und Schlingwurzler und kehrt zu Zaetars Geist zurück.", completion = "Ohne ihre mächtigen Diener ist Prinzessin Theradras wesentlich verwundbarer. Macht ihren Untschlupf ausfindig, {name}... es ist an der Zeit, dass wir zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27699] = { id = 27699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unhaimlich", description = "Das ist ein ganz schön starker Hai!\n\nIhr beschließt, dass es im besten Sinne aller wäre, wenn Ihr versucht, Budd abzulenken, damit er seine Aufmerksamkeit nie wieder auf Nager und dieses Skelettriff richtet.\n\nVielleicht erweisen die Zähne dieser Bestie sich als fesselnd genug...", sourceObjective = "Sammelt 5 von Nagers Zähnen im Skelettriff.", progress = "Was habt Ihr da, Kumpel?", completion = "Was?!\n\nNager ist nicht tot?!\n\nDas macht meine Hoffnung auf das schnelle Gold wohl genauso schnell wieder zunichte…\n\nDiese riesigen Haizähne sind zwar ganz nett, aber wir dürfen nicht aufhören, bis der Glitzerkram uns gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[27700] = { id = 27700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entfesselte Drache", description = "Lirastrasza ist der letzte und größte der roten Drachen, die der Schattenhammer gefangen hat. Sie stehen kurz davor, sie zu töten, {class}.\n\nIhr müsst die Elementiumaxt nehmen und sie von ihren Ketten befreien.", sourceObjective = "Benutzt die Elementiumaxt, um die gefangene Lirastrasza aus ihren Ketten zu befreien.", completion = "Ist sie nicht wunderschön?\n\nIch bin gespannt, was sie jetzt mit ihrer Freiheit anstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27701] = { id = 27701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entfesselte Drache", description = "Lirastrasza ist der letzte und größte der roten Drachen, die der Schattenhammer gefangen hat. Sie stehen kurz davor, sie zu töten, {class}.\n\nIhr müsst die Elementiumaxt nehmen und sie von ihren Ketten befreien, bevor sie es tun.", sourceObjective = "Benutzt die Elementiumaxt, um die gefangene Lirastrasza aus ihren Ketten zu befreien.", completion = "Ist sie nicht wunderschön? So anmutig.\n\nIch hoffe, sie kann ihren Rachedurst stillen. Und noch viel mehr…", sourceObjectiveStatus = "unverified-source-field" }
quests[27702] = { id = 27702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnadenstoß", description = "Schaut Euch das an! Lirastrasza vernichtet sie!\n\nIhr müsst jedoch noch ein paar der Drachen, die sie aus der Luft geholt hat, den Rest geben, {name}. Wir wollen schließlich nicht, dass die Heiler des Schattenhammers sie wieder flugtauglich machen.\n\nEs wird Zeit für einen Gnadenstoß.", sourceObjective = "Versetzt 5 Himmelsschrecken der Zwielichtdrachen einen Gnadenstoß.", completion = "Unsere Bemühungen zur Verbesserung der Beziehungen zum roten Drachenschwarm haben sich wirklich ausgezahlt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27703] = { id = 27703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnadenstoß", description = "Schaut Euch das an! Lirastrasza vernichtet sie!\n\nIhr müsst jedoch noch ein paar der Drachen, die sie aus der Luft geholt hat, den Rest geben, {name}. Wir wollen schließlich nicht, dass diese stinkenden Heiler des Schattenhammers sie wieder flugtauglich machen.\n\nEs wird Zeit für einen Gnadenstoß.", sourceObjective = "Versetzt 5 Himmelsschrecken der Zwielichtdrachen einen Gnadenstoß.", completion = "Welch Glück, dass Ihr und Kriegsfürst Krogg Euch mit den roten Drachen angefreundet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27704] = { id = 27704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legenden des Versunkenen Tempels", description = "Ihr müsst zuerst den Tempel betreten, {name}. Ich kann Euch folgen, wenn der Weg sicher ist, aber ich wage es nicht, blindlings hineinzugehen. Würde ich mich gegen mein Volk wenden, wäre ich ein gefährlicher Feind.\n\nIhr könnt die Treppen hinter mir hinuntersteigen. Dann schwimmt durch die überfluteten Tiefen der zerstörten Hallen. Danach folgt dem Tunnel zur Rechten, um zur Halle der Masken zu gelangen.\n\nNehmt Euch vor den Tempelwachen in Acht. Sobald Ihr die Halle der Masken gefunden habt, werde ich mich durch den Schwurstein mit Euch in Verbindung setzen.", sourceObjective = "Begebt Euch durch die Vorräume des Tempels zur Halle der Masken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27705] = { id = 27705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erster Schritt: Die Priesterin", description = "Meine Brüder werden hier abgeschlachtet. Genau, wie ich mir gedacht hatte.\n\nIch muss Euch nochmals um Hilfe bitten, bevor ich eintrete, {name}. In einem Gang außerhalb dieses Raums führt der Weg nach rechts und links. Rechts geht es zur Kammer des Bluts. Dort führen die Atal'ai ihre finsteren Rituale durch.\n\nSie bereiten sich schon jahrelang auf einen Gegner wie mich vor, aber nicht auf einen wie Euch. Betretet die Kammer des Bluts und tötet Priesterin Udum'bra. Sie ist eine von drei bösartigen Präsenzen hier, die entfernt werden müssen, bevor ich eintreten kann.", sourceObjective = "Besiegt Priesterin Udum'bra in der Kammer des Bluts.", sourceObjectiveStatus = "unverified-source-field" }
quests[27706] = { id = 27706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zepter von Orsis", description = "Das Schloss der Truhe öffnet sich mit lautem Klicken, als Ihr die beiden Steine in die Plakette einsetzt.\n\nNehmt das Zepter an Euch und bringt es zu General Ammantep.", sourceObjective = "Holt das Zepter von Orsis aus dem heiligen Gefäß.", progress = "Ihr seid zurück, {name}.", completion = "Also... das ist es, was Al'Akir die ganze Zeit wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27707] = { id = 27707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gefängnis von Neferset", description = "Hieroglyphen, die einen angeketteten Tol'vir zeigen, befinden sich in der südöstlichen Ecke der Karte.\n\nVielleicht wurde Tahet dorthin gebracht, als man ihn gefangen nahm.", sourceObjective = "Geht in das Gefangenenlager von Neferset und findet etwas über den Aufenhaltsort Tahets heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[27708] = { id = 27708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit des Aufsehers", description = "<Erunaks Bildnis formt sich in Eurem Geist.>\n\nIhr habt gute Arbeit geleistet, {name}, aber es bleibt noch eines zu tun.\n\nBevor wir von hier fortgehen, sollten wir ein wenig Unordnung stiften.\n\nFindet denjenigen, der diese Naga anführt und lasst ihn für seine Untaten bezahlen.", sourceObjective = "Erunak Steinsprecher möchte, dass Ihr Aufseher Azjakir in der Umklammerung tötet.", completion = "Es ist gut, dass ihre Pläne durchkreuzt wurden.\n\nBald muss ich weiterziehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[27709] = { id = 27709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schildwachenspiel", description = "Als Ihr die Statue an ihren Platz setzt, erscheinen weitere Steinstatuen im Raum. In einem kleinen Gehäuse am anderen Ende des Raums erscheint auch eine rubinrote Statue. Ihr hört eine Stimme:\n\n \"Die Schildwache sieht.\n\n Die Schildwache beschützt.\n\n Der Blick der Schildwache versagt nie.\"\n\nDie rote Statue auf der anderen Seite des Raums erscheint Euch wichtig. Vielleicht solltet Ihr versuchen, die beiden roten Statuen miteinander zu verbinden?", sourceObjective = "Beendet das Spiel der Schildwache, indem Ihr die beiden roten Statuen miteinander verbindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27711] = { id = 27711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Elementiumtiefen", description = "Der Initiand der Erdenruferin, Goldmine, braucht Euch.\n\nIch glaube, Ihr sollt ihn in dieser Mine unterstützen, was auch immer sich dort befinden mag.", sourceObjective = "Sprecht mit Initiand Goldmine vor den Elementiumtiefen im Schattenhochland.", completion = "{name}, bin ich froh, dass Ihr zurück seid! Ich habe eine spaßige Aufgabe für uns beide!", sourceObjectiveStatus = "unverified-source-field" }
quests[27712] = { id = 27712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Elementiumtiefen", description = "Die Erdenruferin hat einen Goblininitianden? Und er heißt Goldmine? Jedenfalls braucht er Euch.\n\nIch glaube, Ihr sollt für ihn die Drecksarbeit in dieser Mine erledigen, was auch immer sich dort befinden mag.", sourceObjective = "Sprecht mit Initiand Goldmine vor den Elementiumtiefen im Schattenhochland.", completion = "{name}, bin ich froh, dass Ihr zurück seid! Ich habe eine spaßige Aufgabe für uns beide!", sourceObjectiveStatus = "unverified-source-field" }
quests[27713] = { id = 27713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem Todesschwinge kam", description = "Todesschwinge hat ein ganz schönes Chaos angerichtet, als er hier durchgekommen ist. Ohne mich wäre er wahrscheinlich noch immer hier und würde all die Einwohner des Ödlands umbringen.\n\nWas, Ihr glaubt mir nicht? Gut, lasst mich Euch die ganze Geschichte erzählen.", sourceObjective = "Hört Euch Theldurins Geschichte an.", completion = "Eine ganz schöne Geschichte, nicht wahr? Jetzt wisst Ihr, warum Todesschwinge seitdem nicht mehr hierher zurückgekehrt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27714] = { id = 27714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem Todesschwinge kam: Die wahre Geschichte", description = "Theldurins Geschichte war nicht nur falsch, sie war langweilig, einfallslos und langatmig.\n\nIch sage Euch, was an dem Tag wirklich geschehen ist.", sourceObjective = "Hört Euch Lucien Knobelzangs Version der Geschichte an.", progress = "Ich bin noch nicht mit meiner Geschichte fertig. Setzt Euch wieder hin.", completion = "Ende! Und die Moral von der Geschicht' gibt es nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27715] = { id = 27715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem Todesschwinge kam: Was wirklich geschah", description = "Die beiden haben keine Ahnung, wie man eine Geschichte erzählt. Theldurins Geschichte war zu kurz und Luciens Erzählung war ein bisschen zu ausschweifend, falls Ihr versteht, was ich meine.\n\nAußerdem kamen in beiden Geschichten weder Nervenkitzel noch Fans vor, die meine Genialität bewundern.\n\nLehnt Euch zurück, {name}. Ich erzähle Euch, was damals wirklich geschah.", sourceObjective = "Hört Euch Marteks Version der Geschichte an.", completion = "Ich fasse es nicht, dass mich diese Typen einfach so unterbrochen haben. Und dabei lief meine Geschichte gerade so gut...\n\nWie dem auch sei, danke, dass Ihr so lange zugehört habt. Es ist schön, jemand neues zum Geschichten erzählen zu haben. Ich bin mir sicher, dass Lucien und Theldurin das genauso sehen.\n\nHabt Ihr eine Geschichte, die Ihr mit uns teilen wollt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27716] = { id = 27716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stück Vergangenheit", description = "<Eine uralte, leicht zerbrochene Steintafel mit einer Unmenge von Inschriften auf allen Seiten. Ihr könnt die Sprache nicht lesen, aber die schiere Menge an Text und der fast ornamental wirkende Charakter des Steins lassen drauf schließen, dass er von großem Wert sein muss.>\n\n<Levia Traumwächter bei den Überlebenden von Nespirah hat genau nach so etwas gesucht.>", sourceObjective = "Bringt die uralte Elfengravur zu Levia Traumwächter. Ihr solltet sie bei den Überlebenden von Nespirah der Allianz finden.", progress = "Ha! Habt Ihr gesehen, wie der Admiral mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint der Einzige zu sein, dem ich vertrauen kann. Wartet... was habt Ihr da?", completion = "Ausgezeichnet! Ich werde ein bisschen brauchen, bis ich es übersetzt haben, aber genau das hatte ich zu finden gehofft.\n\nKeine Ahnung, ob wir je von hier entkommen. Aber wenn es hart auf hart kommt, finde ich schon einen Weg, dies hier an die Oberfläche treiben zu lassen, damit es eines Tages gefunden wird.\n\nNochmals danke, {name}. Hier... Vielleicht habe ich etwas, das Ihr gebrauchen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27717] = { id = 27717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stück Vergangenheit", description = "<Eine uralte, leicht zerbrochene Steintafel mit einer Unmenge von Inschriften auf allen Seiten. Ihr könnt die Sprache nicht lesen, aber die schiere Menge an Text und der fast ornamental wirkende Charakter des Steins lassen drauf schließen, dass er von großem Wert sein muss.>\n\n<Elendri Goldbraue bei den Überlebenden von Nespirah hat genau nach so etwas gesucht.>", sourceObjective = "Bringt die uralte Elfengravur zu Elendri Goldbraue. Ihr solltet sie bei den Überlebenden von Nespirah der Horde finden.", progress = "Ha! Habt Ihr gesehen, wie der Hauptmann mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint der Einzige zu sein, dem ich vertrauen kann. Wartet... was habt Ihr da?", completion = "Ausgezeichnet! Mit den Werkzeugen, die ich Euch gegeben habe, hätte ich nicht mehr erwarten können.\n\nIch sollte die Lücken füllen und den Text schnell in eine schriftliche Form bringen können. Keine Ahnung, ob wir je von hier entkommen. Aber wenn es hart auf hart kommt, finde ich schon einen Weg, dies hier an die Oberfläche treiben zu lassen, damit es eines Tages gefunden wird.\n\nNochmals danke, {name}. Ihr seid nicht übel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27718] = { id = 27718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Vashj'ir!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kommandant Thorak in der Messerbucht in Durotar zu melden.\n\nWir brauchen Eure Hilfe im Kampf gegen unseren verhassten Feind, die Allianz, mehr denn je!\n\nReist nach Süden durch das Haupttor von Orgrimmar nach Durotar. Folgt von dort aus dem Pfad nach Osten zur Küste. Dort findet ihr die Messerbucht. Thorak hält sich an seinem Posten in der Nähe der Docks auf.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Meldet Euch bei Kommandant Thorak in der Messerbucht in Durotar.", completion = "Lok'tar, Bruder! Ihr kommt genau rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27719] = { id = 27719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser des Lebens", description = "Nehmt mein Wasser des Lebens und gebt es auf den Leichnam des ertrunkenen Zwergs.\n\nAls er lebte, bearbeitete er Metall. Und obwohl sein Leichnam jetzt meinen Loch nährt, kann er Euch dank des Wassers sagen, was Ihr wissen wollt.\n\nNehmt dann Eure Informationen und verschwindet von meinem Besitz.", sourceObjective = "Benutzt das Wasser des Lebens, um dem Leichnam von Schmiedemeister Finlay Informationen zu entlocken.", completion = "Der Schattenhammer? Und diese Informationen habt Ihr also von einem ertrunkenen Zwerg der Wildhämmer?\n\nIhr macht Scherze, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27720] = { id = 27720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilde Fahrt des Herrn Goldmine", description = "In Ordnung, {name}. Wir müssen zum Erdportal an der anderen Seite der Höhle gelangen.\n\nIch habe ein Gefährt für uns \"gesichert\". Warum laufen, wenn man stilvoll fahren kann? Ich hoffe, Ihr habt nichts gegen Minenwagen.\n\nGebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Fahrt zusammen mit Initiand Goldmine im Minenwagen bis zum Ende der Strecke.", completion = "Oh nein! Meine Waffen und Totems!\n\nSie sind dahin!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[27721] = { id = 27721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Hyjal!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandtem Schwarzhuf, um Zugang zur Mondlichtung zu erlangen. Schwarzhuf hält sich im Taurenviertel im Tal der Weisheit in Orgrimmar auf.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Sprecht mit Cenarius' Abgesandtem Schwarzhuf, um auf die Mondlichtung zu reisen.", progress = "Schwarzhuf schickt Euch?", completion = "Wir wussten, dass die Horde Hilfe schicken würde. Und Ihr kommt keine Sekunde zu früh!", sourceObjectiveStatus = "unverified-source-field" }
quests[27722] = { id = 27722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Tiefenheim!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar zu melden.\n\nDer Irdene Ring, der von unserem ehemaligen Kriegshäuptling Thrall angeführt wird, braucht unsere Hilfe! Es wurde uns berichtet, dass die Elementarebene Tiefenheim droht, unsere Welt zu übernehmen!\n\nDer Westliche Erdschrein befindet sich direkt nördlich des Tals der Weisheit.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Sprecht mit Scharfseher Krogar am Westlichen Erdschrein in Orgrimmar.", completion = "Unsere Welt ist in Gefahr, {name}! Wir brauchen die Hilfe überragender Helden wie Ihr es seid, um sie zu retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27724] = { id = 27724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Vashj'ir!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rekrutierer Burns im Hafen von Sturmwind zu melden.\n\nDie kürzlichen Angriffe der Horde auf unsere Handelsschiffe müssen schnell und gerecht geahndet werden!\n\nDer Hafen von Sturmwind befindet sich im Nordwesten von Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Rekrutierer Burns im Hafen von Sturmwind in Sturmwind.", completion = "All unsere Kriegsschiffe befinden sich bereits im Kampf gegen die Horde, also werdet Ihr ein Söldnerschiff nehmen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27725] = { id = 27725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdhütte Quel'Danil", description = "Es mag Euch fern der Heimat erscheinen, {class}, aber ein großer Teil meines Volkes wurde von Botschafter Rualeth hierher geführt. Wir haben uns bei den Hochelfen der Jagdhütte Quel'Danil im Nordwesten niedergelassen, um den Weg des Lichts zu erlernen und die friedliche Schönheit dieses Landes zu genießen.\n\nEin derartiger Frieden könnte sehr kurzlebig sein. Wir haben gesehen, dass die Horde sich weiter nach Westen bewegt. Könntet Ihr nach Quel'Danil reisen und Anachoretin Traska warnen? Ihre Hütte befindet sich etwas nördlich des Hauptgebäudes.", sourceObjective = "Sprecht mit Anachoretin Traska bei der Jagdhütte Quel'Danil.", completion = "Yoro schickt uns eine Warnung vor der Horde? Die Elfen Hochtals haben einen Angriff bereits längere Zeit befürchtet. Um genau zu sein, haben wir...\n\n<Schreie und der Klang berstenden Metalls sind aus dem Süden zu hören.>\n\nBeim Lichte... sie sind hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27726] = { id = 27726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Hyjal!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandter Jademond in Sturmwind, um Zugang zur Mondlichtung zu erlangen.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Cenarius' Abgesandter Jademond, um auf die Mondlichtung zu reisen.", completion = "Wir wussten, dass die Allianz Hilfe schicken würde. Und Ihr kommt keine Sekunde zu früh!", sourceObjectiveStatus = "unverified-source-field" }
quests[27727] = { id = 27727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Tiefenheim!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Naraat dem Erdsprecher am Östlichen Erdschrein in Sturmwind zu melden.\n\nDer Irdene Ring braucht unsere Hilfe! Uns wurde berichtet, dass die Elementarebene Tiefenheim droht, unsere Welt zu übernehmen und alles Leben in Azeroth zu zerstören!\n\nDer Östliche Erdschrein befindet sich direkt nordwestlich der Burg Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!", sourceObjective = "Sprecht mit Naraat dem Erdsprecher am Östlichen Erdschrein in Sturmwind.", completion = "Unsere Welt ist in Gefahr, {name}! Wir brauchen die Hilfe überragender Helden wie Ihr es seid, um sie zu retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27729] = { id = 27729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmaal mit Gefühl", description = "Aale gehören zu den widerlichsten Wesen in ganz Azeroth.\n\nSicher, da gibt es diejenigen, denen sie angeblich egal sind. Und dann noch diejenigen, die sogar behaupten, sie zu mögen.\n\nSie lügen.\n\nIn Wahrheit mag nämlich niemand Aale. Nicht einmal Aale mögen Aale.\n\nAzeroth wäre ein besserer Ort, wenn niemand sich ausmalen müsste, wie ein glitschiger Aal sich aus den trüben Tiefen hervor windet und zubeißt.\n\nMitten ins Gesicht.", sourceObjective = "Tötet 8 beliebige Aale im Tang'tharwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[27733] = { id = 27733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gute alte Hütchenspiel", description = "Seht mal, ich würde ja liebend gern den Befehl geben und meine Männer diese Rebellen in Stücke sprengen lassen, aber das kann ich nicht, weil das gesamte Verlies unter Befehl von Aufseher Thelwasser steht, und er will sie im Moment nur einsperren.\n\nStatt sich Befehlen zu widersetzen, werden wir das Ganze auf andere Art lösen! Wir haben uns mit Mortimer Moloch angefreundet, der rein zufällig der Zwillingsbruder des ruchlosen Rebellenanführers Randolph Moloch ist. Tötet Randolph, und wir tauschen sie aus, sodass Mortimer die Rebellion friedlich beenden kann!", sourceObjective = "Tötet Randolph Moloch.", completion = "Ja, Mortimer hat gerade seinen eigenen Tod vorgetäuscht. Er wird vermutlich den Namen seines Bruders annehmen und seine \"epischen Pläne\" weiterführen. Damit müssen wir fertig werden, wenn es soweit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27737] = { id = 27737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst das Feuer Euch erretten!", description = "Ich kenne mich gut mit Erster Hilfe und anderen Formen des Heilens aus, und dank meines Lichtbrunnens ist es mir gelungen, vielen unserer Männer ihre Gesundheit zurückzugeben. Doch es ist so kalt und feucht hier unten, dass ich sie verliere, obwohl ich ihre Wunden geheilt habe!\n\nDie Beben haben die Elemente, die in dem Gefängnis hausen, verärgert... als sie aus der Erde emporbrachen, töteten sie die Hälfte der Gefangenen. Wenn Ihr ihren Anführer, Fürst Gluthitze, töten und mir seinen Kern bringen würdet, könnte ich meine Männer aufwärmen!", sourceObjective = "Beschafft Fürst Gluthitzes Feuerkern.", progress = "Habt Ihr den Kern? Unsere Männer sterben hier unten!", completion = "Wunderbar! Dank des Feuers werden unsere Männer diese Prüfung überstehen!\n\nVielen Dank, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[27738] = { id = 27738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schuppengrube", description = "Ein Punkt am südlichen Rand der Karte wurde mit Hieroglyphen von gegeneinander kämpfenden Krokodilen markiert.\n\nDas muss der Ort sein, an den Caimas Tahet gebracht hat.\n\nBegebt Euch zur Schuppengrube und findet einen Weg, um den Sohn des Wesirs zu retten.", sourceObjective = "Rettet Tahet aus der Schuppengrube in Uldum.", completion = "Ich danke Euch für das, was Ihr getan habt, {name}. Ihr könnt Euch meiner Stimme sicher sein, wenn der Hohe Rat zusammentritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27739] = { id = 27739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König der Gnolle", description = "{name}, ich muss das Unmögliche von Euch verlangen.\n\nIch habe meine Augenklappe, weil er es wollte. Unzählige Unschuldige sind seinem Zorn zum Opfer gefallen. Nur durch ein Wunder konnten wir ihn hier einsperren.\n\nUnd das war ein schwerer Fehler. Wir haben so lange ausgehalten, wie wir konnten, doch dann kamen sie. Aus den Schatten und der Dunkelheit rissen Gnolle, die Hogger dienten, meine besten Männer in Stücke.\n\nIhr müsst den Gnollkönig besiegen, sonst wird er einen weiteren Angriff befehlen und uns alle in kaltem, blutdürstigen Zorn töten.", sourceObjective = "Besiegt Hogger.", completion = "Eine Tat wie die Eurige habe ich in meiner langen Karriere noch nicht gesehen. Hoggers Tod wird noch auf Jahre hinweg einen Schatten auf die Flusspfotengnolle werfen und ihren Angriffen auf unser Volk hoffentlich ein Ende bereiten.\n\nHeld aller Helden, bitte nehmt dies als Zeichen meiner ewigen Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27740] = { id = 27740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baba Torfbräu", description = "Hey, während Ihr draußen wart, hat der Baron vorbeigeschaut! Hat mich so lange getreten, bis Geld herausgefallen ist!\n\nDas macht er aber immer so. Diesmal hat er mir aber noch aufgetragen, Euch etwas mitzuteilen! Er will, dass Ihr nach Süden geht und unserer Kräuterkundigen Baba Torfbräu helft.\n\nSie befindet sich auf der anderen Seite des Gewässers! Aber redet einfach mit meinem Mädchen Daisy draußen und sie wird Euch auf Art des verrückten Larrys dorthin bringen!", sourceObjective = "Redet mit dem verrückten Daisylein, um einen Kanonenkugelritt zu Baba Torfbräu zu unternehmen.", completion = "Ah, es ist so schön, Hilfe frei Haus zu bekommen.\n\nModerne Annehmlichkeiten... davon kann ich nie genug bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27742] = { id = 27742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Nebenerwerb", description = "Wisst Ihr, es ist unsere moralische Verpflichtung, all das Elementium vor den Schieferspinnen zu retten. Diese widerlichen Biester fressen das Zeug!\n\nWas für eine Verschwendung!\n\nAlso, was meint Ihr? Teilen wir 90:10 für mich?", sourceObjective = "Sammelt 6 Elementiumsplitter.", progress = "Was meint Ihr, wie viel könnt Ihr tragen?", completion = "<Goldmine wirft einen schlitzohrigen Blick auf den Haufen mit Elementiumsplittern.>\n\nHmm, ich glaube nicht, dass sich das Zeug gut verkaufen lässt. Am besten gebe ich Euch jetzt gleich Euren Anteil, damit Ihr Euch nicht übers Ohr gehauen fühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27743] = { id = 27743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo wir schon da sind", description = "Wenn Ihr schon hier seid, könnt Ihr Euch auch gleich um die Eindringlinge des Schattenhammers kümmern. Schließlich gehört dieser Ort uns!\n\nIch würde Euch ja helfen, aber da meine Totems und Waffen kaputt sind, bin ich ziemlich aufgeschmissen.", sourceObjective = "Tötet 12 Kultisten des Schattenhammers, entweder Tiefenaufseher oder Zwielichtminenarbeiter, in den Elementiumtiefen.", completion = "Sie haben es nicht besser verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27744] = { id = 27744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenruinierung", description = "Als Ihr die Zwielichtrune der Erde untersucht, spürt Ihr, wie ihre Macht sich weiter in die Elementiumtiefen hinein erstreckt.\n\nWahrscheinlich ist sie mit den anderen Runen verbunden. Initiand Goldmine ist der Meinung, dass Ihr sie alle zerstören solltet.", sourceObjective = "Zerstört die Zwielichtrune der Erde, die Zwielichtrune des Wassers, die Zwielichtrune der Luft und die Zwielichtrune des Feuers.", completion = "Das wird ihnen zeigen, was passiert, wenn man in unser Gebiet eindringt!\n\nWas ist denn das da drüben?", sourceObjectiveStatus = "unverified-source-field" }
quests[27745] = { id = 27745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuriges Wiedersehen", description = "Das ist Magmazahn, mein Feuerelementar, mit dem ich mich zerstritten habe. {name}, Ihr müsst ihn töten, sonst tötet er mich!\n\nEs war alles ein großes Missverständnis. Woher hätte ich denn ahnen sollen, dass er böse wird, wenn ich mir unten in Tiefenheim sein Herz \"ausleihe\"? Er kann nicht sterben... zumindest nicht dauerhaft!\n\nBestimmt hat er die Portalsteuerung bei sich. Ihr müsst ihm die Steuerung abnehmen und sie im Feuerportal benutzen, um uns zurück zum Eingang zu bringen.", sourceObjective = "Beschafft Euch die Feuerportalsteuerung und benutzt sie am Feuerportal.", completion = "Wir haben überlebt und alle Portale sind abgeschaltet!\n\nIhr glaubt doch nicht, dass Magmazahn mir das nachträgt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27746] = { id = 27746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königreich aus Dreck", description = "Dieser Krieg hat uns als Volk viel gekostet. Wir haben viel verloren, um unseren angestammten Platz als die rechtmäßigen Herrscher von Lordaeron zu sichern. Und obwohl wir für den Moment die Oberhand haben, tobt die Schlacht in anderen Teilen der Östlichen Königreiche weiter.\n\nIch muss nach Unterstadt zurück, um mich zu erholen. Ich möchte, dass Ihr an meiner Statt in das Vorgebirge des Hügellands reist, {name}. Als <mein verdientester Soldat/meine verdienteste Soldatin> werdet Ihr unsere Streitkräfte in die absolute Vorherrschaft über unsere Feinde im Hügelland führen.\n\nMeldet Euch bei Hochexekutorin Darthalia am Südwachttor im Osten.", sourceObjective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", completion = "Die Kunde von Eurem Sieg im Silberwald ermutigt uns, {name}. Wir sind bereit, unter Eurem Kommando zu kämpfen und die letzten Überreste der Menschheit aus dem Hügelland zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27747] = { id = 27747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenkrieg", description = "Viele Wildhämmer sind bereits aus ihren Heimen geflohen. Jetzt ist es Zeit, sie vollständig von der Karte zu tilgen.\n\nOben auf dem Grat im Norden findet Ihr verlassene Häuser in den Ruinen von Donnermar. Dort haben sie viele Fässer mit starkem Donnermarbier zurückgelassen.\n\nDonnermarbier hat einen Alkoholgehalt von 220 Prozent. Ich habe keine Ahnung, wie das überhaupt geht.\n\nZerschlagt die Fässer und zündet ihren Inhalt an. Brennt sie aus! Lasst den Zwergen nichts, zu dem sie zurückkehren könnten.", sourceObjective = "Zerschmettert 10 Fässer mit Donnermarbier in den Ruinen von Donnermar.", completion = "Ja, ja. Treibt sie mit Feuer hinaus, wie Murmeltiere aus ihren Löchern…\n\nGut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27748] = { id = 27748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück und Ruhm", description = "Wir müssen in Bewegung bleiben, {name}. Es ist nur eine Frage der Zeit, bevor die Truppen die Kurve kriegen.\n\nDie Lade sollte sich direkt hinter diesen Ruinen befinden.\n\nSeid wachsam. Irgendwie habe ich das Gefühl, dass es noch nicht vorbei ist.", sourceObjective = "Tötet den Obsidiankoloss.", completion = "Schön zu sehen, dass Ihr unversehrt seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27750] = { id = 27750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht am Buffet", description = "<Griffs Magen knurrt.>\n\nImmer, wenn das Drachenmal in den Krieg zieht, geht keiner mehr jagen.\n\nDas beste Essen schnappen wir den Feind direkt vor dem Mund weg. Auf dem Grat nördlich des Flusses gibt es eine Reihe von zerstörten Häusern der Wildhämmer. Ich wette, sie sind randvoll mit Köstlichkeiten.\n\nBringt mir etwas davon.", sourceObjective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", progress = "Hunger.", completion = "<Griff stürzt sich gierig auf den Haufen von Nahrungsmitteln, genug, um ein Dutzend Männer zu ernähren.>\n\nToll! Habt Ihr für Euch selbst auch etwas mitgebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[27751] = { id = 27751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Wildhämmer", description = "Seit mein Volk Anspruch auf das Hochland erhoben hat, sind die Wildhammerzwerge unsere erbittertsten Feinde. Wir haben sie in Grim Batol bekämpft, wir haben sie im Sumpfland bekämpft und selbst jetzt tobt ein offener Krieg im Norden, jenseits des Flusses in den Ruinen von Donnermar.\n\nBeweist mir Euren Wert. Sucht und vernichtet die Kriegsgezeichneten der Wildhämmer. Die Besten unter ihnen tragen Insignien. Meine Krieger sammeln sie gleich dutzendweise.\n\nKönnt Ihr das auch?", sourceObjective = "Tötet Kriegsgezeichnete der Wildhämmer, um 8 Insignien der Wildhämmer zu sammeln. Auch einzigartige Gegner in den Ruinen von Donnermar tragen Insignien bei sich.", progress = "Zeigt mir die Insignien, die Ihr gesammelt habt, {class}.", completion = "<Narkrall schließt seine wettergegerbte Faust fest um die Insignien.>\n\nAlso, {class}. An Euch ist mehr dran, als ich erwartet habe.\n\nVielleicht kann Eure Horde es mit meinen besten Kriegern aufnehmen. Finden wir es heraus…", sourceObjectiveStatus = "unverified-source-field" }
quests[27752] = { id = 27752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpfen wie ein Wildhammer", description = "Ich übertreibe nicht, wenn ich sage, dass wir in Donnermar das beste Bier in den Östlichen Königreichen brauen. Es hat 220 Prozent! Ja, Ihr habt ganz richtig gehört!\n\nAls die verschiedenen Familien sich aus dem Süden in die Mitte der Stadt zurückgezogen haben, mussten sie ihr Bier zurücklassen.\n\n<Blundy hält inne, um die Schwere der Situation einsinken zu lassen.>\n\nHOLT ES ZURÜCK! Dieses Zeug macht selbst den trägsten Krieger zu einem wirbelnden Derwisch der tollwütigen Zerstörung. Holt Euch diese Fässer! Sie sind unsere einzige Hoffnung!", sourceObjective = "Sammelt 10 Fässer voll Donnermarbier aus den Ruinen von Donnermar. Vorsicht! Es hat ganz schön Bumms!", progress = "Bringt mir dieses Bier, {name}.\n\nHe, Ihr habt doch nicht daran genippt, oder?", completion = "Oh, perfekt… Ich werde ein paar dieser Fässer zu meinen Jungs an der Front bringen. Dann geht der Tanz erst richtig los! Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27753] = { id = 27753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Essen zurücklassen", description = "Unsere Vorräte sind knapp bemessen, {name}. Von überall strömen Flüchtlinge nach Donnermar. Das sind ganz schön viele Mäuler, die gestopft werden wollen.\n\nViele Nahrungsmittel wurden zurückgelassen, als die Leute mit ihren Familien in die Sicherheit geflohen sind. Wir brauchen dieses Essen!\n\nDurchsucht die Ruinen von Donnermar südlich, östlich und südwestlich von hier nach ihren Nahrungsmittellagern.\n\nSeid vorsichtig, {class}! Um die Ruinen herum wird heftig gekämpft.", sourceObjective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", progress = "Habt Ihr was zu Beißen?", completion = "Ah, gut - und kaum eine Made oder Käfer zu finden!\n\nDas wird den Leuten, die hierher geflohen sind, das Leben retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27754] = { id = 27754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abreibung für das Drachenmal", description = "Das Drachenmal!\n\n<Colin spuckt aus.>\n\nMonster! Alles Monster! Seit dem letzten Krieg bekämpfen wir uns auf jedem gottverdammten Hügel und in jedem Tal. Und jetzt schließen sie sich der Horde an?\n\nWenn Ihr uns Wildhämmer dazu bringen wollt, uns mit Euch unter dem Banner der Allianz zusammenzutun, dann solltet Ihr Euch am besten im Kampf gegen das Drachenmal beweisen. Stürzt Euch in die Schlacht, die in den Ruinen von Donnermar im Süden und Südwesten tobt. Tötet die Marodeure des Drachenmalklans und sammelt die Insignien ihrer besten Krieger. Dann reden wir weiter.", sourceObjective = "Tötet Marodeure des Drachenmals und sammelt 8 Insignien des Drachenmals. Auch einzigartige Gegner in den Ruinen von Donnermar tragen Insignien bei sich.", progress = "Wie läuft der Kampf, {class}?", completion = "Schau sich das einer an! Da habt Ihr aber eine beeindruckende Trophäensammlung.\n\nIch werde den anderen davon berichten. Wenn ein einzelner {class} der Allianz das erreichen kann, kaum vorzustellen, was der Rest von Euch zu leisten vermag!", sourceObjectiveStatus = "unverified-source-field" }
quests[27755] = { id = 27755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch der Gräber", description = "Die Neferset sind nicht die einzige Bedrohung unserer geheiligten Gräber.\n\nEine Expedition der Gnome stolperte vor einigen Wochen in unsere Lande.\n\nSie haben nicht auf unsere Warnungen gehört und sich zu tief in ein verfluchtes Gewölbe hineingegraben.\n\nJetzt liegt auf der gesamten Expedition ein furchtbarer Fluch, der ihnen den Verstand geraubt und ihre Gedanken übernommen hat.\n\nNun suchen sie Zugang zu den tiefsten Gewölben Uldums und bilden eine große Bedrohung. \n\nGeht zu der Sonnensteinterrasse und erlöst ihre getriebenen Seelen von ihrem Elend.", sourceObjective = "Tötet 6 wahnsinnige Gräber und Robogenieur Mischgeweb.", completion = "Es war nicht möglich, sie zu retten, {name}. Der uralte Fluch, der sie befallen hat, kann nicht von ihnen genommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27756] = { id = 27756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vorarbeiter", description = "Wenn wir herausfinden wollen, was hier vor sich geht, müssen wir uns wohl durch die gesamten Todesminen schlagen! Glubtok der Vorarbeiter wird der erste ernsthafte Gegner sein, auf den Ihr trefft, ein mächtiger Ogermagier. Seid vorsichtig, er verfügt über die rohe Kraft seiner Spezies, kombiniert mit seinen verruchten Zauberkünsten!\n\nNehmt diesen Kommunikator, damit ich mit Euch in Verbindung bleiben kann, während wir mit den Untersuchungen voranschreiten. Seid vorsichtig da unten.", sourceObjective = "Tötet Glubtok.", completion = "<Bzzzzzzzzzzzzt.>\n\nGut gemacht! Saubere Arbeit. Dringt nun weiter vor und seht, was Ihr sonst noch aufspüren könnt! Mit Euch auf unserer Seite knacken wir diesen Fall wie eine Walnuss. Ich weiß es genau.", sourceObjectiveStatus = "unverified-source-field" }
quests[27757] = { id = 27757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkelsten Abgründe", description = "Ich habe im ganzen Sumpf gesehen, wie seltsam sich die Meereskreaturen verhalten. Die Murlocs, ja, aber vorher auch die Gilblins und die Makrura... ich habe neulich sogar einige Naga an den Strand wandern sehen.\n\nIrgendetwas ruft sie hierher, und peitscht sie zur Raserei auf. Viele der Kreaturen wurden in die Stagalsumpfhöhle im Westen gelockt. Da unten ist irgendetwas, und wenn es noch stärker wird, werden wir alle auch anfangen, hineinzuwandern...\n\nIhr solltet es aufhalten, was immer es auch ist. Bevor es zu spät ist.", sourceObjective = "Tötet Hr'nglth den Verirrten.", completion = "Oje. Es klingt als wärt Ihr einem ziemlich finsteren Wesen über den Weg gelaufen. Ich frage mich nur, was einer von denen so weit hier draußen wollte...", sourceObjectiveStatus = "unverified-source-field" }
quests[27758] = { id = 27758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zimmermann", description = "<Bzzzzzzzzzzzzt.>\n\nHallo? Könnt Ihr mich hören? Ausgezeichnet!\n\nEs scheint, als wäre Helix dabei, einen riesigen Mast zu bauen. Ihr glaubt doch nicht, dass er versucht, den Moloch der Defias fertigzustellen, oder?\n\nDas solltet Ihr lieber untersuchen, {name}. Und scheut Euch nicht, Euch die Hände schmutzig zu machen! Ihr habt die Erlaubnis, bei Bedarf tödliche Gewalt anzuwenden. Und offen gestanden wird das wahrscheinlich auch nötig sein.", sourceObjective = "Besiegt Helix Ritzelbrecher.", completion = "<Bzzzzzzzzzzzzt.>\n\nHe, hier ist Horatio. Das war aber spannend! Ich verfolge Eure Fortschritte auf der Spionatron X3-Funktion auf meinem Sturmwind-Kommunikator.\n\nSie verstecken ihr Werk aber hinter ganz schön vielen verstärkten Türen. Rückt weiter vor und schaut, was Ihr als nächstes finden könnt. Ich wette, es wird ein ganz großer Hinweis sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[27760] = { id = 27760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Künstliche Intelligenz", description = "<Eine weibliche Stimme spricht aus dem tragbaren Terminal zu Euch.>\n\nNotfallcode: 55-729\n\nFunktionen des oberen Zerebralkortex der Expeditionsmitglieder sind gestört.\n\nBitte beim nächsten Terminal im Südosten der Sonnensteinterrasse für weitere Analysen melden.", sourceObjective = "Sprecht mit dem A.I.D.A.-Terminal am Feldmesserposten in Uldum.", progress = "<Der Terminal surrt, als seine Mechanismen sich in Gang setzen.>", completion = "Scanne Objekt... \n\nZerebralkortexdiagnostik zeigt keine Anzeichen des \"Grabfluch\"-Phänomens.\n\nDiagnostik enthüllt diverse Schädeltraumata. Dem Nutzer wird empfohlen, in Zukunft in der Nähe stumpfer Gegenstände größere Vorsicht walten zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27761] = { id = 27761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bombige Ablenkung", description = "Der Fluch hat die höheren Gehirnfunktionen der Expeditionsmitglieder übernommen. Doch meine Berechnungen zeigen, dass ihr unterdrücktes, jugendliches Unterbewusstsein durch realistische Bilder stimuliert werden kann.\n\nBenutzt diesen Holoprojektor, um sie abzulenken.\n\nSie sind gerade dabei, Sprengsätze in dem Grab im Osten anzubringen, weil sie versuchen wollen, Zugang zu den Geheimgängen Uldums zu erlangen.\n\nSie suchen gefährliche Neuerschaffungstechnologie unter Uldum und müssen aufgehalten werden.", sourceObjective = "Entschärft den ersten, zweiten und dritten Sprengsatz und deaktiviert 4 instabile Bombenbots am Grab des Sonnenkönigs.", completion = "Gut gemacht, {name}. Die Expedition hat sich bereits selbst dem Untergang geweiht.\n\nEs gibt keinen Grund, den Rest der Welt auch noch in Gefahr zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27762] = { id = 27762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Luntenbrand!", description = "He, {race}, hört mal her. Ich habe einen Auftrag, den Ihr Euch sicher nicht entgehen lassen wollt.\n\nWir wurden aus Luntenbrand, einer neuen Goblinstadt tief im Ödland, hier hoch geschickt. Da unten gibt es jede Menge Geld zu verdienen! Außerdem treiben sich dort nicht annähernd so viele Zombies oder verklemmte Paladine herum.\n\nWeit und breit nur ungezähmte Wildnis da unten und wir suchen nach jemandem, der uns dabei hilft, das zu ändern. Wenn Ihr soweit seid... wir warten auf Euch.", sourceObjective = "Fliegt auf der Unkaputtbaren ins Ödland und meldet Euch dort bei Eddie Flofizzle.", completion = "Hübsche Landung!", sourceObjectiveStatus = "unverified-source-field" }
quests[27763] = { id = 27763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Zentrum von Luntenbrand", description = "Das hier, {race}, ist das Paradies. Ich wollte schon immer in einer netten, ruhigen Stadt am Meer leben, damit ich mich ganz ohne Ablenkungen auf meine Explosionen konzentrieren kann.\n\nRuhe ist jedoch nicht jedermanns Sache. Besonders, wenn man eher der abenteuerlustige Heldentyp ist, so wie Ihr.\n\nWir haben am anderen Ende der Stadt einen Teleporter installiert, der Euch auf die Klippen bringt. Von dort aus könnt Ihr den kurzen Ritt Richtung Westen ins Zentrum von Luntenbrand wagen, mitten im Ödland.\n\nDort sollte es mehr für Euch zu tun geben. Sagt einfach, dass Flo Euch schickt.", sourceObjective = "Benutzt den Teleporter an der Rückseite von Luntenbrand-am-Meer, um auf den Berg zu gelangen, und meldet Euch dann bei Dolph Blastus in Luntenbrand im Ödland.", completion = "Willkommen in Luntenbrand!", sourceObjectiveStatus = "unverified-source-field" }
quests[27764] = { id = 27764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Bitte", description = "Kommen wir zu etwas anderem. Ich habe ein Paket, das geliefert werden muss.\n\nVor nicht allzulanger Zeit kam eine junge Dame in unsere Stadt, die komprimiertes Sprengpulver, eine gehärtete Mithrilbombenhülle und eine Schutzbrille wollte. Natürlich konnten wir ihr eine Menge Sprengpulver und Bombenhüllen verkaufen, aber die Schutzbrille war etwas schwieriger zu beschaffen.\n\nUm es kurz zu machen: Ich habe die Schutzbrille, aber sie ist schon zu ihren Studien in der Lethlorklamm zurückgekehrt. Bringt ihr sie für mich zu ihr?", sourceObjective = "Bringt Dolphs Paket zu Rhea in der Lethlorklamm im Ödland.", progress = "Ahh... Ihr habt mich gefunden. Gut.", completion = "Ich danke Euch, {race}. Die Schutzbrille könnt Ihr behalten, da sie ja bereits ihren Zweck erfüllt hat: sie hat Euch zu mir gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27765] = { id = 27765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Probe: Wilde Eier", description = "Ich experimentiere mit Schwarzdrachen. Genauer gesagt interessiere ich mich für ihre Fortpflanzung.\n\nFür meine aktuellen Experimente benötige ich viele Schwarzdracheneier, weshalb ich hier in der Lethlorklamm bin. Ich würde die Eier ja selbst sammeln, aber ich glaube, es wäre zu Eurem Nutzen, wenn Ihr mir dabei helfen würdet.\n\nIhr könnt sie am Rand der Schlucht finden. Hütet Euch vor den Wächtern, die oben kreisen - sie freuen sich nicht über Eierdiebe.", sourceObjective = "Besorgt 6 Eier von wilden Schwarzdrachen.", progress = "Habt Ihr die Eier dabei?", completion = "Danke, dass Ihr sie so schnell gesammelt habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27766] = { id = 27766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweite Probe: Welpen", description = "Ihr müsst mir noch einen Gefallen tun. Ihr müsst mir die Körper der Schwarzdrachenwelplinge bringen, die in der Nähe herumfliegen. Tötet sie und bringt mir ihre Leichen.", sourceObjective = "Besorgt 10 Kadaver von brühenden Welpen.", progress = "Seid Ihr meiner Bitte nachgekommen?", completion = "Diese grausige Aufgabe war notwendig, {name}.\n\nAlles wird sich Euch bald offenbaren. Fürs Erste nur soviel:\n\nIch bin kein gewöhnlicher Goblin.\n\nIch diene einer Herrin von unvorstellbarer Macht und ihre Beweggründe sind nicht so finster, wie sie erscheinen mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27768] = { id = 27768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweiter Schritt: Der Blutvergießer", description = "Die Trolle hier setzen den Fall meiner Brüder in den Alptraum ewig fort. Sie infizieren und korrumpieren grüne Drachen mit dem Blut ihres verruchten Gottes, und ernten dann das Böse, das in ihnen gediehen ist. Sie werden wie Vieh gezüchtet...\n\nDiese ekelerregenden Untaten dürfen nicht fortgesetzt werden. Kehrt zum Ausgang der Halle der Masken zurück und nehmt den anderen Korridor in Richtung des Schlachthofs. Gomora der Blutvergießer erntet dort Leichen für diese abscheulichen Rituale. Entledigt ihn seines unverdienten Lebens!", sourceObjective = "Tötet Gomora den Blutvergießer im Schlachthof.", sourceObjectiveStatus = "unverified-source-field" }
quests[27769] = { id = 27769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhea enthüllt", description = "Wie schon angedeutet bin ich kein gewöhnlicher Goblin. Vielleicht habt Ihr meine wahre Identität bereits erraten.\n\nLasst mich Euch meine wahre Form zeigen. Da Ihr Euch als vertrauenswürdig erwiesen habt, werde ich die Details meines Planes mit Euch teilen.", sourceObjective = "Erfahrt Rheas wahre Identität.", progress = "Ihr seid aber ungeduldig, {name}.", completion = "Mein wahrer Name ist Rheastrasza und ich bin eine Abgesandte von Alexstrasza, dem Aspekt des roten Drachenschwarms.\n\nDa Todesschwinge derzeit mit anderen Dingen beschäftigt ist, werden wir einen Weg finden, um den schwarzen Drachenschwarm zu erlösen.\n\nUnd Ihr werdet uns dabei helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27770] = { id = 27770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schleier lüften", description = "Der schwarze Drachenschwarm war einst nobel. Sie waren die Bewacher der Erde und schützten die Lande. Welch Ironie, dass ausgerechnet sie zur schlimmsten Bedrohung wurden, die das Land je erlebt hat.\n\nIch glaube aber, dass es noch einen Funken Hoffnung gibt - und meine Herrin sieht das ebenso. Der schwarze Drachenschwarm wird auch nach Todesschwinges Verrat weiter existieren und wieder als nobler Bewacher der Erde zum Himmel aufsteigen.\n\nIch möchte Euch etwas zeigen. Schließt Eure Augen und ich werde Euch den letzten Teil meiner Studien enthüllen.", sourceObjective = "Werdet Zeuge des letzten Teils von Rheas Studien.", completion = "Wir werden noch einen Funken Gutes in diesen Drachen finden, {name}. Entweder in den wilden Eiern, die Ihr gefunden habt, in den Körpern der Welplinge, die Ihr getötet habt, oder in den Eiern, die Nyxondra gelegt hat, als wir sie dazu ermutigten... Wir werden einen unverdorbenen schwarzen Drachen finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27771] = { id = 27771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritte Probe: Implantierte Eier", description = "Nyxondra wird gegen ihren Willen festgehalten. Sie wird mitten in den Brutstätten vor ihrem eigenen Schwarm versteckt. Sie legt zwar Eier, aber man nimmt sie ihr weg, bevor sie sie ausbrüten kann.\n\nGrausam? Vielleicht... Aber nicht annähernd so grausam wie das, was ihr Drachenschwarm meiner Herrin angetan hat.\n\nBeweist mir, dass ich Euch vertrauen kann, {name}. Bringt Nyxondras Eier zu mir. Ihr müsst Nyxondra schlagen, bis sie sich fügt, bevor Ihr die Eier nehmen könnt.", sourceObjective = "Beschafft 3 von Nyxondras Eiern.", progress = "Vergesst nicht, {name}... Dies geschieht zum Wohl des schwarzen Drachenschwarms. Wir sind hier, um ihn zu erlösen, nicht, um ihn zu verletzen. Dies ist nur ein Schritt auf dem Weg zu seiner Gesundung.", completion = "Ihr habt alles, was ich Euch aufgetragen habe, ohne zu fragen erledigt. Unsere Arbeit hier in der Lethlorklamm ist getan.\n\nJetzt ist es an der Zeit, dass ich Euch in alles einweihe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27772] = { id = 27772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ehrwürdige Doktor Blam", description = "Ich habe eine ganz bewusste Entscheidung getroffen, als ich mich Euch zu erkennen gab, {name}. Ich brauche Euer Vertrauen, aber ich kann nicht länger hier in der Lethlorklamm bleiben, da meine Verkleidung ganz klar aufgeflogen ist.\n\nIhr jedoch könntet unentdeckt entwischen. Hier, nehmt die Ergebnisse unserer Forschungen und bringt sie nach Westen. Auf der Agmondkuppe werdet Ihr einen Gnom finden, der weiß, was mit diesen Proben zu tun ist.\n\nBeeilt Euch, {name}! Ihr dürft hier nicht herumtrödeln!", sourceObjective = "Bringt die Proben der schwarzen Drachen zu Dr. Hieronymus Blam auf der Agmondkuppe im Ödland.", progress = "Dr. H. Blam, zu Euren Diensten. Wie kann ich Euch heute behilflich sein?", completion = "Ooh! Wissenschaftszeug! Dann lasst uns mal sehen, was Ihr da habt...\n\nWilde Eier? Bäh. Nutzlos. Damit kann doch niemand etwas anfangen.\n\nOoooh, was ist das? Eine Art... vorkonstruiertes Ei? Das sieht vielversprechend aus, aber ich will lieber nicht wissen, was Rhea tun musste, um es zu bekommen.\n\nHmm... ja, ein paar wirklich nette Leichen. In der Tat, sehr nett.\n\nIn Ordnung, ich werde sehen, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27773] = { id = 27773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritter Schritt: Prophet", description = "Alles, was jetzt noch zwischen mir und dem Tempel steht, ist Prophet Jammal'an selbst. Er ist der Anführer der Atal'aitrolle hier, ein bösartiger Manipulator.\n\nWisset, dass Ihr nicht bloß auf einen verrückten Troll treffen werdet, {name}, sondern auf ein Instrument von Kräften, die Eure finstersten Vorstellungen übertreffen. Doch Ihr kämpft nicht allein... Meine Stärke und der Wille des grünen Drachenschwarms werden Euch begleiten.\n\nBegebt Euch zum Höhlenbau des Rufenden, links durch die Halle des Rituals, und von da in die Halle der Knochen. An ihrem unteren Ende werdet Ihr Jammal'an finden.", sourceObjective = "Bezwingt Jammal'an den Propheten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27774] = { id = 27774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach zu beeinflussen", description = "Die größte Bedrohung für Luntenbrand ist zweifellos die Ogerkolonie im Nordwesten.\n\nDie meisten unserer Ogernachbarn waren Kriegertypen, aber es sieht aus, als würden mehr und mehr von ihnen Magie ausüben. Ich werde keine Ogermagier vor meiner Haustür zulassen.\n\nGeht und macht ein paar dieser Staubspeieroger unschädlich. Hoffentlich lassen sie sich das eine Lehre sein und legen sich nicht mehr mit der Macht von Luntenbrand an.", sourceObjective = "Tötet 9 Staubspeieroger in Camp Kosh", completion = "Ich frage mich, wo all diese Ogermagier herkommen. Wahrhaftig erstaunliche Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27775] = { id = 27775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn's mal wieder schwerer wird, improvisiere!", description = "Ich schaffe es einfach nicht, meine Erfindung in Gang zu bringen. Gah!\n\nDas ist es! Ich habe eine Entscheidung getroffen. Ich werde improvisieren und Magie verwenden.\n\nWas meiner Erfindung wirklich fehlt ist ein solider Kolben, der dünn genug ist, um durch ein schmales Kupferrohr zu passen. Dabei muss er auch stark genug sein, um regelmäßigen Stößen widerstehen zu können. Die magischen Ruten, die die Ogermagier nördlich von hier bei sich tragen, sind genau das Richtige.\n\nSoweit ich weiß, tragen nur die Instrukteure Ruten, die stark genug sind.", sourceObjective = "Beschafft eine Instrukteursrute von den Instrukteuren der Ogermagier in Camp Kosh.", progress = "Ich lasse mich nur ungern dazu herab, Magie in meinen Erfindungen einzusetzen, aber in diesem Fall handelt es sich praktisch um einen Notfall.", completion = "Passt perfekt! Mein Ziegenschläger ist endlich vollendet!", sourceObjectiveStatus = "unverified-source-field" }
quests[27776] = { id = 27776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Ziegen, Baby", description = "Falls es Euch entgangen sein sollte, wir haben hier in Luntenbrand ein kleines Ziegenproblem. Sie fressen alles und scheinen eine Vorliebe für die Häufchen aus Zahnrädern und Getrieben, die wir überall herumliegen lassen, zu haben.\n\nDas wird allmählich wirklich lästig!\n\nIhr findet die meisten Ziegenböcke am Rande der Stadt in der Nähe der Klippen. Benutzt dieses Gerät, um ihnen einen kleinen \"Schubs\" zu geben.", sourceObjective = "Benutzt Garyannes Ziegenboxer an 12 Ziegenböcken in Luntenbrand.", completion = "Gut gemacht! Zweifellos werden die Ziegen zurückkommen, aber sie werden es sich zweimal überlegen, ehe sie noch einmal an meinen Zahnrädern knabbern!", sourceObjectiveStatus = "unverified-source-field" }
quests[27777] = { id = 27777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernzugriffcodes", description = "Die Zahl der Expeditionsteilnehmer ist sehr groß, Nutzer {name}.\n\nSich mit normalen Mitteln um sie zu kümmern würde geschätzte 2.700.136,5 Stunden dauern.\n\nWir können uns einer mächtigen Energiequelle bedienen, die sich in dem Raupenfahrzeug der Expedition befindet.\n\nDazu müssen wir allerdings die Zugangscodes für den Fusionskern finden.\n\nRobogenieur Pfuschelflux hat diese Codes und befindet sich im Sternbeobachtungsturm im Südosten.\n\nIch habe einen Scrambler mit Störfrequenzen gefüttert. Benutzt ihn, um Pfuschelflux' Schutzmechanismen vorübergehend außer Kraft zu setzen.", sourceObjective = "Beschafft die Kernzugriffscodes von Pfuschelflux dem Wahnsinnigen.", progress = "Hattet Ihr Erfolg, {name}? Ich hatte Eure Überlebenschance mit 68,5 % berechnet.", completion = "Ausgezeichnete Arbeit, Nutzer {name}. Jetzt müssen wir uns Zugang zum Fusionskern verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27778] = { id = 27778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Wibson hacken", description = "Es ist wahr. Neue Expeditionsmannschaften sind auf dem Seeweg eingetroffen.\n\nMeine Scanner haben entdeckt, dass sie bereits von dem Fluchphänomen befallen sind.\n\nIhr müsst Euch beeilen und sofort an Bord der M.A.C. Dyver gehen. Die Zugangscodes werden uns die Kontrolle über die Funktionen des Fusionskerns geben, doch wir müssen noch einen Sicherheitslevel umgehen.\n\nNutzer {name}, ich muss Euch bitten, Euch in einen sehr ausgefeilten Großrechner bekannt als der \"Wibson\" zu hacken.\n\nKeine Sorge, ich werde Euch weitere Instruktionen zukommen lassen.", sourceObjective = "Hackt Euch in den Wibsongroßrechner an Bord der M.A.C. Dyver.", progress = "Seid gegrüßt, Nutzer {name}.", completion = "Ich habe alles unter Kontrolle, Nutzer {name}. Aber ich kann die Kerntemperatur nicht auf unbestimmte Zeit stabil halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27779] = { id = 27779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschung der Gnome", description = "Ich habe mein Programm in den Fusionskern geladen und habe jetzt die volle Kontrolle darüber.\n\nIch habe eine kleine Luftblase darin geschaffen, um zu verhindern, dass Nutzer {name} pulverisiert wird.\n\nIch werde eine Steuerung für all meine Bewegungsfunktionen generieren, damit ich meine Schaltkreise der Stabilisierung des Kerns widmen kann.\n\nGeht den Hügel hinunter und neutralisiert so viele Expeditionsmitglieder wie möglich.\n\nMeine Analyse hat ergeben, dass Ihr möglicherweise... \"Schuld\" empfinden könntet bei solch einer großen Anzahl Todesfälle.\n\nNutzer {name}, Ihr müsst Euch darüber klar sein, dass es keine Hoffnung für die Expeditionsmitglieder gibt.", sourceObjective = "Löscht 1000 wahnsinnige Gnome aus.", progress = "Das Ableben der Expeditionsmitglieder ist bedauerlich.", completion = "Es ist vollbracht, Nutzer {name}. Ich danke Euch für Eure Hilfe bei dieser bedauernswerten Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27781] = { id = 27781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maschinerie", description = "<Bzzzzzzzzzzzzt.>\n\n<Bzzzzzzzzzzzzt.>\n\nHa-hallo? {name}, seid Ihr da? Seid Ihr noch am Leben? Hallo?\n\nOh, gut, Ihr seid noch da! Was im Namen Lordareons bauen die da? Es ist eine Art mechanisches Monstrum! Ihr müsst sie daran hindern, dieses... dieses... Ding fertigzustellen! \n\nVergesst alle Regeln, tut einfach nur, was Ihr tun müsst, um sie aufzuhalten!", sourceObjective = "Zerstört den Feindschnitter 5000.", progress = "Ja?", completion = "<Bzzzzzzzzzzzzt.>\n\nIhr nähert Euch dem Herzen ihres Einflussbereichs. Wahrscheinlich wird das Allerheiligste der gesamten Defiasoperation von einer extrem verstärkten Tür geschützt. Schaut, ob Ihr etwas finden könnt, um sie aufzubrechen!\n\nIch schlage eine unauffällige Methode vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27782] = { id = 27782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias braucht Euch", description = "Wir hatten viel Spaß miteinander. Es tut mir sehr leid, dass Ihr gehen müsst. Aber Mathias sagte, dass er Euch braucht.\n\nEr sagte auch, es sei dringend!\n\nAlso, wollt Ihr nach dem, was ihr zu tun habt, vielleicht etwas trinken gehen, <Kumpel/meine Dame>?", sourceObjective = "Sprecht mit Meister Mathias Shaw bei der Schattenzitadelle im Schattenhochland.", completion = "Ihr seid zurück! Wir wissen, wo Cho'gall seine ultimative Waffe versteckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27783] = { id = 27783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona braucht Euch", description = "Wir hatten viel Spaß miteinander. Es tut mir sehr leid, dass Ihr gehen müsst. Aber Garona sagte, dass sie Euch braucht.\n\nSie sagte auch, es sei dringend!\n\nAlso, wollt Ihr nach dem, was ihr zu tun habt, vielleicht etwas trinken gehen, <Kumpel/meine Dame>?", sourceObjective = "Sprecht mit Garona der Halborcin bei der Schattenzitadelle im Schattenhochland.", completion = "Ihr seid zurück! Wurde ja auch Zeit. Wir wissen, wo Cho'gall seine ultimative Waffe versteckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27784] = { id = 27784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenhammer", description = "Während Ihr in der Mine wart, konnte ich herausfinden, wo der Schattenhammer aufbewahrt wird. Er wurde am Zwielichtaltar im Süden geschmiedet.\n\nNoch wichtiger, die Kultisten haben einen schweren Fehler begangen: Cho'gall selbst überwacht seine Fertigstellung.\n\nViele Agenten des SI:7 sind gestorben, um uns diese Informationen zu bringen.", sourceObjective = "Gelangt zum Schattenhammer.", completion = "Der Schattenhammer schwebt in der Mitte des Altars, ungeschützt…", sourceObjectiveStatus = "unverified-source-field" }
quests[27785] = { id = 27785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Admiral", description = "<Bzzzzzzzzzt.>\n\nIch fasse es nicht... Sie sind beinahe mit dem Wiederaufbau fertig! Wir haben nicht viel Zeit, {name}.\n\nAdmiral Knurrreißer, Vanessas rechte Hand, muss sich an Bord befinden. Wir werden nie an sie herankommen, solange er am Leben ist. Ihr werdet die noch unvollendete Moloch besteigen, Knurrreißer aufspüren und töten müssen, sodass wir in Vanessas private Kajüte auf dem Oberdeck gelangen können.\n\nSeid vorsichtig, der Admiral steht unter dem Worgenfluch und würde Euch nur zu gern mit seinen Klauen zerreißen!", sourceObjective = "Tötet Admiral Knurrreißer.", completion = "<Bzzzzzzzzzzzzt.>\n\nEure Abenteuer haben Euch einigen Ruhm in Geheimdienstkreisen eingebracht, {name}. Viele hochrangige Mitglieder vom SI:7 haben Eure Infiltration der Todesminen mit ihren eigenen Sturmwind-Kommunikatoren aufmerksam verfolgt.\n\nMathias Shaw will höchstpersönlich mit Euch sprechen! Ich werde Euch sofort durchstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27786] = { id = 27786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenhammer", description = "Während Ihr in der Mine wart, konnte ich herausfinden, wo der Schattenhammer aufbewahrt wird. Er wurde am Schattenaltar der Stürme im Süden geschmiedet.\n\nNoch wichtiger, die Kultisten haben einen schweren Fehler begangen: Cho'gall selbst überwacht seine Fertigstellung.\n\n<Garona beginnt, ihre Klingen zu schärfen.>\n\nViele Kor'kron sind gestorben, um uns diese Informationen zu bringen.", sourceObjective = "Gelangt zum Schattenhammer.", completion = "Der Schattenhammer schwebt in der Mitte des Altars, ungeschützt…", sourceObjectiveStatus = "unverified-source-field" }
quests[27787] = { id = 27787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädelberster der Berg", description = "Es war eine Falle! Cho'gall hat Euch mit dem Hammer angelockt, damit sein Gronn Euch den Rest geben kann.\n\nÜberlebt und tötet Schädelberster den Berg!", sourceObjective = "Überlebt und tötet dann Schädelberster den Berg.", completion = "Ihr habt es geschafft, Junge! Ihr habt den verdammten Gronn besiegt und Cho'gall in seine Bastion des Zwielichts zurückgeschickt.\n\nKeine Sorge. Mit Eurer Hilfe und der Eurer Freunde werden wir dort hineinkommen und Cho'gall ein für alle Mal den Garaus machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27788] = { id = 27788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädelberster der Berg", description = "Es war eine Falle! Cho'gall hat Euch mit dem Hammer angelockt, damit sein Gronn Euch den Rest geben kann.\n\nÜberlebt und tötet Schädelberster den Berg!", sourceObjective = "Überlebt und tötet dann Schädelberster den Berg.", completion = "Ihr habt es geschafft, {name}! Ihr habt den verdammten Gronn besiegt und Cho'gall in seine Bastion des Zwielichts zurückgeschickt.\n\nKeine Sorge. Mit Eurer Hilfe und der Eurer Freunde werden wir dort hineinkommen und Cho'gall ein für alle Mal den Garaus machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27789] = { id = 27789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer Ärger mit den Troggs", description = "Ich brauche ein wenig Zeit, um die Proben zu analysieren. Außerdem täte mir eine Pause von der Troggerschießerei ganz gut. Steigt in eines meiner Geschütze und erledigt so viele Troggs, wie Ihr nur könnt. Ich bleibe hier und führe meine Untersuchungen durch.\n\nDie Geschütze haben zwei Fähigkeiten: Einen normalen Schuss und eine elektrische Überladung, für den Fall, dass Euch zu viele Feinde zu nahe kommen. He he. Viel Glück.\n\nOh, und haltet nach den großen, langsamen Troggs Ausschau. Die sollten sich besser nicht in Eurer Nähe aufhalten.", sourceObjective = "Steigt in einen Kabummturm und überlebt vier Angriffswellen der Troggs.", progress = "Noch nicht ganz fertig. Brauche etwas mehr Zeit.", completion = "Die Ergebnisse sind da. Ich habe Spuren der Verderbtheit in allen drei Proben gefunden. Rhea wird ganz schön enttäuscht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27790] = { id = 27790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nummer Eins der Defias", description = "Hallo, {name}. Ich habe viel von Euch gehört. Hört gut zu, denn Ihr werdet nur eine Chance bekommen.\n\nDie neue Nummer Eins der Defias muss in der Hütte sein und von dort die Strippen ziehen. Ich will, dass Ihr da reingeht und sie unschädlich macht, für die unzähligen Unschuldigen, die die von ihrem Vater gegründete Organisation getötet und terrorisiert hat.\n\nIch kann kaum glauben, dass sie Euch so nahe an sich heranlässt, ohne zu fliehen und auf eine bessere Gelegenheit zu warten, aber es sieht aus, als hätten wir Glück.", sourceObjective = "Erschlagt die Nummer Eins der Defias.", completion = "Eure Anstrengungen hier könnten heute womöglich ganz Sturmwind gerettet haben, {name}. Vanessa ist zwar noch immer dort draußen, aber sie ist eine unerhebliche Gefahr, nun da wir den Moloch in unsere wachsame Obhut nehmen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27791] = { id = 27791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staubwindausgrabung", description = "Ich habe eine Idee, die reine Spekulation ist. Zum Glück sind reine Spekulationen eine meiner Spezialitäten.\n\nNördlich von hier hat die Forscherliga neue Ruinen der Titanen unter dem Sand gefunden. Wenn es jemanden gibt, der älter und weiser ist, als die Drachen, sind es die Titanen. Ich habe sogar Gerüchte gehört, dass die Titanen die Drachen ERSCHAFFEN haben.\n\nSprecht mit Oberausgrabungsleiter Durdin im Lager nördlich von hier. Er wird weitaus mehr über die Titanen wissen als ich.\n\nWas habe ich Euch gesagt? Reine Spekulation.", sourceObjective = "Sprecht mit Oberausgrabungsleiter Durdin in der Staubwindausgrabung im Ödland.", completion = "Titanen? Ihr wollt etwas über Titanen wissen?\n\nDa seid Ihr genau an der richtigen Adresse, mein Lieber. Wir stehen vor einer großen Entdeckung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27792] = { id = 27792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Liebe und im Krieg ist alles erlaubt. Und in der Archäologie auch.", description = "Moment mal, Eins nach dem Anderen. Ich werde mich hier nicht einfach hinsetzen und Euch alles erzählen, was wir in diesen Ruinen herausgefunden haben. Es gibt Probleme, um die wir uns kümmern müssen!\n\nAm wichtigsten sind diese Akademievandalen, die auf der anderen Seite des Grabs sind. Sie machen sich mit unserer ganzen Beute aus dem Staub! Wissen die denn nicht, dass Graben Zwergensache ist?\n\nJagt ein paar von deren 'Ausgräbern' - eher Banditen, wenn Ihr mich fragt - und bringt mir einige wertvolle Artefakte zurück.\n\nDANN unterhalten wir uns über Titanen.", sourceObjective = "Erlangt einen zerbrochenen Kelch, eine staubige Vase, eine irdene Hieroglyphe und ein Troggwerkzeug.", progress = "Eure Taschen sehen aber schwer aus. Beladen mit geplünderten Artefakten, hoffe ich?", completion = "Kelch... wertlos.\n\nVase... gefälscht.\n\nHieroglyphe... interessant, aber nicht weiter außergewöhnlich.\n\nWas haben wir denn da? Ich habe noch nie Kunsthandwerk der Troggs von diesem Kaliber gesehen! Da seid ihr aber auf etwas wirklich Seltenes gestoßen, {name}.\n\nNa gut, wie Ihr möchtet. Sprechen wir also über die Titanen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27793] = { id = 27793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Beschützer", description = "Ihr habt in der zentralen Kammer des Grabes recht viel Rumpeln gehört. Diese zwei großen Statuen sahen schrecklich verdächtig aus.", sourceObjective = "Untersucht den Wächter und die Schildwache.", sourceObjectiveStatus = "unverified-source-field" }
quests[27794] = { id = 27794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Blam", description = "Innerhalb der Kiste findet Ihr einen kleinen, runden Gegenstand, der auf einem Kissen liegt.\n\nWenn es hier unten ein Titanenartefakt geben sollte, dann muss es das sein. Ihr beschließt, ihn zu Dr. Blam zurückzubringen.", sourceObjective = "Bringt das Auge der Behüter zu Dr. Hieronymus Blam bei der Agmondkuppe im Ödland.", progress = "Und? Hat sich unser Schuss ins Blaue ausgezahlt?", completion = "Bloß ein winzig kleines Gerät?\n\nIch habe diese Titanen noch nie verstanden.\n\nNun gut! Wollen wir doch mal sehen, was dieser Piepser kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[27795] = { id = 27795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flut der Dunkelheit", description = "Die Schlacht verläuft genau so, wie ich es wollte. Jetzt, da ihre Krieger erschöpft sind, habe ich die Reiterei hinein geschickt.\n\nWomit ich jedoch nicht gerechnet hatte, waren Oger. Unsere Ritter stehen den Schlägern zwar in nichts nach, dennoch werden sie Hilfe brauchen.\n\nIhr müsst sofort wieder auf das Feld, {name}. Nur wenige können einen Oger zu Fuß zur Strecke bringen, aber ich glaube, dass ich mich auf Euch verlassen kann. Enttäuscht mich nicht.", sourceObjective = "Tötet 6 Oger von Steinard.", completion = "Sich einem Oger direkt in den Weg zu stellen ist beeindruckend, {name}. Ich bin froh, dass ich Soldaten wie Euch da draußen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27796] = { id = 27796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer des Wächters", description = "Als diese Reliquientrottel hier auftauchten, gerieten wir in Panik und begannen, einfach wahllos zu plündern.\n\nViel zweifelhafte Archäologie spielte sich an diesem Tag ab.\n\nGlücklicherweise stieß Olga zufällig auf diese kleine Jadestatue. Wir dachten, es sei eine Art Schlüssel, konnten aber nichts finden, das sie hätte öffnen können. Vielleicht habt Ihr mehr Glück damit.", sourceObjective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer des Wächters.\n\nBereitgestellter Gegenstand:", completion = "<Die Statue rastet in ihren Platz auf der großen Steinplatte ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27797] = { id = 27797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer der Schildwache", description = "Beinahe wurde uns diese Statue von einem der Reliquienhandlanger des Blutwächters gestohlen. Wir konnten ihn auf frischer Tat ertappen und bekamen die Statue zurück, aber es hat sich nicht wirklich gelohnt.\n\nEs scheint, als wäre sie eine Art Schlüssel, aber ich kann in diesen Ruinen nirgendwo das Schloss dazu finden. Möchtet Ihr es versuchen?", sourceObjective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer der Schildwache.\n\nBereitgestellter Gegenstand:", completion = "<Die Statue gleitet an ihren Platz auf der kalten Marmorplatte.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27798] = { id = 27798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser des Lebens", description = "Nehmt mein Wasser des Lebens und gebt es auf den Leichnam des ertrunkenen Zwergs.\n\nAls er lebte, bearbeitete er Metall. Und obwohl sein Leichnam jetzt meinen Loch nährt, kann er Euch dank des Wassers sagen, was Ihr wissen wollt.\n\nNehmt dann Eure Informationen und verschwindet aus meinem Reich.", sourceObjective = "Benutzt das Wasser des Lebens, um dem Leichnam von Schmiedemeister Finlay Informationen zu entlocken.", completion = "Der Schattenhammer? Und diese Informationen habt Ihr also von einem ertrunkenen Zwerg?\n\nIhr macht Scherze, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[27803] = { id = 27803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine willkommene Entlastung", description = "Meine Jungs stellen Verteidigungslinien zu allen Seiten der Stadt und halten die Elementare zurück, die von allen Seiten aus dem aufgerissenen Boden herbeiströmen. Es sind gute Jungs und sie schlagen sich wacker, aber auch der hartnäckigste Zwerg wird einmal müde.\n\nSie haben sich in Schichten eingeteilt: eine Stunde Rast für jede Stunde an der Front. Das ist das Beste, was ich ihnen mit so wenig Leuten bieten kann.\n\nWenn Ihr helfen wollt, dann sucht Euch eine Seite aus und übernehmt eine Schicht. Verschafft meinen Jungs eine willkommene Verschnaufpause. Meldet Euch zurück, sobald Ihr eine ansehnliche Zahl Elementare getötet habt.", sourceObjective = "Tötet 8 unterworfene Feuerteufel.", completion = "Gute Arbeit, Junge. Es ist schön, ein zusätzliches Paar geschickter Hände zur Verfügung zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27804] = { id = 27804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für immer unser Zuhause", description = "Wir wurden schon weiter zurückgedrängt, als ich befürchtet hatte, aber ich habe nicht vor, unsere Häuser diesen Bastarden zu überlassen. Sie können sie vielleicht niederbrennen, plündern und auf ihre Überreste spucken, aber wir werden nicht aufgeben und sie zurückfordern.\n\nNatürlich hätte ich es lieber, wenn sie sie nicht niederbrennen. Ich habe die Jungs angewiesen, Eimer am Brunnen zu füllen und damit zu versuchen, das Feuer einzudämmen. Wenn Ihr ihnen aushelft, können sie Euch vielleicht Eimer zuwerfen, sodass Ihr nicht selbst laufen müsst.", sourceObjective = "Löscht 50 Feuer in Feuerbarts Patrouille.", completion = "Vielen Dank für Eure Hilfe. Jede noch so kleine Tat kann viel bewirken.\n\nWir werden weiter Wasser bringen, bis wir den Schattenhammer zurückgedrängt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27805] = { id = 27805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Quäntchen Trost", description = "Ihr seid also das neue Gesicht, das Keegan aushelfen soll? Freut mich, Euch kennenzulernen. Vielleicht könnt Ihr den geplagten Wildhämmern, die hier Zuflucht gefunden haben, ein oder zwei Gefallen tun.\n\nWir mussten uns in größter Hast in diesem Gebäude verschanzen, sodass wir viele unserer Wertsachen in unseren zerstörten Häusern in der Nähe zurückließen. Würdet Ihr sie uns zurückbringen, wenn Ihr da draußen seid? Ihr würdet ein paar sehr bedrängten Seelen eine große Freude bereiten.", sourceObjective = "Findet Mearas Trockenrosen, Parlans Elfenbeinhammer und Aprikas Puppe.", progress = "Konntet Ihr ihre Wertsachen finden? Ich weiß, es scheint so banal, aber in Zeiten wie diesen können auch Kleinigkeiten so viel bewirken.", completion = "Ihr seid sehr großzügig. Vielen Dank.\n\nUnsere Welt versinkt dieser Tage in Dunkelheit. Wir sind sehr dankbar, dass Ihr uns ein kleines Licht gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27806] = { id = 27806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenvolle Last", description = "Iain, mein Stellvertreter, hat den Leichnam eines unserer gefallenen Helden in die Kathedrale im Westen gebracht. Er ist dafür verantwortlich, aus den verstreuten Truppen einen neuen Greifenreiterflügel aufzustellen. Ich möchte, dass Ihr ihm helft.\n\nIch sollte Euch klar machen, wie eilig diese Aufgabe ist. Wir werden hier nicht bis in alle Ewigkeit standhalten können. Der Schattenhammer oder das Drachenmal werden uns früher oder später überwältigen. Ein aktiver Greifenreiterflügel ist vielleicht unsere einzige Chance, diesen Kampf zu überleben.", sourceObjective = "Sprecht mit Iain Feuerbart auf Feuerbarts Friedhof.", completion = "Grüße, {race}. Kommt Ihr in Keegans Auftrag?", sourceObjectiveStatus = "unverified-source-field" }
quests[27807] = { id = 27807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klan Mullan", description = "Wenn wir wieder ein vollständiges Greifengeschwader zusammenbekommen wollen, müssen wir uns beeilen, die Überlebenden zusammenzutrommeln, bevor sie fortgehen oder aufgelesen werden. Ich habe einige Gruppen Reiter im Auge, die zusammengeblieben sind. Ich werde bald aufbrechen, um die Reiter von Donnermar und Moora zu suchen.\n\nAls ich die Mullans das letzte Mal sah, gingen sie nach Westen hinauf in den Schmelztiegel des Gemetzels. Geht und schaut, ob Ihr Duglas Mullan davon überzeugen könnt, sich Keegan anzuschließen - er sollte ihm einen Gefallen oder drei schulden.", sourceObjective = "Sprecht mit Duglas Mullan am Schmelztiegel des Gemetzels.", completion = "Iain hat Euch geschickt?\n\nIhr seht mir nicht wie ein Feuerbart aus. Warum sollte ich mir anhören, was Ihr zu sagen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27808] = { id = 27808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stur wie ein Doyle", description = "Die Reiter von Doyle wurden zuletzt gesehen, als sie auf die Bäume im Süden an der Grenze zum Obsidianwald zurannten. Sie sind ein sturer Haufen und es wird einiger Überredungskunst bedürfen, bevor sie sich uns anschließen.\n\nAm besten erzählt Ihr Keeland Doyle, dass Cailin Langhans bei uns in der Stadt Schutz gesucht hat. Keeland hat eine gewaltige Schwäche für sie und das könnte reichen, ihn davon zu überzeugen, all seine Jungs mitzubringen.", sourceObjective = "Sprecht mit Keeland Doyle im Hochlandwald.", completion = "Anscheinend haben die Doyles am meisten unter den Angriffen der Zwielichtdrachen gelitten.\n\nEs ist offensichtlich, dass sie bis zum Ende gekämpft haben: Alle Fußspuren der Reiter befinden sich in umittelbarer Nähe ihrer Greife. Es ist unwahrscheinlich, dass es Überlebende gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27809] = { id = 27809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbart brüllt", description = "Ihr müsst für mich noch zu Mackay und seinen Leuten gehen. Sie sind auf der anderen Seite des Verschlingenden Risses im Kriegslager Gorshak.\n\nNiemand vom Drachenmalklan hat den ersten Ansturm überlebt und Mackay will nun alles, was er kann aus ihrem Lager plündern, um unseren Kampf zu versorgen. Es sollte nicht schwer sein, sie zu überzeugen, aber wahrscheinlich wollen sie Hilfe, um da oben alles zu Ende zu bringen, bevor sie sich auf den Weg zu Keegan machen.\n\nTretet sie gewaltig von dem alten Iain in den Hintern, wenn es sein muss.", sourceObjective = "Sprecht mit Mackay Feuerbart am Kriegslager Gorshak.", completion = "Ist es schon so weit, ja? Dann helft uns, hier fertig zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27810] = { id = 27810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfgeist", description = "Keegan will, dass die Mullans an ihrer Seite fliegen, hm? Wenn es einen Zwerg gibt, für den ich fliegen würde, dann für ihn. Allerdings weiß ich nicht, warum er 'nen Außenstehenden schickt, um mich anzuwerben. Aus meiner Sicht ist das nich' wirklich höflich.\n\nIch schätze mal, dass Ihr keine 20 Sekunden gegen einen meiner Jungs durchhaltet - weder in der Bar noch auf dem Schlachtfeld. Beweist mir das Gegenteil. Besiegt einen von ihnen im Kampf und dann denke ich drüber nach, ob ich mit dem alten Keegan fliege.", sourceObjective = "Fordert einen der Greifenreiter der Mullans heraus und besiegt ihn.", progress = "Nee, ich werd' nicht gegen Euch kämpfen. Geht da rein und fordert einen meiner Jungs heraus, wenn Ihr den Mumm dazu habt.", completion = "Genau so! Gar nicht mal schlecht. Ihr habt ja tatsächlich etwas Kampfkraft in Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27811] = { id = 27811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geruch der Schlacht", description = "Lasst Euch nichts von Duglas vormachen, den Mullans juckt es in den Fingern, wieder zu fliegen - und wenn wir das für jemanden tun, dann für Feuerbart.\n\nWir haben unsere Greifen im Hochlandwald im Süden gelassen, damit sie dort jagen können und ein wenig Abstand von den Kampfgeräuschen bekommen. Sie hatten sich ein wenig Erholung verdient.\n\nWenn Ihr uns bald wieder in der Luft sehen wollt, seid Ihr gut beraten uns zu helfen diese Greife wieder hereinzuholen.\n\nNehmt dieses Stück verkohlte Hochlandbirke. Wir benutzen sie während der Ausbildung - sobald sie sie riechen, kommen sie wieder zurück zu uns.", sourceObjective = "Findet 8 Greife der Mullans und bringt sie zurück zu ihren Greifenreitern.", progress = "Ohne unsere Vögel werden wir Euch nicht viel nützen.", completion = "Gut gemacht. Ich habe immer das Gefühl, dass ein Teil von mir fehlt, wenn mein Greif nicht in der Nähe ist. Ich kann ja nicht für Duglas und den Rest seines Clans sprechen, aber ich werde bei Feuerbarts Ruf bereit sein, loszureiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27812] = { id = 27812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Loyalität des Klan Mullan", description = "Ihr habt Euren Standpunkt klargemacht. Keegan kann auf uns zählen. Wir treffen uns mit ihnen in der Stadt, sobald die Jungs alle versammelt sind.\n\nDafür, dass Ihr kein Wildhammer seid, seid Ihr ganz schön zäh. Offenbar gibt's da, wo Ihr herkommt, gute Weidegründe.\n\nAber ich hab' Euch noch nich' trinken sehen. Das ist der wahre Test.", sourceObjective = "Kehrt mit den Neuigkeiten über den Klan Mullan zu Iain Feuerbart auf Feuerbarts Friedhof zurück.", completion = "Ihr habt die Mullans. Gute Neuigkeiten! Die sind im Kampf mehr wert, als ihr Gewicht in Gold - und die sind nich' grad dürr.", sourceObjectiveStatus = "unverified-source-field" }
quests[27813] = { id = 27813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod würdig des Drachenmals", description = "Der Schattenhammer hat die Stadt ausgeplündert und die meisten der Angehörigen des Drachenmalklans, die darin lebten, getötet. Einige haben allerdings überlebt und die sind nich' grade erbaut darüber, dass wir uns Freiheiten mit ihren Vorräten herausnehmen.\n\nNicht, dass das von Bedeutung wäre.\n\nNaja, ich bin nich' grad erbaut darüber, dass sie meine Jungs angreifen. Tötet sie, jagt sie weg - is' mir egal, werdet sie nur irgendwie los.", sourceObjective = "Besiegt 6 Nachzügler des Drachenmals.", completion = "So ist es schon besser. Lasst uns die letzten Vorräte einsammeln und dann ab zu Keegan.", sourceObjectiveStatus = "unverified-source-field" }
quests[27814] = { id = 27814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles was wir kriegen können", description = "Zurückbleiben und mehr Waffen schmieden? Pff! Ein Schmiedehammer hat sich nie vor einer Schlacht gedrückt! Wer braucht schon eine sichere Umgebung, um Waffen zu schmieden? Außerdem gibt es da draußen tonnenweise Rohstoffe. Die Waffen des Drachenmals sind wertlos, aber man kann sie als Grundlage für echte Waffen nutzen. Bringt mir acht Waffen des Drachenmals, damit ich mit meiner Tochter echte Waffen aus ihnen schmieden kann.", sourceObjective = "Bringt 8 Waffen des Drachenmals zu Brom Schmiedehammer beim Kriegslager Gorshak.", progress = "Wie viele Waffen habt Ihr bisher?", completion = "Gut gemacht, Alter. Vielen Dank; ein bisschen Gold für Eure Mühen gibt es auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27815] = { id = 27815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas für die Jungs", description = "Ihr habt das Lager gesäubert und den Laufburschen für Schmiedehammer gespielt? Nicht schlecht für <'nen kleinen/'ne kleine:c> {class}. Bringt die hier zu Iain auf Feuerbarts Friedhof. Er sollte Euch für die gute Arbeit belohnen.", sourceObjective = "Bringt Schmiedehammers Waffen zu Iain Feuerbart auf Feuerbarts Friedhof.", progress = "Was haben wir denn hier?", completion = "Ha! Offenbar war ihr Beutezug richtig erfolgreich. Ich muss dem alten Schmiedehammer wohl eine Runde ausgeben, wenn wir mit dem Durcheinander hier fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27816] = { id = 27816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Persönliche Bitte", description = "Schade um die Doyles. Es grenzt allerdings schon an ein Wunder, wie viele von uns es herausgeschafft haben - insofern bin ich nicht sonderlich überrascht.\n\nDiese Rüpel in Donnermar sind Feiglinge. Sogar nachdem sie wussten, dass die Bitte von Keegan kam, wollten sie keinen Fuß aus ihrer Stadt setzen. Ich hab' allerdings die Moores an Bord geholt, also haben wir drei Klans.\n\nKeegan wollte nach Eurer Rückkehr mit Euch persönlich sprechen. Geht und sucht ihn in der Stadt auf.", sourceObjective = "Sprecht mit Keegan Feuerbart an Feuerbarts Patrouille.", completion = "Offensichtlich hattet Ihr Glück mit dem Zurückbringen der Reiter. Auch der Zeitpunkt war passend - wir haben gerade die Elementare zurückgeschlagen, also sollten wir genug Bewegungsfreiheit haben, um sofort einen Angriff zu führen.\n\nDanke, {name}. Ihr seid ein guter {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27817] = { id = 27817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hammer fallen lassen", description = "Dank Euch und Iain haben wir genug Reiter zusammen, um den Kampf wieder gegen den Schattenhammer führen zu können.\n\nWir sind darin ausgebildet, während des Flugs zu kämpfen, aber ein zweiter Reiter, der sich um die Sturmhammer kümmert, ist noch wirkungsvoller. Ich dachte, dass Euch diese Ehre gefallen könnte.\n\nSucht Euch einen Greif aus und schließt Euch dem Kampf an. Ihr solltet Euch allerdings beeilen - wir wollen vor Ablauf einer Stunde alles, was dem Schattenhammer angehört, von den schwebenden Felsen beseitigen.", sourceObjective = "Tötet 12 Zwielichtsturmbändiger und Servias Windterror. Benutzt dazu einen der Greifen von Feuerbarts Patrouille.", completion = "Genau so macht man das, mein Freund!\n\nJetzt, da wir wieder ein echtes Greifengeschwader haben, können wir den Kampf auf den Rest des Schattenhammers ausweiten. Ihr seid jederzeit willkommen, mit uns zu fliegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27818] = { id = 27818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glitschige Zeichen", description = "Ich habe mich hier schon niedergelassen, bevor Kraulsumpf gegründet wurde, um meine Tränke zu brauen und etwas Frieden zu finden. Ich kenne diesen Sumpf wie meine Westentasche.\n\nDie Fauna hat sich hier in letzter Zeit verändert. Diese geflügelten Schlangen, die Ihr vielleicht im Stagalsumpf gesehen habt, sind Windnattern, und die hat es hier schon seit Urzeiten nicht mehr gegeben.\n\nSie geben allerdings hervorragende Zutaten ab, wenn es die sind, für die ich sie halte. Seid so gut und bringt mir ein paar ihrer Herzen, okay?", sourceObjective = "Sammelt 5 intakte Stagalsumpfnatternherzen.", progress = "Seid Euch nicht so zimperlich.", completion = "Na werfen wir doch mal einen Blick drauf...\n\nMmm, oje. Ich hatte befürchtet, dass es sich darum handelt. Sie sind zwar noch brauchbar, aber es ist kein schöner Gedanke, solche Biester in der Nachbarschaft zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27819] = { id = 27819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST - RVM" }
quests[27821] = { id = 27821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs und Menschen", description = "Während der Krieg die ganze Welt überzieht, ist das letzte, was wir brauchen, eine Hordensiedlung gleich nebenan. Das Rotkammgebirge, der Dämmerwald, sogar Elwynn selbst: alle sind nur einen Tagesmarsch von hier entfernt.\n\nWir haben den ersten Angriff gestartet, und ich habe nicht vor, der Horde eine Atempause zu lassen. Betrachtet Euch als im Einsatz. Schnappt Euch eine Waffe, stoßt zum Rest der Truppen draußen im Blutsumpf, und fangt an, Orcs zu töten.\n\nMeldet Euch bei mir zurück, nachdem Ihr etwas Schaden angerichtet habt. Ich will Euch lebend zurück... und das ist ein Befehl. Weggetreten!", sourceObjective = "Tötet 8 Krieger von Steinard.", completion = "Mehr Schmutzflecken als Blutflecken... das sehe ich gern. Sieht so aus, als hättet Ihr das Zeug für den Krieg, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27822] = { id = 27822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trampel", description = "Ich will, dass der Sieg vollkommen abgesichert wird. Es reicht nicht, genügend Material zu haben, wir müssen sicherstellen, dass der Feind nichts hat.\n\nSteinards Streitkräfte verlassen sich auf das Holz, das aus den umliegenden Wäldern gesammelt wird. Die Orcpeons, die das Holz fällen, mögen keine Krieger sein, aber sie kennen nur Hass auf die Menschen.\n\nZeigt keine Gnade. Ich will, dass diese Peons getötet werden und dass der Holznachschub nach Steinard vollkommen abgeschnitten wird.", sourceObjective = "Tötet 5 Steinardpeons.", completion = "Während Eurer Abwesenheit gab es Schläge gegen unsere eigenen Holznachschublinien. Dadurch sollten wir in etwa die gleichen Mengen gesammelt haben.\n\nGute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
